(window.GIM_TS=window.GIM_TS||{})["Avodah Zarah.1"]={"from":24,"a":[["ומבררים את האמור במשנתנו, \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"איצטרובלין\"?\u0004 הוא הצמח הקרוי \u0003תורניתא. ורמינהו\u0004 \u0005[ומשליכים,\u0006 מקשים מברייתא\u0005]\u0006 ששנינו בה: \u0003הוסיפו עליהן\u0004 לעניין איסור שביעית: \u0003אלכסין ואיצטרובלין, מוכססין ובנות שוח; ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לפרש ש\u0003איצטרובלין\u0004 פירושו \u0003תורניתא, תורניתא מי איתא\u0004 \u0005[האם יש]\u0006 בה איסור \u0003בשביעית?\u0004","\u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003זה הכלל: כל שיש לו עיקר\u0004 שיש לו שורשים — \u0003יש לו\u0004 דין \u0003שביעית, וכל שאין לו עיקר\u0004 — \u0003אין לו\u0004 דין \u0003שביעית,\u0004 ותורניתא זו אין לה שורשים! \u0003אלא אמר רב ספרא:\u0004 תורניתא היא \u0003פירי דארזא\u0004 \u0005[פירות הארז].\u0006 \u0003וכן כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל \u0003אמר\u0004 בשם \u0003ר' אלעזר:\u0004 איצטרובלין הוא \u0003פירי דארזא\u0004 \u0005[פירות הארז].\u0006","ומבררים את זיהוים של שאר הדברים ששנינו במשנה: \u0003\"בנות שוח\"\u0004 — \u0003אמר רבה בר בר חנה אמר ר' יוחנן: תאיני חיוראתא\u0004 \u0005[תאנים לבנות].\u0006 \u0003\"ופטוטרות\"\u0004 — \u0003אמר רבה בר בר חנה אמר ר' יוחנן:\u0004 אין הכוונה למין נוסף, אלא לומר שמיני הפירות שנאסרו במכירה \u0003בפטוטרותיהן שנו\u0004 שהם אסורים, כאשר הם נמכרים עם העוקצים שלהם, ולא כאשר הם קצוצים.","\u0003\"לבונה\"\u0004 — \u0003אמר ר' יצחק אמר ר' שמעון בן לקיש:\u0004 הכוונה היא דווקא ל\u0003לבונה זכה,\u0004 שבה משתמשים לשם קטורת לעבודה זרה. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003ומכולן\u0004 מכל המינים האסורים \u0003מוכרין להן חבילה,\u0004 כמות גדולה, שהיא בוודאי מיועדת לסחורה ולא להקרבה. \u0003וכמה\u0004 הוא משקלה של \u0003חבילה? פירש ר' יהודה בן בתירא: אין חבילה\u0004 \u0003פחותה מ\u0004משקל \u0003שלשה מנין.\u0004","ושואלים: \u0003וליחוש דלמא אזיל ומזבין לאחריני ומקטרי\u0004 \u0005[ונחשוש שמא הולך\u0006 קונה זה \u0005ומוכר לאחרים, ו\u0006הם \u0005מקטירים]!\u0006 \u0003אמר אביי:\u0004 בוודאי הדבר ייתכן, אלא שעל האיסור של \u0003\"לפני\u0004 עיור לא תתן מכשול\" (ויקרא יט, יד) \u0003מפקדינן\u0004 \u0005[מצווים אנו],\u0006 שלא לגרום להם לעבוד עבודה זרה על ידינו, \u0003אלפני דלפני לא מפקדינן\u0004 \u0005[על \"לפני\" של \"לפני\", אין אנו מצווים].\u0006","שנינו במשנה: \u0003ותרנגול לבן\u0004 אסור למכור לגוי. \u0003אמר ר' יונה אמר ר' זירא אמר רב זביד, ואיכא דמתני\u0004 \u0005[ויש ששונים]\u0006 רק \u0003אמר ר' יונה אמר ר' זירא:\u0004 אם הקונה אומר סתם \u0003\"תרנגול למי\",\u0004 כלומר, למי יש תרנגול למכירה — \u0003מותר למכור לו\u0004 גם \u0003תרנגול לבן,\u0004 משום שנראה שאינו מקפיד דווקא בלבן. אבל אם הוא שואל \u0003\"תרנגול לבן למי\"\u0004 — \u0003אסור למכור לו תרנגול לבן.\u0004","ומקשים על כך, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יהודה אומר: מוכר הוא לו תרנגול לבן בין התרנגולין\u0004 האחרים. ויש לשאול: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אילימא דקאמר\u0004 \u0005[אם תאמר שהוא אומר]\u0006 \u0003\"תרנגול לבן למי, תרנגול לבן למי\",\u0004 אם כן, \u0003אפילו\u0004 תרנגול לבן \u0003בין התרנגולין\u0004 — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 ימכור, שהרי הודיע שרצונו בתרנגול לבן!","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר \u0003דקא אמר\u0004 \u0005[שהוא אומר]\u0006 \u0003\"תרנגול למי, תרנגול למי\", ואפילו הכי\u0004 \u0005[כך],\u0006 \u0003לר' יהודה,\u0004 אם מוכר תרנגול לבן זה \u0003בין התרנגולין\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מותר, \u0003בפני עצמו\u0004 — \u0003לא, ולתנא קמא\u0004 \u0005[ו\u0006לדעת \u0005התנא הראשון]\u0006 שאוסר — \u0003אפילו בין התרנגולין נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 ימכור לו!","\u0003אמר רב נחמן בר יצחק: הכא במאי עסקינן\u0004 \u0005[כאן\u0006 במשנה \u0005במה אנו עוסקים]?\u0006 לא כשמבקש תרנגול סתם, שאז מותר לתת לו לבן לדעת הכל, אלא \u0003כגון דאמר\u0004 \u0005[שאומר]\u0006 \"מכור לי \u0003זה וזה\",\u0004 כלומר, שהיו בידי היהודי תרנגולים רבים, והוא מצביע על כמה מהם, וביניהם גם לבן.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא במפורש \u0005גם כן כך],\u0006 \u0003אמר ר' יהודה: אימתי\u0004 אסור? \u0003בזמן שאמר\u0004 \"מכור לי \u0003תרנגול זה לבן\",\u0004 שהזכיר שרצונו בתרנגול לבן, \u0003אבל אם אמר\u0004 \"מכור לי \u0003זה וזה\"\u0004 — \u0003מותר.\u0004 ומוסיפה הברייתא: \u0003ואפילו אמר\u0004 רק \u0003\"תרנגול זה\",\u0004 והצביע על תרנגול לבן, אם היה זה \u0003גוי שעשה משתה לבנו או שהיה לו חולה בתוך ביתו\u0004 — \u0003מותר\u0004 למכור לו, שניכר הדבר שקונה לשמחת בנו או לרפואת החולה.","אגב שהובאה ברייתא זו מקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003גוי שעשה משתה לבנו, אינו אסור אלא אותו היום ואותו האיש בלבד.\u0004 ומכאן נדייק: \u0003אותו היום ואותו האיש מיהא\u0004 \u0005[על כל פנים]\u0006 \u0003אסור! אמר רב יצחק בר רב משרשיא: בטווזיג\u0004","\u0003תנן\u0004 \u0005[בסעודת רעות שנינו]\u0006 שאיננו משתה חתונה, אלא סעודה של ידידות, ואין מקריבים בה קרבנות. ושבים לדון בדבריו של ר' זירא, שגוי המבקש תרנגול סתם מותר למכור לו לבן. ומקשים ממה ששנינו במשנה: \u0003ושאר כל הדברים, סתמן מותר, ופירושן אסור.\u0004 ויש לברר: \u0003מאי\u0004 \u0005[מה]\u0006 בדיוק הכוונה ב\u0003\"סתמן\" ומאי\u0004 \u0005[ומה]\u0006 הכוונה ב\u0003\"פירושן\"? אילימא\u0004 \u0005[אם תאמר]:\u0006 \u0003סתמא\u0004 \u0005[סתם]\u0006 — \u0003דקאמר חיטי חוורתא\u0004 \u0005[שהוא אומר\u0006 שרוצה \u0005חיטים לבנות],\u0006 \u0003פירושן\u0004 — \u0003דקאמר\u0004 \u0005[שהוא אומר]\u0006 שהוא צריך אותן \u0003לעבודה זרה,\u0004"],["הרי \u0003לא\u0004 על \u0003סתמן צריכא למימר דמזבנינן\u0004 \u0005[צריך לומר שמוכרים אנו],\u0006 להם, \u0003ולא\u0004 על \u0003פירושן צריכא למימר דלא מזבנינן\u0004 \u0005[צריך לומר שאין אנו מוכרים],\u0006 שדברים אלה ברורים מעצמם! \u0003אלא\u0004 יש להסביר: \u0003סתמן\u0004 פירושו \u0003דקאמר\u0004 \u0005[שהוא אומר]\u0006 שרצונו לקנות \u0003חיטי\u0004 \u0005[חיטים],\u0006 \u0003פירושן\u0004 — \u0003דקאמר חוורתא\u0004 \u0005[שהוא אומר\u0006 שרצונו בחיטים \u0005לבנות]\u0006 שהן משמשות לעבודה זרה.","ומכאן נדייק: \u0003מכלל\u0004 ש\u0003תרנגול\u0004 שאמרו במשנה שלא למכור — \u0003אפילו סתמן נמי\u0004 \u0005[גם כן]\u0006 כשלא פירש לבן, \u0003לא\u0004 ימכור להם, שלא כדברי ר' זירא! ובתשובה לכך \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003לעולם סתמן\u0004 פירושו \u0003דקאמר חיטי חוורתא\u0004 \u0005[שאומר\u0006 הגוי שרצונו ב\u0005חיטים לבנות],\u0006 \u0003פירושן\u0004 — \u0003דקאמר\u0004 \u0005[שהוא אומר]\u0006 שצריך אותן \u0003לעבודה זרה;\u0004","\u0003ופירושן אצטריכא ליה\u0004 \u0005[הוצרך לו\u0006 לומר\u0005],\u0006 ומדוע? שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003האי גברא\u0004 \u0005[אדם זה]\u0006 באמת \u0003לאו\u0004 \u0005[לא]\u0006 \u0003לעבודה זרה קא בעי\u0004 \u0005[הוא צריך]\u0006 את החיטים, שהרי אין דרכם בכך, \u0003אלא מיבק הוא דאביק\u0004 \u0005[אדוק הוא]\u0006 \u0003בעבודה זרה,\u0004 \u0003וסבר\u0004 \u0005[\u0006והוא \u0005סבור]:\u0006 \u0003כי היכי דההוא גברא אביק ביה כולי עלמא נמי אביקו\u0004 \u0005[כמו שאותו אדם,\u0006 הוא עצמו, \u0005דבוק בה, כולם גם כן דבוקים\u0006 בה\u0005],\u0006 ולכן הוא אומר בלבו: \u0003אימא הכי כי היכי דליתבו לי\u0004 \u0005[אומר כך,\u0006 שרצוני לעבודה זרה, \u0005כדי שיתנו לי],\u0006 אף שבאמת אין הם לעבודה זרה, ויהיה מותר, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שכיון שפירש לעבודה זרה — אסור, שיש לחשוש שלכך באמת הוא מתכוון.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי:\u0004 אם אומר הגוי ושואל בין המוכרים: \u0003\"תרנגול לבן קטוע למי\u0004 יש למכור\", \u0003מהו למכור לו תרנגול לבן שלם?\u0004 וצדדי השאלה, \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 \u0003מדקאמר\u0004 \u0005[מכיון שהוא אומר]\u0006 \u0003קטוע,\u0004 סימן ש\u0003לאו\u0004 \u0005[לא]\u0006 \u0003לעבודה זרה קבעי\u0004 \u0005[הוא צריך]\u0006 אותו, שהרי אינם מקריבים קרבן חסר אבר, ויהיה מותר למכור לו, \u0003או דלמא איערומי קא מערים\u0004 \u0005[שמא מערים הוא]\u0006 שהוא יודע שלא ימכרו לו שלם אם יבקש זאת, והוא סבור שהואיל וקטוע אינו מצוי, יקבל מהם שלם, ואסור למכור לו?","וממשיך רב אשי: \u0003אם תימצי\u0004 (תמצא) \u0003לומר האי איערומי הוא דקא מערים\u0004 \u0005[\u0006במקרה שכ \u0005זה מערים\u0006 הוא\u0005],\u0006 ואסור הדבר, יש לשאול: אם שאל \u0003\"תרנגול לבן למי, תרנגול לבן למי\", ויהבו ליה\u0004 \u0005[ונתנו לו]\u0006 תרנגול \u0003שחור ושקל\u0004 \u0005[ולקח],\u0006 \u0003ויהבו ליה\u0004 \u0005[ונתנו לו]\u0006 תרנגול \u0003אדום ושקל\u0004 \u0005[ולקח],\u0006 \u0003מהו למכור לו לבן\u0004 גם כן? וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 \u0003כיון דיהבו\u0004 \u0005[שנתנו]\u0006 לו \u0003שחור ושקל\u0004 \u0005[ולקח],\u0006 \u0003אדום ושקל\u0004 \u0005[ולקח],\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003לעבודה זרה קא בעי\u0004 \u0005[הוא צריך],\u0006 \u0003או דלמא איערומי קא מערים\u0004 \u0005[שמא מערים הוא]?\u0006 שאלה זו לא נפתרה, ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","שנינו במשנה \u0003ר' מאיר אומר: אף דקל\u0004 טב וחצב אין מוכרים לגוים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא לאבימי: גמירי\u0004 \u0005[למודים אנו]\u0006 במסורת, שמסכת \u0003עבודה זרה\u0004 של \u0003אברהם אבינו ארבע מאה פירקי הויין\u0004 \u0005[ארבע מאות פרקים היו\u0006 בה\u0005],\u0006 \u0003ואנן חמשה תנן\u0004 \u0005[ו\u0006אילו \u0005אנו חמישה\u0006 פרקים בלבד \u0005אנו שונים\u0006 בה\u0005],\u0006 \u0003ו\u0004בכל זאת \u0003לא ידעינן מאי קאמרינן\u0004 \u0005[אין אנו יודעים מה אנו אומרים].\u0006","ושאל אותו: \u0003ומאי קשיא\u0004 \u0005[ומה קשה],\u0006 מה אינך מבין במשנתנו? אמר לו: \u0003דקתני\u0004 \u0005[ששנינו],\u0006 \u0003ר' מאיר אומר: אף דקל טב, חצב ונקלס אסור למכור לגוים.\u0004 ונדייק: \u0003דקל טב\u0004 \u0005[טוב]\u0006 \u0003הוא דלא מזבנינן\u0004 \u0005[שאין אנו מוכרים],\u0006 \u0003הא דקל ביש מזבנינן\u0004 \u0005[אבל דקל רע מוכרים אנו].\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 להלן: \u0003אין מוכרין להם במחובר לקרקע\u0004 כל דבר! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"דקל טב\u0004 \u0005[טוב]\u0006 \u0003\"? פירות\u0004 של \u0003דקל טב\u0004 \u0005[טוב]\u0006 שהם תלושים. \u0003וכן אמר רב הונא: פירות דקל טב\u0004 \u0005[טוב].\u0006","שנינו במשנה: \u0003\"חצב\",\u0004 ומסבירים שהוא \u0003קשבא\u0004 \u0005[מין תמרים].\u0006 ובפירוש \u0003\"נקלס\"\u0004 מסופר, \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' חמא בר יוסף: קורייטי. אמר ליה\u0004 \u0005[לו]\u0006 אביי לרב דימי: תנן \u0005[שנינו\u0006 במשנה\u0005]\u0006 \u0003\"נקלס\" ולא ידעינן\u0004 \u0005[ואין אנו יודעים]\u0006 \u0003מהו, ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 \u0003קורייטי, ולא ידעינן\u0004 \u0005[ואין אנו יודעים]\u0006 מהו, אם כן \u0003מאי אהנית לן\u0004 \u0005[מה הועלת לנו],\u0006 אם גם את הפירוש איננו יודעים? \u0003אמר ליה\u0004 \u0005[להם]:\u0006 \u0003אהנאי לכו\u0004 \u0005[אני הועלתי לכם],\u0006 \u0003דכי אזלת התם\u0004 \u0005[שכאשר תלך לשם]\u0006 לארץ ישראל \u0003אמרת להו\u0004 \u0005[אומר אתה להם]\u0006 \u0003\"נקלס\"\u0004 — \u0003ולא ידעי\u0004 \u0005[ואינם יודעים],\u0006 \u0003אמרת להו\u0004 \u0005[אומר אתה להם]\u0006 \u0003\"קורייטי\"\u0004 — \u0003וידעי, וקא מחוו לך\u0004 \u0005[ויודעים, ומראים לך\u0006 מהו\u0005].\u0006","\u0003מקום שנהגו למכור בהמה דקה לגוים\u0004 — \u0003מוכרין, מקום שנהגו שלא למכור\u0004 — \u0003אין מוכרין. ובכל מקום אין מוכרין להם בהמה גסה,\u0004 שנמצא עובד בה בשבת, וישראל מצווה על שביתת בהמתו. ואף לא \u0003עגלים וסייחים,\u0004 בין \u0003שלמין ו\u0004בין \u0003שבורין\u0004 שאינם יכולים לעשות מלאכה. \u0003ר' יהודה מתיר בשבורה, ובן בתירא מתיר בסוס.\u0004","מדברי המשנה שבמקום שנהגו שלא למכור בהמה דקה אין מוכרים, מדייקים: \u0003למימרא\u0004 \u0005[לומר]\u0006 מכאן \u0003דאיסורא ליכא\u0004 \u0005[שאיסור אין\u0006 בכך\u0005],\u0006 אלא רק \u0003מנהגא\u0004 \u0003הוא דאיכא\u0004 \u0005[מנהג הוא שיש],\u0006 \u0003היכא דנהיג\u0004 \u0005[במקום שנוהגים]\u0006 \u0003איסור\u0004 — \u0003נהוג\u0004 \u0005[נוהגים],\u0006 \u0003היכא דנהיג\u0004 \u0005[במקום שנוהגים]\u0006 \u0003היתר\u0004 — \u0003נהוג\u0004 \u0005[נוהגים].\u0006","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו כאיסור, ולא כמנהג: \u0003אין מעמידין בהמה בפונדקאות של גוים, מפני שחשודין על הרביעה,\u0004 וכיוון שהדבר אסור להם הרי זה בכלל הציווי \"לפני עיור לא תתן מכשול\". \u0003אמר רב:\u0004 הלכה זו של העמדת בהמה בפונדקאות תלויה בהלכה שבמשנתנו, \u0003מקום שהתירו למכור\u0004 לגוים, הרי זה משום שבאותו מקום אינם חשודים על רביעת בהמה דקה, ובמקום כזה גם \u0003התירו לייחד\u0004 עימם בהמה דקה בפונדקאות. וכן לצד האחר, \u0003מקום שאסרו לייחד\u0004 בפונדקאות \u0003אסרו\u0004 גם \u0003למכור.\u0004"],["\u0003ור' אלעזר אומר: אף במקום שאסרו לייחד, מותר למכור. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 שאם ימכור לו שוב אין חשש לרביעה, לפי ש\u0003גוי חס על בהמתו שלא תעקר\u0004 (תיעשה עקרה) מחמת הרביעה, ולכן אין הוא רובע את בהמתו שלו. אבל ליחד אסור, לפי שחשודים הם לרבוע בהמות של ישראל. ומעירים: \u0003ואף רב הדר ביה\u0004 \u0005[חזר בו]\u0006 מדבריו, ש\u0003אמר רב תחליפא אמר רב שילא בר אבימי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: גוי חס על בהמתו שלא תעקר.\u0004","שנינו במשנה: \u0003ובכל מקום אין מוכרין בהמה גסה כו'.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003נהי\u0004 \u0005[אם אמנם]\u0006 ש\u0003לרביעה לא חיישינן\u0004 \u0005[אין אנו חוששים],\u0006 ואולם \u0003מעביד ביה מלאכה חיישינן\u0004 \u0005[לעשיית מלאכה בה\u0006 בשבת \u0005אנו חוששים].\u0006 ושואלים: מדוע נחשוש לכך?","\u0003וניעביד\u0004 \u0005[ושיעשה]\u0006 בה מלאכה, \u0003כיון דזבנה קנייה\u0004 \u0005[שקנאה\u0006 הגוי \u0005קנה אותה\u0006 לעצמו\u0005]\u0006 לכל דבר, ומותר לו לעבוד בה בשבת! ומשיבים: נאסרה מכירה \u0003גזירה משום שאלה\u0004 שמא יבוא להשאיל את הבהמה, או \u0003משום שכירות,\u0004 ואז יעשה בה מלאכה בזמן שהיא שייכת לישראל.","ומקשים שוב: הרי גם \u0003שאלה קנייה\u0004 \u0005[קונה אותה]\u0006 לשואל, \u0003ו\u0004גם \u0003אגרא קנייה\u0004 \u0005[שכירות קונה אותה]\u0006 לשוכר, אמנם לא לצמיתות אבל לשעתה, ובאותה שעה אינה שלו אלא של הגוי, ומדוע לא יעבוד בה?","\u0003אלא אמר רמי בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' ייבא:\u0004 האיסור למכור הוא \u0003גזירה\u0004 \u0003משום נסיוני\u0004 \u0005[נסיונות]\u0006 שעושים לפני מכירת הבהמה, \u0003דזמנין דזבנה לה ניהליה\u0004 \u0005[שפעמים שהוא מוכר אותה לו]\u0006 \u0003סמוך לשקיעת החמה דמעלי שבתא\u0004 \u0005[של ערב שבת],\u0006 \u0003ואמר ליה\u0004 \u0005[ואומר לו]:\u0006 \u0003תא נסייה ניהליה\u0004 \u0005[בוא נסה אותה],\u0006 \u0003ושמעה ליה לקליה ואזלא מחמתיה\u0004 \u0005[ו\u0006הבהמה \u0005שומעת את קולו של\u0006 בעליה היהודי \u0005והולכת בגללו],\u0006 \u0003וניחא ליה דתיזל\u0004 \u0005[ונוח לו שתלך],\u0006 שהרי הוא רוצה שיראה הגוי שהיא מסוגלת לעבודה, \u0003והוה ליה\u0004 \u0005[ונמצא]\u0006 \u0003מחמר אחר בהמתו בשבת, והמחמר אחר בהמתו בשבת\u0004 — \u0003חייב חטאת.\u0004","על מה שהנחנו ששכירות קונה, \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: ושכירות מי קניא\u0004 \u0005[האם\u0006 היא \u0005קונה]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אף במקום שאמרו\u0004 שמותר \u0003להשכיר\u0004 דירה לגוי — \u0003לא לבית דירה אמרו, מפני ש\u0004הגוי \u0003מכניס לתוכו עבודה זרה. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003שכירות קניא\u0004 \u0005[קונה],\u0006 \u0003האי כי קא מעייל\u0004 \u0005[\u0006גוי \u0005זה כאשר הוא מכניס]\u0006 — \u0003לביתיה קא מעייל\u0004 \u0005[לביתו הוא מכניס]\u0006 ומה איכפת ליהודי בעל הדירה?","ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003עבודה זרה דחמירא\u0004 \u0005[ש\u0006היא \u0005חמורה]\u0006 ביותר, ומחמירים בה אף בדבר שאינו שייך לו בשלימות, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ולא תביא תועבה אל ביתך\"\u0004 (דברים ז, כו), ובית זה עדיין שמו של היהודי עליו.","וכן \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב משרשיא: ושכירות מי קניא\u0004 \u0005[האם\u0006 היא \u0005קונה]?\u0006 \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003ישראל ששכר פרה מכהן\u0004 — \u0003יאכילנה כרשיני\u0004 (מין ירק) \u0003תרומה,\u0004 לפי שהיא בהמת כהן ומותר להאכילה תרומה, \u0003ו\u0004להיפך, \u0003כהן ששכר פרה מישראל, אף על פי ש\u0004לפי ההסכם \u0003מזונותיה עליו\u0004, שהכהן השוכר הוא החייב במזונותיה — מכל מקום \u0003לא יאכילנה כרשיני תרומה\u0004 לפי שהיא פרת ישראל.","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003שכירות קניא\u0004 \u0005[קונה],\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא יאכילנה\u0004 הכהן כרשיני תרומה? הלוא \u0003פרה דידיה\u0004 \u0005[שלו]\u0006 \u0003היא\u0004 לפי שעה! \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003שכירות לא קניא\u0004 \u0005[אינה קונה].\u0006 ומעירים: \u0003והשתא דאמרת\u0004 \u0005[ועכשיו שאתה אומר]\u0006 \u0003שכירות לא קניא\u0004 \u0005[אינה קונה]\u0006 ואינה מפקעת את הדבר מרשות בעליו, אם כן אפשר לפרש כמו שפירשנו מתחילה, שאין מוכרים בהמה גסה לגוי \u0003גזירה משום שכירות, וגזירה משום שאלה, וגזירה משום נסיוני\u0004 (נסיונות).","מסופר, \u0003רב אדא שרא לזבוני חמרא אידא דספסירא\u0004 \u0005[התיר למכור חמור על ידי ספסר]\u0006 יהודי, והסביר: \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום נסיוני\u0004 — \u0003הא לא ידעה לקליה דאזלא מחמתיה\u0004 \u0005[הרי אינה מכירה את קולו\u0006 של הספסר \u0005שתלך בגללו],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003משום שאלה ושכירות\u0004 — \u0003כיון\u0004 ש\u0003לא דידיה\u0004 \u0005[שלו]\u0006 \u0003היא, לא מושיל ולא מוגר\u0004 \u0005[אינו משאיל ואינו משכיר\u0006 אותה\u0005],\u0006 \u0003ועוד\u0004 טעם שאינו משאיל או משכיר — \u0003משום\u0004 ש\u0003לא ניגלי ביה מומא\u0004 \u0005[יתגלה בה מום]\u0006 בתוך זמן השכירות והשאלה, שהרי הוא מעוניין למכור את הבהמה.","ועוד מסופר, \u0003רב הונא זבין ההיא\u0004 \u0005[מכר אותה]\u0006 \u0003פרה לגוי, אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא: מאי טעמא עבד מר הכי\u0004 \u0005[מה טעם עשה אדוני כך]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא: \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003לשחיטה זבנה\u0004 \u0005[קנה אותה]\u0006 ולא כדי לעשות בה מלאכה."],["והוסיף: \u0003ומנא תימרא דאמרינן כי האי גוונא\u0004 \u0005[ומנין אתה אומר שאנו אומרים כגון זה]\u0006 שתולים להקל במכירה, ואין חוששים משום \"לפני עיור\", אף כאשר יש אפשרות של מכשול? \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005],\u0006 \u0003בית שמאי אומרים: לא ימכור אדם\u0004 לחבירו \u0003פרה החורשת ב\u0004שנת \u0003שביעית,\u0004 משום שמן הסתם הקונה מתכוון לחרוש בפרה חורשת זו, דבר האסור בשנה השביעית, \u0003ובית הלל מתירין,\u0004 וטעמם — \u0003מפני שיכול\u0004 הקונה \u0003לשוחטה,\u0004 ולאו דווקא לחרוש בה. משמע שאנו תולים בכך ואין אוסרים.","\u0003אמר רבה: מי דמי\u0004 \u0005[האם\u0006 הדברים \u0005דומים]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 לענין שביעית, \u0003אין\u0004 \u0003אדם מצווה על שביתת בהמתו בשביעית,\u0004 ואין איסור בעצם עבודתה של הבהמה, ואם משום הכשלה של חבירו — יכול הוא לתלות שאינו מתכוון כלל לעבוד בה. אבל \u0003הכא\u0004 \u0005[כאן]\u0006 לעניין מכירה לגוי, הרי \u0003אדם מצווה על שביתת בהמתו בשבת,\u0004 ואם תעבוד — עבירה שלו היא, ואין לו להיכנס אפילו לספק עבירה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבה: \u0003וכל היכא\u0004 \u0005[מקום]\u0006 ש\u0003אדם מצווה\u0004 על שביתת דבר מקנייניו — \u0003אסור\u0004 למכור למרות הספק? \u0003והרי שדה,\u0004 ש\u0003אדם מצווה על שביתת שדהו בשביעית, ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]\u0006 בכל זאת, \u0003בית שמאי אומרים: לא ימכור אדם שדה ניר\u0004 (שדה חרוש) \u0003בשביעית\u0004 משום שמן הסתם יזרע בו הקונה בשנה זו, \u0003ובית הלל מתירין, מפני שיכול להובירה\u0004 (להשאירה בורה) ולא לעבד אותה. משמע שאנו תולים באפשרות זו, אף שאדם מוזהר על שביתת שדהו!","ומצד אחר \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי: וכל היכא\u0004 \u0005[מקום]\u0006 ש\u0003אין אדם מצווה\u0004 על שביתת דבר מקנייניו — \u0003שרי\u0004 \u0005[מותר]\u0006 לו למכור? \u0003והרי כלים,\u0004 ש\u0003אין אדם מצווה על שביתת כלים בשביעית, ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005],\u0006 \u0003אלו הן כלים שאין אדם רשאי למוכרן בשביעית: המחרישה וכל כליה\u0004 כל הכלים הנלווים לה, וכן \u0003העול\u0004 ששמים על פרה כדי לרתום אותה למחרישה, \u0003והמזרה\u0004 שזורים בו את התבואה, \u0003והדקר\u0004 שמשתמשים בו לעבודת אדמה!","\u0003אלא אמר רב אשי: כל היכא דאיכא למיתלא\u0004 \u0005[מקום שיש\u0006 אפשרות \u0005לתלות]\u0006 בדבר אחר — \u0003תלינן\u0004 \u0005[אנו תולים]\u0006 \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 \u0003ש\u0004הוא \u0003מצווה, וכל היכא דליכא למיתלי\u0004 — \u0005[מקום שאין לתלות]\u0006 בדבר אחר — \u0003לא תלינן\u0004 \u0005[אין אנו תולים]\u0006 \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003אינו מצווה.\u0004","מסופר, \u0003רבה זבין ההוא חמרא\u0004 \u0005[מכר חמור אחד]\u0006 \u0003לישראל החשיד\u0004 \u0005[החשוד]\u0006 \u0003למכור\u0004 בהמה גסה \u0003לגוי, אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבה: \u0003מאי טעמא עבד מר הכי\u0004 \u0005[מה טעם עשה אדוני כך]?\u0006 הרי ילך זה וימכרנו לגוי! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003לישראל זביני\u0004 \u0005[מוכר אני].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003והא אזיל ומזבין ליה\u0004 \u0005[והרי\u0006 הוא \u0005הולך ומוכר אותו]\u0006 \u0003לגוי!\u0004 אמר לו רבה כתשובה לכך: וכי \u0003לגוי קא מזבין\u0004 \u0005[הוא מוכר],\u0006 \u0003לישראל לא קא מזבין\u0004 \u0005[אינו מוכר]?\u0006 אם כן, אין לומר בוודאות שמוכר דווקא לגוי!","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 אביי ממה ששנינו: \u0003מקום שנהגו למכור בהמה דקה לכותים\u0004 — \u0003מוכרין, שלא למכור\u0004 — \u0003אין מוכרין.\u0004 ויש לשאול: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דחשידי ארביעה\u0004 \u0005[ש\u0006הכותים \u0005חשודים על רביעה],\u0006 \u0003ומי חשידי\u0004 \u0005[והאם חשודים\u0006 הם\u0005]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אין מעמידין בהמה בפונדקאות של גוים,\u0004 בהמות \u0003זכרים אצל\u0004 אנשים \u0003זכרים\u0004 (גברים), מחשש שירבעו אותן, וכן אין מעמידים בהמות \u0003נקבות אצל נקבות\u0004 (נשים), למרות שאין חשש לרביעה, \u0003ואין צריך לומר\u0004 שאין מעמידים בהמות \u0003נקבות אצל זכרים\u0004 (זכרים) \u0003ו\u0004בהמות \u0003זכרים אצל נקבות.\u0004","\u0003ואין מוסרין בהמה לרועה שלהן, ואין מייחדין\u0004 (מתייחדים) \u0003עמהם\u0004 במקום מבודד, מחשש סכנה, \u0003ואין מוסרין להם תינוק ללמדו ספר וללמדו אומנות\u0004 (מקצוע). \u0003אבל מעמידין בהמה בפונדקאות של כותים, זכרים אצל נקבות ונקבות אצל זכרים, ואין צריך לומר זכרים אצל זכרים ונקבות אצל נקבות,\u0004 משום שאין חוששים שהם עוברים על התורה ורובעים בהמה.","\u0003ו\u0004כן \u0003מוסרין בהמה לרועה שלהן, ומייחדין עמהם, ומוסרין להם תינוק ללמדו ספר וללמדו אומנות; אלמא לא חשידי\u0004 \u0005[מכאן שאין\u0006 הם \u0005חשודים].\u0006","\u0003ועוד תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אין מוכרין להם\u0004 לגויים \u0003לא זיין\u0004 (נשק) \u0003ולא כלי זיין\u0004 (כלי עזר של נשק), \u0003ואין משחיזין להן את הזיין, ואין מוכרין להן לא סדן\u0004 (סד לרגלי אסירים), \u0003ולא קולרין\u0004 (שרשרות ברזל לצוואר), \u0003ולא כבלים, ולא שלשלאות של ברזל,\u0004 ובענין זה שווים \u0003אחד גוי ואחד כותי.\u0004","ונברר: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר שאין מוכרים לכותים\u0005]?\u0006 \u0003אי נימא דחשידי\u0004 \u0005[אם נאמר\u0006 מפני \u0005ש\u0006הם \u0005חשודים]\u0006 על \u0003שפיכות דמים, ומי חשידי\u0004 \u0005[והאם\u0006 הם \u0005חשודים]?\u0006 \u0003האמרת\u0004 \u0005[הרי אמרת]:\u0006 \u0003ומייחדין עמהן,\u0004 משמע שאין חוששים לשפיכות דמים! \u0003אלא\u0004 וודאי אסור למכור להם \u0003משום דאתי לזבונה\u0004 \u0005[שיבוא למוכרה]\u0006 \u0003לגוי.\u0004 ואם כן כיצד מותר למכור חמור לישראל החשוד למוכרו לגוי?","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003כותי לא עביד\u0004 \u0005[אינו עושה]\u0006 \u0003תשובה\u0004 ובודאי עשוי למכור, \u0003ישראל עביד\u0004 \u0005[עושה]\u0006 \u0003תשובה,\u0004 ואולי לא ימכור, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב נחמן אמר רבה בר אבוה: כדרך שאמרו אסור למכור לגוי, כך אסור למכור לישראל החשוד למכור לגוי,\u0004 הרי שבפירוש אסרו למכור ליהודי החשוד למכור לגוי! כיון שנוכח רבה שצדק אביי, \u0003רהיט בתריה תלתא פרסי\u0004 \u0005[רץ אחריו,\u0006 אחרי אותו חשוד שקנה את חמורו, מרחק \u0005שלוש פרסות]\u0006 כדי לבטל את המכר, \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שרדף אחריו מרחק \u0003פרסא בחלא\u0004 \u0005[פרסה בחולות],\u0006 \u0003ולא אדרכיה\u0004 \u0005[השיגו].\u0006","אגב שהובאה הברייתא בעניין איסור מכירת כלי נשק, מביאים מה ש\u0003אמר רב דימי בר אבא: כדרך שאסור למכור לגוי, אסור למכור ללסטים\u0004 (גנב חמוש בנשק) \u0003ישראל.\u0004 ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אי דחשיד דקטיל\u0004 \u0005[אם\u0006 ליסטים זה \u0005חשוד ש\u0006הוא \u0005הורג\u0006 נפשות\u0005]\u0006 — \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, \u0003היינו\u0004 \u0005[זהו]\u0006 בדיוק דינו של \u0003גוי,\u0004 שאסור למכור לו משום \"לפני עיוור\"!","\u0003ואי דלא קטיל\u0004 \u0005[ואם\u0006 הוא לסטים \u0005שאינו הורג],\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא\u0004 ימכרו לו? ומשיבים: \u0003לעולם\u0004 מדובר בליסטים \u0003דלא קטיל\u0004 \u0005[שאינו הורג\u0006 נפשות\u0005],\u0006 \u0003ו\u0004אם כן מדוע בכל זאת אסור למכור לו? \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003במשמוטא\u0004 \u0005[ב\u0006גנב \u0005השומט\u0006 דברים\u0005],\u0006 \u0003דזימנין דעביד לאצולי נפשיה\u0004 \u0005[שפעמים\u0006 הוא \u0005עושה,\u0006 משתמש בנשק, כדי \u0005להציל עצמו]\u0006 כשתופסים אותו, ויש לחשוש שישתמש בנשק ויהרוג בו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין מוכרין להן\u0004 לגויים \u0003תריסין\u0004 (מגינים) אף על פי שהם רק נשק להגנה ולא להתקפה, \u0003ויש אומרים: מוכרין להן תריסין.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 שאין מוכרים להם? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דמגנו עלייהו\u0004 \u0005[ש\u0006הם \u0005מגינים עליהם]\u0006 בשעת מלחמה, \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה חושש, \u0003אפילו חיטי ושערי נמי\u0004 \u0005[חיטים ושעורים גם כן]\u0006 \u0003לא\u0004 ימכרו להם, שהרי גם הם מועילים להם! \u0003אמר רב:\u0004"],["\u0003אי\u0004 \u0005[אם]\u0006 \u0003אפשר\u0004 היה שלא למכור להם בלי שתיגרם איבה, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 היה אסור הדבר, אבל אי אפשר בלא כן. מה שאין כן בתריסים, שניתן להימנע ממכירתם.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003תריסין היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 ש\u0003לא\u0004 מוכרים להם, \u0003דכי שלים זינייהו, קטלי בגוייהו\u0004 \u0005[שכאשר נגמר הנשק שלהם,\u0006 הם \u0005הורגים בהם,\u0006 בתריסים\u0005].\u0006 \u0003ו\u0004לפי זה, טעמם של \u0003יש אומרים\u0004 שבברייתא ש\u0003מוכרים להם תריסין,\u0004 היא שאין לחשוש לכך, משום \u0003דכי שלים זינייהו, מערק ערקי\u0004 \u0005[שכאשר נגמר הנשק שלהם,\u0006 הם \u0005בורחים],\u0006 ואין הם משתמשים בתריסים להריגה. \u0003אמר רב נחמן אמר רבה בר אבוה: הלכה כיש אומרים\u0004 שמוכרים להם תריסים.","\u0003אמר רב אדא בר אהבה: אין מוכרין להן עששיות\u0004 (גושים, מטילים) \u0003של ברזל, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003משום דחלשי מינייהו\u0004 \u0005[ש\u0006הם \u0005יוצרים מהם]\u0006 \u0003כלי זיין.\u0004 ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אפילו מרי וחציני נמי\u0004 \u0005[מעדרים וכשילים גם כן]\u0006 לא נמכור להם, שהרי הם יכולים לחשל מהם כלי נשק! \u0003אמר רב זביד:\u0004 מדובר \u0003בפרזלא הינדואה\u0004 \u0005[בברזל הודי]\u0006 שהוא מובחר ומשתמשים בו לכלי זיין. ומעירים: \u0003והאידנא, דקא מזבנינן\u0004 \u0005[ובימינו, שאנו מוכרים]\u0006 כל כלי נשק, \u0003אמר רב אשי:\u0004 הרי זה \u0003לפרסאי דמגנו עילוון\u0004 \u0005[לפרסים שמגינים עלינו].\u0006","שנינו במשנה: \u0003עגלים וסייחים\u0004 אין מוכרים להם. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' יהודה מתיר ב\u0004בהמה \u0003שבורה\u0004 למוכרה, \u0003מפני שאינה יכולה להתרפאות ולחיות. אמרו לו: והלא מרביעין עליה ויולדת,\u0004 ומסבירה הגמרא: \u0003וכיון\u0004 ש\u0003מרביעין עליה ויולדת אתו לשהויה\u0004 \u0005[יבואו להשהות אותה\u0006 אצלם\u0005]\u0006 וישראל הרואה אותה ברשותם לא יבחין, ויהא סבור שמותר למכור להם בהמה גסה! \u0003אמר להן\u0004 ר' יהודה: \u0003לכשתלד\u0004 בהמה כזו אחשוש לדבר, שאיני חושש לכך. ומעירים: \u0003אלמא\u0004 \u0005[מכאן]\u0006 שהוא סבור ששבורה \u0003לא מקבלת זכר,\u0004 שאין היא נרבעת ויולדת.","ועוד שנינו במשנה: \u0003בן בתירא מתיר בסוס\u0004 למוכרו לגוי. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003בן בתירא מתיר בסוס, מפני שהוא\u0004 הגוי \u0003עושה בו\u0004 בשבת \u0003מלאכה שאין חייבין עליה חטאת,\u0004 כלומר, משום שרכיבה אינה מלאכה שיש עליה איסור מן התורה, ואין מקום לגזור משום חשש זה. \u0003ורבי אוסר\u0004 למכור סוס \u0003מפני שני דברים, אחד משום תורת כלי זיין,\u0004 שבדרך כלל משתמשים בסוסים במלחמה, \u0003ואחד משום תורת בהמה גסה.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 לענין \u0003תורת כלי זיין איכא\u0004 \u0005[יש]\u0006 \u0003דקטיל בסחופיה\u0004 \u0005[ש\u0006הסוס \u0005הורג במכתו],\u0006 שמלמדים את הסוס עצמו להרוג. \u0003אלא תורת בהמה גסה מאי\u0004 \u0005[מה]\u0006 \u0003היא,\u0004 מה עניינו? הרי אמרנו שלא נועד אלא לרכיבה! \u0003אמר\u0004 \u0003ר' יוחנן: לכשיזקין\u0004 הסוס ושוב אינו ראוי למלחמה \u0003מטחינו\u0004 (טוחן בו) \u0003ברחיים,\u0004 ונמצא עושה בו מלאכה של ממש \u0003בשבת. אמר ר' יוחנן: הלכה כבן בתירא\u0004 שמותר למכור סוס.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לתלמידים\u0005]:\u0006 \u0003שור של פטם\u0004 שמפטמים אותו לצורך שחיטה, \u0003מהו,\u0004 מה דינו לעניין מכירה? ומעירים: \u0003תיבעי\u0004 \u0005[תישאל]\u0006 השאלה \u0003ל\u0004פי שיטת \u0003ר' יהודה, תיבעי לרבנן\u0004 \u0005[תישאל\u0006 לדעת \u0005חכמים].\u0006","\u0003תיבעי\u0004 \u0005[תישאל]\u0006 \u0003ל\u0004דעת \u0003ר' יהודה: עד כאן לא קא שרי\u0004 \u0005[התיר]\u0006 \u0003ר' יהודה אלא בשבורה, דלא אתי\u0004 \u0005[שלא תבוא]\u0006 אף בעתיד \u0003לכלל מלאכה, אבל האי\u0004 \u0005[זה]\u0006 שור של פטם, \u0003דכי משהי ליה\u0004 \u0005[שכאשר ישהו אותו\u0006 ולא יפטמו אותו\u0005]\u0006 \u0003אתי\u0004 \u0005[יבוא]\u0006 \u0003לכלל מלאכה\u0004 — \u0003אסור\u0004 למוכרו,","\u0003או דלמא\u0004 \u0005[שמא]\u0006 יש לומר ההפך: \u0003אפילו ל\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003לא קא אסרי התם\u0004 \u0005[אין הם אוסרים שם]\u0006 למכור בהמה שבורה \u0003אלא\u0004 בדבר \u0003דסתמיה לאו\u0004 \u0005[\u0006\u0005שסתמו לא]\u0006 \u0003לשחיטה קאי\u0004 \u0005[עומד]\u0006 אלא למלאכה\u0005,\u0006 \u0003אבל האי\u0004 \u0005[זה]\u0006 שור של פטם, \u0003דסתמיה\u0004 \u0005[שסתמו]\u0006 \u0003לשחיטה קאי\u0004 \u0005[עומד]\u0006 ולא לעבוד בו, \u0003אפילו רבנן שרו\u0004 \u0005[חכמים מתירים]?\u0006","ומציעים תשובה: \u0003תא שמע\u0004 \u0005[בוא ושמע],\u0006 ש\u0003אמר רב יהודה אמר שמואל:\u0004 אנשיו \u0003של בית רבי היו מקריבין\u0004 צריכים היו להביא מתנה לשלטון \u0003שור של פטם ביום אידם\u0004 של הגוים, \u0003חסר\u0004 \u0005[חיסרו]\u0006 משלהם \u0003ארבע ריבבן\u0004 \u0005[רבבות]\u0006 של דינרים כשוחד, כדי להביא לכך \u0003שאין מקריבין אותו היום\u0004 ביום האיד, \u0003אלא למחר,\u0004 וכן \u0003חסר\u0004 \u0005[חיסרו]\u0006 משלהם והוציאו עוד \u0003ארבע ריבבן\u0004 \u0005[רבבות]\u0006 \u0003שאין מקריבין אותו\u0004 להם \u0003חי אלא שחוט,\u0004 חזרו ו\u0003חסר\u0004 \u0005[חיסרו]\u0006 עוד \u0003ארבע ריבבן\u0004 \u0005[רבבות]\u0006 \u0003שאין מקריבין אותו כל עיקר.\u0004","ויש לשאול: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 שנתנו שוחד כדי שלא יצטרכו לתיתו? \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 שמכירת פטם לגוי אסורה \u0003דלמא אתי לשהויי\u0004 \u0005[שמא יבואו להשהות\u0006 אותו\u0005]\u0006 ויבוא לכלל מלאכה? ודוחים: \u0003וליטעמיך\u0004 \u0005[ולשיטתך]\u0006 שכך אתה מסביר, אם כן מה שהוציאו כסף מתחילה \u0003שאין מקריבין אותו היום אלא למחר\u0004 — \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 מה הרוויחו בכך? \u0003אלא\u0004 טעם הדבר שונה הוא, \u0003רבי מיעקר מילתא בעי\u0004 \u0005[רצה לעקור את הדבר],\u0006 את הגזירה הזו, שיהא מוטל עליהם מס זה, \u0003וסבר: יעקר ואתי פורתא פורתא\u0004 \u0005[ייעקר ויבוא מעט מעט],\u0006 ולכן בכל פעם שינה במקצת את הגזירה הזו כדי לבטלה לבסוף לגמרי, ונמצא שאין מכאן ראיה לשאלה זו.","ועל עצם שאלת הגמרא שואלים: שור של פטם \u0003וכי משהי ליה, בריא ועביד\u0004 \u0005[וכאשר משהים אותו,\u0006 את השור של פטם, הריהו \u0005מבריא\u0006 מתחזק \u0005ועושה]\u0006 \u0003מלאכה? אמר רב אשי, אמר לי\u0004 האיש שהיה מומחה לדבר, ששמו היה \u0003זבידא: בר תורא\u0004 \u0005[בן שור]\u0006 שפיטמו אותו, \u0003משהינן ליה ועביד על חד תרין\u0004 \u0005[משהים אותו\u0006 שירזה \u0005ו\u0006הוא \u0005עושה מלאכה פי שניים\u0006 משוורים אחרים\u0005].\u0006","\u0003אין מוכרין להם\u0004 לגוים \u0003דובין ואריות וכל דבר שיש בו נזק לרבים.\u0004 וכן \u0003אין בונין עמהם בסילקי\u0004 (אולם עמודים גדול), או \u0003גרדום\u0004 (שדנים בו), או \u0003איצטדייא\u0004 (אצטדיון) \u0003ובימה, אבל בונין עמהם בימוסיאות\u0004 (במות קטנות) \u0003ו\u0004כן \u0003בית מרחצאות.\u0004 אם \u0003הגיע\u0004 בבית המרחץ \u0003לכיפה שמעמידין בה\u0004 הגויים \u0003עבודה זרה\u0004 — \u0003אסור לבנות\u0004 עמהם.","\u0003אמר רב חנין בר רב חסדא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר רב חנן בר רבא אמר רב: חיה גסה הרי היא\u0004 נידונת \u0003כבהמה דקה ל\u0004ענין \u0003פירכוס\u0004 בזמן שחיטה. שאם היתה עומדת למות ושחטוה, הרי אם פירכסה לאחר שחיטתה סימן הוא שעדיין היתה חיה, ומותרת בשחיטתה, אבל אם לא פירכסה — אסורה. \u0003אבל לא\u0004 דומה דין חיה גסה לדין בהמה דקה \u0003ל\u0004ענין \u0003מכירה,\u0004 אלא דווקא לבהמה גסה, שאסור למוכרה לגוים כלל.","והוסיף רב חנן בר רבא: אלו דברי רב, \u0003ואני אומר: אף למכירה\u0004 דינה כבהמה דקה, ש\u0003מקום שנהגו למכור\u0004 — \u0003מוכרין, שלא למכור\u0004 — \u0003אין מוכרין.\u0004","ומקשים על רב, \u0003תנן\u0004 \u0005[שנינו]\u0006 במשנתנו: \u0003אין מוכרין להן דובין ואריות ולא כל דבר שיש בו נזק לרבים.\u0004 ונדייק מכאן: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא] משום \u0003דאית ביה\u0004 \u0005[שיש בו]\u0006 \u0003נזק לרבים,\u0004 לכך אין מוכרים להם. \u0003הא לית ביה\u0004 \u0005[אבל\u0006 חיה גסה אחרת, ש\u0005אין בה]\u0006 \u0003נזק לרבים שרי\u0004 \u0005[מותר]!\u0006 \u0003אמר רבה בר עולא:\u0004 אין מכאן ראיה לדחות דברי רב, שכן לשיטתו מדובר במשנה \u0003בארי שבור,\u0004 שאינו ראוי למלאכה,"],["\u0003ואליבא\u0004 \u0005[ולפי שיטת]\u0006 \u0003ר' יהודה\u0004 במשנה הקודמת, (לעיל עבודה זרה יד,ב) שמתיר למכור בהמה גסה שהיא שבורה. אבל חיה גסה שלימה — אסור למכור, כדרך שאסור למכור בהמה גסה. \u0003רב אשי אמר:\u0004 אין צורך להעמיד במקרה מיוחד כזה, אלא \u0003סתם ארי שבור הוא אצל מלאכה\u0004 כלומר, אינו מסוגל לעשות מלאכה, וממילא החשש במכירה אינו קיים לגביו.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא: \u0003כשם שאין מוכרין להן בהמה גסה, כך אין מוכרין להן חיה גסה, ואפילו במקום שמוכרין להן בהמה דקה, חיה גסה אין מוכרין להן.\u0004 אם כן, \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003רב חנן בר רבא,\u0004 שהתיר! ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא ונדחו דבריו. וענין זה שעסקנו בו נידון גם בצורות אחרות.","\u0003רבינא רמי מתניתין אברייתא ומשני\u0004 \u0005[היה משליך\u0006 מראה סתירה בין \u0005משנתנו והברייתא ומתרץ],\u0006 כיצד? \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003אין מוכרין להן דובין ואריות ולא כל דבר שיש בו נזק לרבים,\u0004 ונדייק מכאן: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא] חיה כמו ארי \u0003דאית ביה\u0004 \u0005[שיש בו]\u0006 \u0003נזק\u0004 אין מוכרים, \u0003הא לית ביה\u0004 \u0005[אבל\u0006 דבר ש\u0005אין בו]\u0006 \u0003נזק\u0004 — \u0003מוכרין.\u0004","\u0003ורמינהי\u0004 \u0005[ומקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בברייתא: \u0003כשם שאין מוכרין בהמה גסה, כך אין מוכרין חיה גסה, ואפילו במקום שמוכרין בהמה דקה, חיה גסה אין מוכרין,\u0004 משמע שאין מוכרים כלל חיה גסה, אפילו כשאינה גורמת נזק! \u0003ומשני\u0004 \u0005[ומתרץ]\u0006 רבינא: מדובר במשנה \u0003בארי שבור, ואליבא\u0004 \u0005[ועל פי שיטתו]\u0006 של \u0003ר' יהודה.\u0004 ואילו \u0003רב אשי אמר: סתם ארי שבור הוא אצל מלאכה.\u0004","ולעצם הראיה לענין זה ממשנתנו, \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב נחמן: מאן לימא לן\u0004 \u0005[מי יאמר לנו]\u0006 ש\u0003ארי חיה גסה היא? דלמא\u0004 \u0005[שמא]\u0006 \u0003חיה דקה היא,\u0004 ואין לדייק מכאן לעניין חיה גסה!","ועוד מביאים, \u0003רב אשי דייק מתניתין ומותיב תיובתא\u0004 \u0005[היה מדייק ממשנתנו ומקשה\u0006 ממנה \u0005קושיה חמורה],\u0006 כיצד? \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין מוכרין להן דובים ואריות ולא כל דבר שיש בו נזק לרבים,\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 דבר \u0003דאית ביה\u0004 \u0005[שיש בו]\u0006 \u0003נזק, הא לית ביה\u0004 \u0005[הרי\u0006 אם \u0005אין בו]\u0006 \u0003נזק מוכרין; ו\u0004עוד יש לדייק:","\u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 \u0003ארי,\u0004 ש\u0003סתם ארי שבור הוא אצל מלאכה,\u0004 מותר במכירה אם אין בו נזק, \u0003אבל מידי אחרינא דעביד\u0004 \u0005[דבר אחר,\u0006 חיה אחרת \u0005שעושה]\u0006 \u0003מלאכה\u0004 — \u0003לא,\u0004 אסור למכור אותו, ואם כן מכאן \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003רב חנן בר רבא\u0004 שהתיר! ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא.","ושואלים: \u0003וחיה גסה מיהת מאי\u0004 \u0005[על כל פנים איזו]\u0006 \u0003מלאכה עבדא\u0004 \u0005[עושה]\u0006 היא, שיש לאסור למוכרה? הרי חיה אינה מאולפת למלאכה! \u0003אמר אביי, אמר לי מר יהודה: דבי\u0004 \u0005[בביתו]\u0006 של \u0003מר יוחני טחני\u0004 \u0005[היו טוחנים]\u0006 ב\u0003ריחים בערודי\u0004 \u0005[בערודים],\u0006 שהם חיה גסה.","\u0003אמר ר' זירא: כי הוינן בי\u0004 \u0005[כאשר היינו בבית\u0006 מדרשו\u0005]\u0006 של \u0003רב יהודה, אמר לן\u0004 \u0005[לנו]:\u0006 \u0003גמירו מינאי הא מילתא, דמגברא רבה שמיע לי\u0004 \u0005[לימדו ממני דבר זה, שמאדם גדול שמעתי אותה],\u0006 \u0003ולא ידענא אי\u0004 \u0005[ואיני יודע,\u0006 איני זוכר, \u0005אם]\u0006 \u0003מרב\u0004 שמעתיה \u0003אי\u0004 \u0005[אם]\u0006 \u0003משמואל: חיה גסה הרי היא\u0004 נידונת \u0003כבהמה דקה ל\u0004ענין \u0003פירכוס\u0004 לאחר שחיטה.","וממשיך ר' זירא ומספר: \u0003כי אתאי\u0004 \u0005[כאשר הגעתי]\u0006 \u0003ל\u0004עיר \u0003קורקוניא,\u0004 \u0003אשכחתיה\u0004 \u0005[מצאתי]\u0006 את \u0003רב חייא בר אשי, ויתיב וקאמר משמיה\u0004 \u0005[ויושב\u0006 היה \u0005ואומר משמו]\u0006 של \u0003שמואל: חיה גסה הרי היא כבהמה דקה לפירכוס, אמינא\u0004 \u0005[אמרתי]:\u0006 \u0003שמע מינה משמיה\u0004 \u0005[למד מכאן שמשמו]\u0006 של \u0003שמואל איתמר\u0004 \u0005[נאמר]\u0006 דבר זה, ונתברר ספיקו של רב יהודה. \u0003כי אתאי\u0004 \u0005[כאשר הגעתי]\u0006 \u0003לסורא, אשכחתיה\u0004 \u0005[מצאתי]\u0006 את \u0003רבה בר ירמיה דיתיב וקאמר לה משמיה\u0004 \u0005[שיושב ואומר את\u0006 ההלכה \u0005הזו משמו]\u0006 של \u0003רב: חיה גסה הרי היא כבהמה דקה לפירכוס,\u0004 ומתוך כך \u0003אמינא\u0004 \u0005[אמרתי]:\u0006 \u0003שמע מינה איתמר משמיה\u0004 \u0005[למד מכאן, שנאמר\u0006 הדבר \u0005משמו]\u0006 של \u0003רב ואיתמר משמיה\u0004 \u0005[ונאמר\u0006 גם \u0005משמו]\u0006 של","\u0003שמואל. כי סליקת להתם\u0004 \u0005[כאשר עליתי לשם]\u0006 לארץ ישראל, \u0003אשכחתיה\u0004 \u0005[מצאתי]\u0006 את \u0003רב אסי דיתיב וקאמר\u0004 \u0005[שיושב ואומר],\u0006 \u0003אמר רב חמא בר גוריא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: חיה גסה הרי היא כבהמה דקה לפירכוס, אמרי ליה\u0004 \u0005[אמרתי לו]:\u0006 \u0003ולא סבר לה מר דמאן מרא דשמעתתא\u0004 \u0005[ו\u0006כי \u0005אין אדוני סבור שמיהו בעליה,\u0006 מוסרה, \u0005של שמועה זו]\u0006 \u0003רבה בר ירמיה?\u0004 ומדוע לא אמרת בשמו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003פתיא אוכמא\u0004 \u0005[סיר שחור],\u0006 כלומר אדם המתייגע הרבה בתורה, \u0003מינאי ומינך\u0004 \u0003תסתיים שמעתא\u0004 \u0005[ממני וממך תסתיים השמועה],\u0006 שנצרף את שני הדברים למסורת אחת.","ומעירים: ואכן, \u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 במסורת הלכה זו כדברי רב אסי: \u0003אמר ר' זירא אמר רב אסי אמר רבה בר ירמיה אמר רב חמא בר גוריא אמר רב: חיה גסה הרי היא כבהמה דקה לפירכוס.\u0004","שנינו במשנה ש\u0003אין בונין\u0004 בסילקאות. \u0003אמר רבה בר בר חנה אמר ר' יוחנן, שלש\u0004 מיני \u0003בסילקאות הן: של מלכים, ושל מרחצאות, ושל אוצרות\u0004 (מחסנים). \u0003אמר רבא: שתים\u0004 מהם \u0003להיתר\u0004 שאין בהם צד איסור (ללא חשש הריגה) ומותר לבנותם, \u0003ואחד\u0004 מהם \u0003לאיסור, וסימן\u0004 לדבר: \u0003\"לאסר מלכיהם בזקים\"\u0004 (תהלים קמט, ח), ומכאן רמז שבסילקאות של מלכים הם האסורות בבניה.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים],\u0006 \u0003אמר רבא: כולם להיתר.\u0004 ומקשים: כיצד כולם להיתר? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין בונין עמהן בסילקי, גרדום, איצטדייא ובימה!\u0004 ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 ותקן את לשון המשנה כך: אין בונים עמהן בסילקי \u0003של גרדום ושל איצטדייא ושל בימה,\u0004 אבל בסילקי שלא לצרכי דין והריגה — בונים.","עקב דברים אלה מספרים כמה מעשים על חכמים שנדונו על ידי המלכות. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כשנתפס ר' אליעזר למינות\u0004 כלומר, כשהואשם על ידי השלטונות באשמת מינות, \u0003העלהו לגרדום לידון. אמר לו אותו הגמון\u0004 (שופט): \u0003זקן שכמותך יעסוק בדברים בטלים הללו\u0004 של המינות?","\u0003אמר לו: נאמן עלי הדיין.\u0004 ומסבירים: \u0003כסבור\u0004 \u0003(\u0004סבור היה) \u0003אותו הגמון: עליו הוא אומר,\u0004 שר' אליעזר מדבר על ההגמון עצמו שיוציא את דינו כראוי. \u0003ו\u0004אולם \u0003הוא לא אמר אלא כנגד אביו שבשמים\u0004 כלומר, הוא התכוון לומר שנאמנים עליו דיני שמים, שאם נתפס בדבר זה מן הסתם כך היה ראוי לו. \u0003אמר לו\u0004 ההגמון: \u0003הואיל והאמנתי\u0004 (האמנת אותי) \u0003עליך, דימוס,\u0004 כלומר \u0003פטור אתה.\u0004","\u0003כשבא לביתו נכנסו תלמידיו אצלו לנחמו\u0004 על שהאשימוהו באשמת מינות, \u0003ולא קיבל עליו תנחומין\u0004 במה שאמרו לו. \u0003אמר לו ר' עקיבא: רבי, תרשיני לומר דבר אחד ממה שלימדתני?\u0004 \u0003אמר לו: אמור. אמר לו: רבי, שמא\u0004 דבר של \u0003מינות בא לידך\u0004"],["\u0003והנאך\u0004 (ונהנית ממנו), \u0003ועליו\u0004 (ובגללו) \u0003נתפסת\u0004 מצד דיני שמים? \u0003אמר לו: עקיבא, הזכרתני\u0004 שכך היה, \u0003פעם אחת הייתי מהלך בשוק העליון של ציפורי, ומצאתי אדם אחד מתלמידי ישו הנוצרי ויעקב איש כפר סכניא שמו, אמר לי, כתוב בתורתכם: \"לא תביא אתנן זונה\u0004 ומחיר כלב בית ה' אלהיך\" (דברים כג, יט), \u0003מהו לעשות הימנו\u0004 מכסף אתנן \u0003בית הכסא לכהן גדול\u0004 בבית המקדש? \u0003ולא אמרתי לו כלום.\u0004","\u0003אמר לי, כך לימדני ישו הנוצרי\u0004 שמותר הדבר, שנאמר: \u0003\"כי מאתנן זונה קבצה ועד אתנן זונה ישובו\"\u0004 (מיכה א, ז), לומר: \u0003ממקום הטנופת באו\u0004 כספים אלה של אתנן זונה, \u0003למקום הטנופת\u0004 של בית הכסא \u0003ילכו,\u0004","\u0003והנאני הדבר\u0004 כלומר, נהנתי מן החידוד שיש בכך, ו\u0003על ידי זה נתפסתי למינות\u0004 על ידי השלטונות, וזאת משום ש\u0003עברתי על מה שכתוב בתורה: \"הרחק מעליה דרכך\"\u0004 (משלי ה, ח), ומפרשים: \u0003זו מינות, \"ואל תקרב אל פתח ביתה\"\u0004 (משלי ה, ח) — \u0003זו הרשות\u0004 (השלטונות הזרים). ומעירים: \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 בלשון אחרת: \u0003\"הרחק מעליה דרכך\"\u0004 — \u0003זו מינות והרשות, \"ואל תקרב אל פתח ביתה\"\u0004 — \u0003זו זונה.\u0004 ושואלים: \u0003וכמה\u0004 היא קירבה האסורה? \u0003אמר רב חסדא: ארבע אמות.\u0004","כיון שהוזכרה אותה דרשת הכתוב, שואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003[האי\u0004 (פסוק זה)\u0003] \"מאתנן זונה\" מאי דרשי ביה\u0004 \u0005[מה\u0006 הם \u0005דורשים בו]?\u0006 ואומרים: \u0003כ\u0004דברי \u0003רב חסדא,\u0004 ש\u0003אמר רב חסדא: כל זונה שנשכרת\u0004 על ידי כסף, נקשרת היא כל כך לעניין זה, עד ש\u0003לבסוף\u0004 כאשר שוב אין בה חפץ, \u0003היא\u0004 עצמה \u0003שוכרת\u0004 אנשים לזנות עימה, \u0003שנאמר: \"ובתתך אתנן ואתנן לא נתן לך [ותהי להפך]\"\u0004(יחזקאל טז, לד).","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 דעת רב חסדא, שאמר שהכתוב אוסר להתרחק מרחק מסויים מזנות, על שיטת \u0003ר' פדת,\u0004 ש\u0003אמר ר' פדת: לא אסרה תורה אלא קריבה של\u0004 מעשה שיש בו \u0003גלוי עריות בלבד,\u0004 ולא קירבה אחרת, \u0003שנאמר: \"איש איש אל כל שאר בשרו לא תקרבו לגלות ערוה\"\u0004 (ויקרא יח, ו), כלומר, איזוהי קירבה אסורה? זו שיש בה גילוי ערוה.","מסופר, \u0003עולא כי הוה אתי מבי רב, הוה מנשק להו לאחתיה אבי ידייהו\u0004 \u0005[כאשר היה בא,\u0006 שב לביתו ממקום לימודו, \u0005מבית הרב, היה מנשק את אחיותיו על ידיהן],\u0006 \u0003ואמרי לה\u0004 \u0005[ויש שאומרים]\u0006 שהיה מנשקן \u0003אבי חדייהו\u0004 \u0005[על חזיהן]\u0006. ומעירים: \u0003ופליגא דידיה אדידיה\u0004 \u0005[וחלוק\u0006 מעשה זה \u0005שלו\u0006 של עולא \u0005על\u0006 דבר אחר \u0005שלו],\u0006 ש\u0003אמר עולא:\u0004 אפילו \u0003קריבה בעלמא\u0004 \u0005[בלבד]\u0006 לערוה \u0003אסור,\u0004 \u0003משום \"לך לך אמרין נזירא\u0004 \u0003סחור סחור לכרמא לא תקרב\"\u0004 \u0005[\"לך לך אומרים\u0006 אנשים ל\u0005נזיר, סביב סביב, לכרם אל תתקרב\"]\u0006 שלא תיכשל באכילת ענבים. ובאותו אופן צריך להתרחק מכל קירבה שיש בה צד ערוה.","ובהמשך לדברים על המינות והרשות, מביאים את הפסוק: \u0003\"לעלוקה שתי בנות הב הב\"\u0004 (משלי ל, טו), ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"הב הב\"? אמר מר עוקבא:\u0004 אלה הם \u0003[קול] שתי בנות, שצועקות מגיהנם\u0004 מרוב יסוריהן, והן אלה ש\u0003אומרות בעולם הזה: הבא הבא\u0004 (\"הב הב\"), שדורשות מסים והכנעה להן, \u0003ומאן נינהו\u0004 \u0005[ומי הן\u0006 אלה\u0005]?\u0006 ה\u0003מינות והרשות. איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003אמר רב חסדא אמר מר עוקבא, קול גיהנם צועקת ואומרת\u0004 כך: \u0003הביאו לי שתי בנות שצועקות ואומרות בעולם הזה \"הבא הבא\".\u0004","נאמר בספר משלי על האשה הנכריה: \u0003\"כל באיה לא ישובון ולא ישיגו ארחות חיים\"\u0004 (משלי ב, יט), ומבינים חכמים כי \"אשה\" זו היא המינות, ותמהים: \u0003וכי מאחר שלא שבו\u0004 (\"לא ישובון\") ההולכים אצל המינות, \u0003היכן ישיגו\u0004 אורחות חיים? ומה טעם צריך להשמיענו הכתוב כן? ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך\u0006 הוא \u0005אומר]\u0006 כך יש להבין את הכתוב: בדרך כלל כל באיה לא ישובו, \u0003ו\u0004גם \u0003אם ישובו\u0004 — \u0003לא ישיגו אורחות חיים.\u0004","ומקשים: \u0003למימרא\u0004 \u0005[לומר,\u0006 ללמוד מכאן\u0005]\u0006 ש\u0003כל הפורש ממינות\u0004 שהיה שם וחזר בו — \u0003מיית\u0004 \u0005[מת],\u0006 שאינו יכול לחיות עוד? \u0003והא ההיא דאתאי לקמיה\u0004 \u0005[והרי\u0006 אשה \u0005אחת שבאה לפני]\u0006 \u0003רב חסדא\u0004 להתוודות לפניו, \u0003ואמרה ליה\u0004 \u0005[לו]:\u0006 \u0003קלה שבקלות\u0004 העבירה הקטנה ביותר שעשתה, היתה ש\u0003עשתה בנה הקטן מבנה הגדול,\u0004 כלומר שנבעלה לבנה הגדול והולידה ממנו בן קטן, \u0003ואמר לה רב חסדא: טרחו לה בזוודתא\u0004 \u0005[בצידה לדרך]\u0006 כלומר הכינו לה תכריכים, שוודאי תמות במהרה, \u0003ו\u0004בסופו של דבר \u0003לא מתה.\u0004","\u0003מדקאמרה\u0004 \u0005[מ\u0006מה \u0005שאמרה]\u0006 ש\u0003קלה שבקלות\u0004 היא מה ש\u0003עשתה\u0004 בנה הקטן מבנה הגדול, \u0003מכלל\u0004 הדברים אתה למד ש\u0003מינות [נמי] הויא\u0004 \u0005[גם כן היתה]\u0006 \u0003בה,\u0004 עד שפרקה כל עול, ובכל זאת לא מתה! ומשיבים: \u0003ההוא\u0004 \u0005[\u0006ב\u0005אותו\u0006 מקרה\u0005]\u0006 מדובר ש\u0003לא הדרא\u0004 \u0005[חזרה]\u0006 \u0003בה שפיר\u0004 \u0005[היטב],\u0006 \u0003ומשום הכי\u0004 \u0005[כך]\u0006 \u0003לא מתה,\u0004 משום שלא היתה תשובה זו גמורה.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שכך היתה הקושיה על מה שנאמר שהפורש ממינות מת: מכלל הדברים אתה למד שדווקא הפורש \u0003ממינות\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מת, \u0003מעבירה\u0004 של עריות — \u0003לא? והא ההיא דאתאי קמיה\u0004 \u0005[והרי\u0006 אשה \u0005אחת שבאה לפני]\u0006 \u0003רב חסדא, ואמר להו\u0004 \u0005[להם]\u0006 \u0003[רב חסדא: זוידו\u0004 \u0005[הכינו]\u0006 \u0003לה זוודתא\u0004 \u0005[צידה]\u0006 לדרך, תכריכיה\u0003], ומתה!\u0004 ומשיבים: \u0003מדקאמרה\u0004 \u0005[מ\u0006מה \u0005שאמרה]\u0006 \u0003קלה שבקלות, מכלל\u0004 הדברים אתה למד ש\u0003מינות נמי הויא\u0004 \u0005[גם כן היתה]\u0006 \u0003בה.\u0004","ושואלים: \u0003ו\u0004הפורש \u0003מעבירה\u0004 של עריות \u0003לא\u0004 ימות? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמרו עליו על ר' אלעזר בן דורדיא, שלא הניח זונה אחת בעולם שלא בא עליה,\u0004 שהיה שטוף כל כך בזנות. \u0003פעם אחת שמע שיש זונה אחת בכרכי הים והיתה\u0004 זונה זו \u0003נוטלת כיס\u0004 (ארנק) מלא \u0003דינרין בשכרה, נטל כיס דינרין והלך ועבר עליה\u0004 (לקראתה) \u0003שבעה נהרות\u0004 כדי להגיע אליה. \u0003בשעת הרגל דבר\u0004 כשהיו מתעסקים בענייני תשמיש, \u0003הפיחה\u0004 רוח מאחוריה, \u0003אמרה\u0004 בתוך הדברים: \u0003כשם שהפיחה זו אינה חוזרת למקומה, כך אלעזר בן דורדיא אין מקבלין אותו\u0004 גם אם יחזור \u0003בתשובה.\u0004","כששמע את הדבר נזדעזע מאד, \u0003הלך וישב בין שני הרים וגבעות, אמר: הרים וגבעות בקשו עלי רחמים,\u0004 שאתקבל בתשובה! \u0003אמרו לו: עד שאנו מבקשים עליך, נבקש על עצמנו, שנאמר: \"כי ההרים ימושו והגבעות תמוטינה\"\u0004 (ישעיהו נד, י). \u0003אמר: שמים וארץ בקשו עלי רחמים! אמרו: עד שאנו מבקשים עליך, נבקש על עצמנו, שנאמר: \"כי שמים כעשן נמלחו והארץ כבגד תבלה\"\u0004 (ישעיהו נא, ו).","\u0003אמר: חמה ולבנה בקשו עלי רחמים! אמרו לו: עד שאנו מבקשים עליך, נבקש על עצמנו, שנאמר: \"וחפרה הלבנה ובושה החמה\"\u0004 (ישעיהו כד, כג). \u0003אמר: כוכבים ומזלות בקשו עלי רחמים! אמרו לו: עד שאנו מבקשים עליך, נבקש על עצמנו, שנאמר: \"ונמקו כל צבא השמים\"\u0004 (ישעיהו לד, ד).","\u0003אמר: אין הדבר תלוי אלא בי, הניח ראשו בין ברכיו וגעה בבכיה עד שיצתה נשמתו. יצתה בת קול ואמרה: ר' אלעזר בן דורדיא מזומן לחיי העולם הבא. [והא הכא\u0004 \u0005[והרי כאן]\u0006 \u0003בעבירה הוה\u0004 \u0005[היה]\u0006 שחטא, \u0003ומית\u0004 \u0005[ומת]\u0006 כאשר עשה תשובה!\u0003]\u0004 ומשיבים: \u0003התם נמי\u0004 \u0005[שם גם כן],\u0006 \u0003כיון דאביק בה טובא\u0004 \u0005[שהיה קשור בה ביותר],\u0006 מעבר לתאוה גופנית בלבד, \u0003כמינות דמיא\u0004 \u0005[\u0006היא \u0005דומה],\u0006 שנעשה לו הדבר כעין עבודה זרה שלו.","מסופר, כששמע מעשה זה \u0003בכה רבי ואמר: יש קונה עולמו\u0004 עולם הבא שלו \u0003ב\u0004מעשים של \u0003כמה שנים, ויש קונה עולמו בשעה אחת. ו\u0004עוד \u0003אמר רבי\u0004 בעקבות מעשה זה: \u0003לא דיין לבעלי תשובה שמקבלין אותן, אלא שקורין אותן \"רבי\",\u0004 שהרי כך קראו לו מן השמים \"ר' אלעזר בן דורדיא\".","ועוד מסופר בעניין הרחקה מעבודה זרה ומזנות, \u0003ר' חנינא ור' יונתן הוו קאזלי באורחא\u0004 \u0005[היו מהלכים בדרך],\u0006 \u0003מטו להנהו תרי שבילי\u0004 \u0005[הגיעו לאותם שני שבילים],\u0006 \u0003חד פצי אפיתחא\u0004 \u0005[אחד\u0006 היה \u0005פתוח לפתח]\u0006 של \u0003עבודה זרה, וחד פצי אפיתחא דבי\u0004 \u0005[ואחד\u0006 היה \u0005פתוח לפתח של בית]\u0006 \u0003זונות. אמר ליה חד לחבריה\u0004 \u0005[לו אחד לחבירו]:\u0006 \u0003ניזיל אפיתחא\u0004 \u0005[נלך על הפתח]\u0006 שמוליך ל\u0003עבודה זרה,\u0004"],["\u0003דנכיס יצריה\u0004 \u0005[\u0006לפי \u0005שנשחט יצרו]\u0006 שאין יצר זה תקיף כבר, \u0003אמר ליה אידך\u0004 \u0005[לו האחר]:\u0006 להיפך, \u0003ניזיל אפיתחא דבי זונות ונכפייה ליצרין, ונקבל אגרא\u0004 \u0005[נלך על פתח בית הזונות, ונכפה את יצרנו ונקבל שכר]\u0006 על כך. \u0003כי מטו התם, חזינהו\u0004 \u0005[כאשר הגיעו לשם, ראו אותם]\u0006 \u0003[\u0004ה\u0003זונות],\u0004 \u0003איתכנעו מקמייהו\u0004 \u0005[נכנעו מפניהם]\u0006 ונכנסו פנימה למקומותיהן, מפני כבודם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 הראשון: \u0003מנא לך הא\u0004 \u0005[מנין לך זה]\u0006 שהזונות הן שתתביישנה מפנינו? \u0003אמר ליה\u0004 \u0005[לו],\u0006 כתוב: \u0003\"מזמה תשמר\u0004 עליך \u0003תבונה תנצרכה\"\u0004 (משלי ב, יא), כלומר, התורה היא תשמור עליך.","\u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לרבא: מאי\u0004 \u0005[מהי]\u0006 \u0003\"מזמה\"\u0004 הכתובה שם? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה ל\u0003תורה\u0004 שתשמור עליך, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בה \"זמה\"\u0004 (ויקרא יח, יז), \u0003ומתרגמינן\u0004 \u0005[ומתרגמים\u0006 דבר זה\u0005]:\u0006 \u0003עצת חטאין,\u0004 הרי שזימה היא עצה, חכמה, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 גם כן לגבי התורה ביטוי זה: \"גם זאת מעם ה' יצאה \u0003הפליא עצה הגדיל תושיה\"\u0004 (ישעיהו כח, כט), \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003\"זימה\u0004 תשמור עליך\" \u0003מבעי ליה\u0004 \u0005[צריך\u0006 היה \u0005לו\u0006 לומר\u0005],\u0006 ולא \"מזימה\"! אלא \u0003הכי קאמר\u0004 \u0005[כך אומר]\u0006 הכתוב: מזימה כמו מזימה, \u0003מדבר זימה תשמור עליך, תורה תנצרכה.\u0004","ושבים לעניין דינים שדנו את חכמי ישראל בזמן הרומאים. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כשנתפסו ר' אלעזר בן פרטא ור' חנינא בן תרדיון\u0004 למלכות כאשר היו גזירות השמד על ישראל, \u0003אמר לו ר' אלעזר בן פרטא לר' חנינא בן תרדיון: אשריך שנתפסת על דבר אחד\u0004 שהיתה עליו רק האשמה אחת, שהרביץ תורה ברבים, \u0003אוי לי שנתפסתי על חמשה דברים\u0004 חמש האשמות שונות שמעלילים עלי.","\u0003אמר לו ר' חנינא:\u0004 להיפך, \u0003אשריך שנתפסת על חמשה דברים ואתה ניצול, אוי לי שנתפסתי על דבר אחד ואיני ניצול, שאת\u0004 (אתה) \u0003עסקת בתורה ובגמילות חסדים, ואני לא עסקתי אלא בתורה [בלבד].\u0004","ומעירים: \u0003ו\u0004הוא \u0003כד\u0004ברי \u0003רב הונא,\u0004 ש\u0003אמר רב הונא: כל העוסק בתורה בלבד דומה כמי שאין לו אלוה, שנאמר: \"וימים רבים לישראל ללא אלהי אמת\u0004 וללא כהן מורה וללא תורה\" (דברי הימים ב טו, ג), \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"ללא אלהי אמת\"? שכל העוסק בתורה בלבד דומה כמי שאין לו אלוה\u0004 באמת.","ושואלים: \u0003ובגמילות חסדים לא עסק? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר בן יעקב אומר: לא יתן אדם מעותיו לארנקי של צדקה אלא אם כן ממונה עליו תלמיד חכם כר' חנינא בן תרדיון!\u0004 ומשיבים: \u0003הימנוה הוא דהוה מהימן\u0004 \u0005[להאמין לו הוא שהיה נאמן]\u0006 שלא נטל כלום לעצמו וחילק ביושר, אבל \u0003מיעבד לא עבד\u0004 \u0005[לעשות\u0006 בעצמו צדקה \u0005לא עשה].\u0006","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר לו\u0004 ר' חנינא בן תרדיון: \u0003מעות של פורים נתחלפו לי במעות של צדקה וחלקתים לעניים,\u0004 משמע שהוא בעצמו נתן צדקה! ומשיבים: אמנם \u0003מיעבד עבד\u0004 \u0005[לעשות עשה],\u0006 אבל \u0003כדבעי ליה לא עבד\u0004 \u0005[כמו שהיה ראוי לו\u0006 לפי עושרו \u0005לא עשה].\u0006","וממשיכים בתיאור המעשה, \u0003אתיוהו\u0004 \u0005[הביאו]\u0006 את \u0003ר' אלעזר בן פרטא\u0004 לדין, ו\u0003אמרו: מאי טעמא תנית, ומאי טעמא גנבת\u0004 \u0005[מה טעם שנית, ומה טעם גנבת]?\u0006 שאלה היו האשמות שהאשימוהו. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אי סייפא לא ספרא\u0004 \u0005[אם\u0006 אדם הוא \u0005סייף,\u0006 בעל חרב, גנב, \u0005אינו סופר\u0006 העוסק בתורה\u0005],\u0006 \u0003ואי ספרא לא סייפא\u0004 \u0005[ואם\u0006 הוא \u0005סופר אינו סייף],\u0006 כלומר, אתם מאשימים אותי בשני דברים הסותרים זה את זה, שמי שמלאכתו בתורה אינו עוסק בגניבה, וכן להיפך, \u0003ומדהא ליתא הא נמי ליתא\u0004 \u0005[ומכיון שזה אינו גם זה אינו].\u0006 ושאלו אותו: \u0003ו\u0004אם כן \u0003מאי טעמא קרו לך\u0004 \u0005[מה הטעם קוראים לך]\u0006 \u0003\"רבי\"?\u0004 אמר להם: \u0003רבן של תרסיים\u0004 (אורגים) \u0003אני,\u0004 גדול שבהם, ומלמדם, ומשום כך הם קוראים לי \"רבי\" בלשון כבוד.","רצו לבדוק אם אכן הוא מומחה בדבר, \u0003אייתו ליה תרי קיבורי\u0004 \u0005[הביאו לו שתי פקעות\u0006 של צמר\u0005],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003הי דשתיא והי דערבא\u0004 \u0005[איזו של שתי ואיזו של ערב]?\u0006 שיש הבדל בין חוטי שתי וערב בעוביים ובחוזקם, ודבר זה יכולים המומחים להבחין בו מיד. \u0003איתרחיש ליה ניסא\u0004 \u0005[התרחש לו נס],\u0006 \u0003אתיא זיבוריתא אותיבא על דשתיא ואתאי זיבורא ויתיב על דערבא\u0004 \u0005[באה צירעה נקבה\u0006 \u0005ישבה על\u0006 פקעת \u0005השתי ובא צירעה זכר\u0006 \u0005וישב על\u0006 פקעת \u0005הערב],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003האי דשתיא והאי דערבא\u0004 \u0005[זה של שתי וזה של ערב]\u0006 שהבין שמראים לו משמים דבר זה, שחוט השתי הקבוע בנול הוא המקבל את הערב, כמו הנקבה שמקבלת זכר.","\u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ומאי טעמא לא אתית לבי\u0004 \u0005[ומה טעם לא באת לבית]\u0006 \u0003אבידן?\u0004 שזה היה המקום שבו היו דנים בענייני חכמה ואמונה! \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003זקן הייתי ומתיירא אני שמא תרמסוני ברגליכם\u0004 מרוב הקהל. \u0003[אמרו]: ועד האידנא\u0004 \u0005[עכשיו]\u0006 \u0003כמה סבי איתרמוס\u0004 \u0005[זקנים נרמסו\u0006 שם\u0005],\u0006 שאתה חושש? \u0003אתרחיש ניסא, ההוא יומא אירמס חד סבא\u0004 \u0005[התרחש נס,\u0006 ו\u0005אותו יום נרמס זקן אחד],\u0006 ונמצא שבטלה טענתם.","שאלוהו: \u0003ומאי טעמא קא שבקת\u0004 \u0005[ומה טעם שלחת]\u0006 את \u0003עבדך לחירות?\u0004 והם גזרו שלא יעשו כן. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לא היו דברים מעולם,\u0004 לא עשיתי זאת. \u0003קם חד [מינייהו] לאסהודי ביה\u0004 \u0005[עמד אחד מהם להעיד בו],\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 \u0003אליהו אידמי ליה כחד מחשובי דמלכותא\u0004 \u0005[נדמה להם כאחד מחשובי המלכות],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מדאתרחיש ליה ניסא בכולהו, בהא נמי אתרחיש ליה ניסא\u0004 \u0005[מכיון שמתרחש לו נס בכולם, בזה גם כן יתרחש לו נס],\u0006 \u0003וההוא גברא בישותיה הוא דקא אחוי\u0004 \u0005[ואותו אדם,\u0006 אתה, את \u0005רשעותו הוא מראה],\u0006 שלא תצליח בכך, ואינך מראה אלא את רצונך להרע.","\u0003ולא אשגח ביה\u0004 \u0005[השגיח בו]\u0006 אותו אדם, \u0003קם למימר להו\u0004 \u0005[עמד לומר להם]\u0006 את עדותו. באותו זמן \u0003הוה כתיבא איגרתא\u0004 \u0005[היתה נכתבת אגרת]\u0006 \u0003דהוה כתיב מחשיבי דמלכות לשדורי לבי קיסר\u0004 \u0005[שהיתה כתובה מחשובי המלכות לשלוח לבית הקיסר],\u0006 \u0003ושדרוה על ידיה דההוא גברא\u0004 \u0005[ושלחו על ידי אותו אדם\u0006 שבא להעיד\u0005],\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 \u0003אליהו פתקיה ארבע מאה פרסי\u0004 \u0005[וזרקו ארבע מאות פרסות]\u0006 למרחק, \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003ולא אתא\u0004 \u0005[חזר]\u0006 ונתבטלו איפוא ההאשמות כנגד ר' אלעזר בן פרטא.","\u0003אתיוהו\u0004 \u0005[הביאו]\u0006 את \u0003ר' חנינא בן תרדיון\u0004 לדין, \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אמאי קא עסקת באורייתא\u0004 \u0005[מדוע עסקת בתורה]?\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 כלשון הכתוב: \u0003\"כאשר צוני ה' אלהי\"\u0004 (דברים ד, ה ). \u0003מיד גזרו עליו ל\u0004מות ב\u0003שריפה, ועל אשתו\u0004 גזרו \u0003להריגה\u0004 בחרב, \u0003ועל בתו לישב בקובה של זונות.\u0004 ומסבירים מדוע נגזרו עליו משמים העונשים הללו: \u0003עליו לשריפה\u0004 — \u0003שהיה\u0004"],["\u0003הוגה את השם באותיותיו,\u0004 שהיה מבטאו כמו שהיה כתוב. ושואלים: \u0003ו\u0004באמת \u0003הכי עביד הכי\u0004 \u0005[כיצד עשה כך]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005],\u0006 \u0003אלו שאין להם חלק לעולם הבא: האומר אין תורה מן השמים, ואין תחיית המתים מן התורה. אבא שאול אומר: אף ההוגה את השם באותיותיו!\u0004","ומשיבים: הוא \u0003להתלמד עבד\u0004 \u0005[עשה],\u0006 \u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0005]\u0006 לגבי איסור כשפים: \u0003\"לא תלמד לעשות\"\u0004 (דברים יח, ט) \u0003אבל אתה למד להבין ולהורות,\u0004 משמע שיש דברים שמותר לעשות בדרך לימוד.","ושואלים: אם כן, \u0003אלא מאי טעמא אענש\u0004 \u0005[מה טעם נענש]?\u0006 ומשיבים: \u0003משום הוגה את השם בפרהסיא [דהוי\u0004 \u0005[שהיה]\u0006\u0003],\u0004 שהיה צריך לעשות זאת בצינעה, ולא בפני הרבים. \u0003ו\u0004גזרו \u0003על אשתו להריגה,\u0004 משום ש\u0003לא מיחה ביה\u0004 \u0005[מחתה בו]\u0006 שלא יעשה כן. \u0003מכאן אמרו: כל מי שיש בידו למחות\u0004 בחבירו על עבירה שעובר, \u0003ואינו מוחה\u0004 — \u0003נענש עליו. ו\u0004עוד גזרו","\u0003על בתו לישב בקובה של זונות,\u0004 מדוע? \u0003אמר ר' יוחנן: פעם אחת היתה בתו\u0004 זאת \u0003מהלכת לפני גדולי רומי, אמרו\u0004 בשיחה ביניהם: \u0003כמה נאות פסיעותיה\u0004 (הליכתה) \u0003של ריבה\u0004 (נערה) \u0003זו,\u0004 כיון ששמעה כך \u0003מיד דקדקה\u0004 (הקפידה) \u0003בפסיעותיה\u0004 להלך כך, באופן שימצא חן בעיני הגברים, ולכן נענשה. \u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר ר' שמעון בן לקיש, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"עון עקבי יסובני\"\u0004 (תהלים מט, ו)? \u0003עונות שאדם דש בעקביו בעולם הזה,\u0004 כלומר, עוונות שאדם אינו שם לב אליהם, שהם עוונות קטנים שאינם נחשבים בעיניו, כגון דרך הליכתו, \u0003מסובין\u0004 (סובבים) \u0003לו ליום הדין.\u0004","ומסופר: \u0003בשעה שיצאו שלשתן\u0004 מן הדין \u0003צדקו עליהם את הדין, הוא,\u0004 ר' חנינא בן תרדיון, \u0003אמר: \"הצור תמים פעלו\u0004 כי כל דרכיו משפט\" (דברים לב, ד), \u0003ואשתו אמרה\u0004 את המשכו של כתוב זה: \u0003\"אל אמונה ואין עול\u0004 צדיק וישר הוא\". \u0003בתו אמרה: \"גדל העצה ורב העליליה אשר עיניך פקחות על כל דרכי\u0004 בני אדם לתת לאיש כדרכיו\" (ירמיהו לב, יט). \u0003אמר רבי: [כמה] גדולים צדיקים הללו, שנזדמנו להן שלש מקראות\u0004 אלה \u0003של צדוק הדין בשעת צדוק הדין.\u0004","ובענין זה של ר' חנינא בן תרדיון \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כשחלה ר' יוסי בן קיסמא, הלך ר' חנינא בן תרדיון לבקרו. אמר לו: חנינא אחי, (אחי) אי\u0004 \u0005[אין]\u0006 \u0003אתה יודע שאומה זו,\u0004 רומי, \u0003מן השמים המליכוה? ש\u0004הרי \u0003החריבה את ביתו ושרפה את היכלו, והרגה את חסידיו ואבדה את טוביו, ועדיין היא קיימת,\u0004 משמע שמן השמים נגזר כך, \u0003ואני שמעתי עליך שאתה יושב ועוסק בתורה [ומקהיל קהלות ברבים] וספר\u0004 תורה \u0003מונח לך בחיקך\u0004 בניגוד לגזירותיה של אומה זו!","\u0003אמר לו: מן השמים ירחמו\u0004 ולא יקרה לי דבר. \u0003אמר לו: אני אומר לך דברים של טעם\u0004 עניינים של סברה, \u0003ואתה אומר לי \"מן השמים ירחמו\"? תמה אני אם לא ישרפו\u0004 \u0003אותך ואת ספר תורה\u0004 שמונח לך בחיקך \u0003באש! אמר לו\u0004 ר' חנינא: \u0003רבי, מה אני לחיי העולם הבא,\u0004 כלומר, האם ראוי אני לכך?","\u0003אמר לו: כלום מעשה בא לידך?\u0004 איזה מעשה מיוחד בא לידך שאתה יכול לראות בו סימן? \u0003אמר לו: מעות של פורים נתחלפו לי במעות של צדקה וחלקתים\u0004 את כל הכסף שהייתי צריך לפורים \u0003ל\u0004צרכי \u0003עניים, אמר לו: אם כן, מחלקך יהי חלקי ומגורלך יהי גורלי.\u0004","\u0003אמרו: לא היו\u0004 (חלפו) \u0003ימים מועטים\u0004 \u0003עד שנפטר ר' יוסי בן קיסמא\u0004 מחוליו, \u0003והלכו כל גדולי רומי לקברו והספידוהו הספד גדול, ובחזרתן מצאוהו לר' חנינא בן תרדיון שהיה יושב ועוסק בתורה ומקהיל קהלות ברבים וספר תורה מונח לו בחיקו.\u0004","\u0003הביאוהו\u0004 לדין \u0003וכרכוהו בספר תורה, והקיפוהו בחבילי זמורות והציתו בהן את האור\u0004 (אש), \u0003והביאו ספוגין של צמר ושראום במים והניחום על לבו, כדי שלא תצא נשמתו\u0004 ב\u0003מהרה,\u0004 אלא יתייסר הרבה בשריפה. \u0003אמרה לו בתו: אבא, אראך בכך\u0004 ביסורים אלה? \u0003אמר לה: אילמלי אני נשרפתי לבדי, היה הדבר קשה לי. עכשיו שאני נשרף וספר תורה עמי, מי שמבקש עלבונה של ספר תורה הוא יבקש עלבוני.\u0004","\u0003אמרו לו תלמידיו: רבי, מה אתה רואה? אמר להן:\u0004 רואה אני \u0003גליון נשרפין ואותיות\u0004 שבהם \u0003פורחות\u0004 למרום. אמרו לו: \u0003אף אתה פתח פיך ותכנס [בך] האש,\u0004 שתמות מהרה! \u0003אמר להן: מוטב שיטלנה\u0004 את נשמתי \u0003מי שנתנה,\u0004 הקב\"ה, \u0003ואל יחבל הוא\u0004 האדם \u0003בעצמו\u0004 להקדים את מותו.","\u0003אמר לו קלצטונירי\u0004 (התליין): \u0003רבי, אם אני מרבה בשלהבת ונוטל ספוגין של צמר מעל לבך\u0004 ובכך מקרב את מותך וממעט את יסוריך, \u0003אתה מביאני לחיי העולם הבא? אמר לו: הן.\u0004 אמר לו התליין: \u0003השבע לי\u0004 על כך! \u0003נשבע לו. מיד הרבה בשלהבת ונטל ספוגין של צמר מעל לבו, יצאה נשמתו במהרה. אף הוא\u0004 התליין \u0003קפץ ונפל לתוך האור\u0004 ומת.","\u0003יצאה בת קול ואמרה: ר' חנינא בן תרדיון וקלצטונירי מזומנין הן לחיי העולם הבא. בכה רבי ואמר: יש קונה עולמו בשעה אחת\u0004 כתליין זה, \u0003ויש קונה עולמו בכמה שנים\u0004 כמו ר' חנינא בן תרדיון.","מספרים כי \u0003ברוריא דביתהו\u0004 \u0005[אשתו]\u0006 של \u0003ר' מאיר, ברתיה\u0004 \u0005[בתו]\u0006 של \u0003ר' חנינא בן תרדיון הואי\u0004 \u0005[היתה],\u0006 \u0003אמרה ליה\u0004 \u0005[לו]\u0006 לר' מאיר: \u0003זילא בי מלתא דיתבא אחתאי\u0004 \u0005[מזולזל בי הדבר שאחותי יושבת]\u0006 \u0003בקובה של זונות,\u0004 עשה משהו להצילה. \u0003שקל תרקבא דדינרי ואזל\u0004 \u0005[נטל תרקב של דינרים והלך\u0006 לשם\u0005],\u0006 \u0003אמר: אי\u0004 \u0005[אם]\u0006 \u0003לא איתעביד\u0004 \u0005[נעשה]\u0006 \u0003בה איסורא\u0004 \u0005[איסור],\u0006 \u0003מיתעביד ניסא\u0004 \u0005[ייעשה\u0006 לה \u0005נס],\u0006 \u0003אי עבדה איסורא\u0004 \u0005[אם עשתה איסור]\u0006 — \u0003לא איתעביד\u0004 \u0005[ייעשה]\u0006 \u0003לה ניסא\u0004 \u0005[נס].\u0006","\u0003אזל נקט נפשיה כחד פרשא\u0004 \u0005[הלך,\u0006 ו\u0005עשה עצמו כאחד הפרשים],\u0006 \u0003אמר לה: השמיעני\u0004 (היבעלי) \u0003לי, אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003דשתנא אנא\u0004 \u0005[נידה אני]\u0006 ואיני יכולה. \u0003אמר לה: מתרחנא מרתח\u0004 \u0005[אני אחכה\u0006 לך\u0005]\u0006 עד לאחר הזמן. \u0003אמרה לו: נפישין טובא, ואיכא טובא הכא דשפירן מינאי\u0004 \u0005[יש הרבה\u0006 נשים בקובה זו, \u0005ויש כאן הרבה\u0006 נשים \u0005ש\u0006הן \u0005יפות ממני],\u0006 שדחתה אותו. \u0003אמר: שמע מינה לא עבדה איסורא\u0004 \u0005[למד מכאן,\u0006 ש\u0005לא עשתה איסור],\u0006 \u0003כל\u0004 מי \u0003דאתי, אמרה ליה הכי\u0004 \u0005[שבא, אומרת לו כך].\u0006","\u0003אזל לגבי\u0004 \u0005[הלך אצל]\u0006 ה\u0003שומר דידה\u0004 \u0005[שלה],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הבה ניהלה\u0004 \u0005[תן אותה\u0006 לי\u0005],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מיסתפינא ממלכותא\u0004 \u0005[מתיירא אני מן המלכות]\u0006 שלא יענישוני על כך. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שקול תרקבא דדינרא\u0004 \u0005[קח\u0006 את \u0005תרקב הדינרים],\u0006 \u0003פלגא פלח ופלגא להוי לך\u0004 \u0005[חצי תיתן\u0006 לשלטונות כשידרשו ממך את הכסף \u0005וחצי יהיה לך].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003וכי שלמי, מאי איעביד\u0004 \u0005[וכאשר יגמרו\u0006 הדינרים הללו, \u0005מה אעשה\u0006 אז\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003\"אלהא דמאיר\u0004 \u0005[אלהי מאיר]\u0006 \u0003ענני\" ומתצלת\u0004 \u0005[ותינצל].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 השומר:"],["\u0003ומי יימר דהכי איכא\u0004 \u0005[ומי יאמר שכך הוא]\u0006 שיש בכוח אמירה זו להצילני? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' מאיר: \u0003השתא חזית\u0004 \u0005[עכשיו תראה]\u0006\u0003. הוו הנהו כלבי דהוו קא אכלי אינשי\u0004 \u0005[היו\u0006 שם \u0005כלבים\u0006 טורפים \u0005שהיו אוכלים אנשים],\u0006 \u0003שקל קלא שדא בהו, הוו קאתו למיכליה\u0004 \u0005[לקח רגב\u0006 אדמה \u0005השליך בהם, היו באים לאוכלו],\u0006 \u0003אמר: אלהא דמאיר ענני\u0004 \u0005[אלוהי מאיר ענני]!\u0006 \u0003שבקוה\u0004 \u0005[הניחוהו].\u0006 ראה דבר זה, \u0003ויהבה ליה\u0004 \u0005[ונתנה לו]\u0006 את בת ר' חנינא בן תרדיון לר' מאיר.","\u0003לסוף אשתמע מילתא בי מלכא\u0004 \u0005[נשמע הדבר בבית המלך],\u0006 \u0003אתיוה אסקוה לזקיפה\u0004 \u0005[הביאוהו\u0006 ו\u0005העלוהו לתליה],\u0006 \u0003אמר: אלהא דמאיר ענני\u0004 \u0005[אלוהי מאיר ענני]!\u0006 \u0003אחתוה\u0004 \u0005[הורידו אותו],\u0006 שלא יכלו לתלותו. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מאי האי\u0004 \u0005[מה זה]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003הכי הוה\u0004 \u0005[כך היה]\u0006 \u0003מעשה,\u0004 וסיפר להם כל המעשה שקרה.","\u0003אתו\u0004 \u0005[באו]\u0006 ו\u0003חקקו לדמותיה\u0004 \u0005[את דמותו]\u0006 של \u0003ר' מאיר אפיתחא דרומי\u0004 \u0005[על פתחה של רומי],\u0006 במקום בו עוברים כולם, \u0003אמרי\u0004 \u0005[אמרו]:\u0006 \u0003כל\u0004 מי \u0003דחזי לפרצופא הדין\u0004 \u0005[שרואה את הפרצוף הזה]\u0006 — \u0003לייתיה\u0004 \u0005[שיביא אותו].\u0006 \u0003יומא חדא חזיוהי\u0004 \u0005[יום אחד ראו אותו],\u0006 \u0003רהט אבתריה\u0004 \u0005[רצו אחריו],\u0006 \u0003רהט מקמייהו\u0004 \u0005[רץ מפניהם],\u0006 \u0003על לבי\u0004 \u0005[נכנס לבית]\u0006 \u0003זונות\u0004 להיחבא. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שכך התחמק: \u0003בשולי גוים חזא\u0004 \u0005[ראה],\u0006 \u0003טמש בהא ומתק בהא\u0004 \u0005[טבל\u0006 בתבשיל \u0005ב\u0006אצבע \u0005זו וטעם ב\u0006אצבע \u0005זו]\u0006 כאילו הוא אוכל מתבשילם. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 \u0003אליהו אדמי להו\u0004 \u0005[נדמה להם]\u0006 \u0003כזונה,\u0004 \u0003כרכתיה\u0004 \u0005[חיבקה אותו],\u0006 את ר' מאיר, \u0003אמרי\u0004 \u0005[אמרו]\u0006 הרודפים אחריו: \u0003חס ושלום, אי\u0004 \u0005[אם]\u0006 \u0003ר' מאיר הוה\u0004 \u0005[היה],\u0006 \u0003לא הוה עביד הכי\u0004 \u0005[היה עושה כך],\u0006 וכך ניצל.","\u0003קם ערק, אתא\u0004 \u0005[עמד ברח, ובא]\u0006 \u0003לבבל\u0004 משום הסכנה. ומעירים: \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003מהאי מעשה\u0004 \u0005[ממעשה זה]\u0006 ברח, \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003ממעשה\u0004 של \u0003ברוריא\u0004 אשתו שהתאבדה בגללו ברח, ומחמת הבושה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ההולך לאיצטדינין\u0004 או \u0003לכרקום\u0004 (מצור) שעושים לאנשי הצבא החונים שם מיני צחוק, \u0003וראה שם את הנחשים\u0004 (המנחשים והמכשפים) \u0003ואת החברין\u0004 (לוחשי לחשים), \u0003בוקיון ומוקיון ומוליון ולוליון, בלורין סלגורין\u0004 שהם מיני ליצנים — \u0003הרי זה מושב לצים, ועליהם הכתוב אומר: \"אשרי האיש אשר לא הלך וגו'\u0004 ובמושב לצים לא ישב \u0003כי אם בתורת ה' חפצו\"\u0004 (תהלים א, א —ב), \u0003הא\u0004 \u0005[הרי]\u0006 \u0003למדת\u0004 מכאן, \u0003שדברים הללו מביאין את האדם לידי ביטול תורה,\u0004 שאם אינו יושב במושב לצים — תורת ה' חפצו.","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא: \u0003[הולכין] לאיצטדינין מותר, מפני שצווח\u0004 בזמן הצורך \u0003ומציל\u0004 אדם מישראל שעומד ליהרג שם, \u0003ולכרקום מותר\u0004 ללכת \u0003מפני ישוב מדינה,\u0004 שלפעמים הוא יכול להציל את בני העיר הנצורים כשהוא נמצא בין הצרים, \u0003ובלבד שלא יתחשב עמהם\u0004 כאחד מהם, \u0003ואם נתחשב עמהם\u0004 — \u0003אסור.\u0004 ואם כן, \u0003קשיא\u0004 \u0005[קשה]\u0006 מ\u0003איצטדינין\u0004 על \u0003איצטדינין,\u0004 וכן \u0003קשיא\u0004 \u0005[קשה]\u0006 מ\u0003כרקום\u0004 על \u0003כרקום!\u0004","ומוסיפים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 מ\u0003כרקום\u0004 על \u0003כרקום לא קשיא\u0004 \u0005[אינו קשה],\u0006 אפשר לפרש: \u0003כאן\u0004 שאסור — \u0003במתחשב עמהן, כאן\u0004 שמותר — \u0003בשאין מתחשב עמהן,\u0004 \u0003אלא\u0004 מ\u0003איצטדינין\u0004 על \u0003איצטדינין קשיא\u0004 \u0005[קשה]!\u0006","ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא,\u0004 \u0003[דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006\u0003]: אין הולכין לאיצטדינין מפני\u0004 שהוא \u0003מושב לצים. ור' נתן מתיר מפני שני דברים: אחד, מפני שצווח ומציל\u0004 לפעמים אדם שעומדים להרגו. \u0003ואחד, מפני\u0004 שאם גם אינו מציל, פעמים \u0003שמעיד עדות אשה להשיאה,\u0004 שהוא רואה בעיניו שנהרג בעלה באיצטדיון.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין הולכין לטרטיאות ולקרקסיאות\u0004 (לתיאטראות ולבתי קרקס), \u0003מפני שמזבלין שם זיבול\u0004 כלומר, זובחים שם זבח \u0003לעבודה זרה, דברי ר' מאיר. וחכמים אומרים:\u0004 ללכת ל\u0003מקום שמזבלין\u0004 — \u0003אסור מפני חשד עבודה זרה, ומקום שאין מזבלין שם\u0004 — \u0003אסור\u0004 על כל פנים \u0003מפני מושב לצים.\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 בין טעם זה לטעם אחר, שהרי לדעת שניהם אסור? ומשיבים, \u0003אמר ר' חנינא מסורא:\u0004 אם \u0003נשא ונתן\u0004 שם \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 שלדעת ר' מאיר כל מה שעושה שם מסחר יש בו חשש של דמי עבודה זרה, ולדעת חכמים לאו דווקא.","לאחר שהוזכר ענין מושב לצים, מביאים כמה דברים בגנות הליצנות. \u0003דרש ר' שמעון בן פזי, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"אשרי האיש אשר לא הלך בעצת רשעים ובדרך חטאים לא עמד ובמושב לצים לא ישב\"\u0004 (תהלים א, א)? ויש לשאול: \u0003וכי מאחר שלא הלך, היכן עמד? ומאחר שלא עמד, היכן ישב? ומאחר שלא ישב, היכן לץ?\u0004 שהרי אם לא הולך כלל, ממילא אינו מגיע לכל אותו ענין!","\u0003[אלא] לומר לך, שאם הלך\u0004 — אז \u0003סופו לעמוד\u0004 שם, \u0003ואם עמד\u0004 — \u0003סופו לישב, ואם ישב\u0004 — \u0003סופו ללוץ\u0004 עימם, \u0003ואם לץ\u0004 — \u0003עליו הכתוב אומר: \"אם חכמת חכמת לך ו\u0004אם \u0003לצת לבדך תשא\"\u0004 (משלי ט, יב).","\u0003אמר ר' אליעזר: כל המתלוצץ יסורין באין עליו, שנאמר: \"ועתה אל תתלוצצו פן יחזקו מוסריכם\"\u0004 (ישעיהו כח, כב), ו\"מוסריכם\" מלשון יסורים. וכן \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבא לרבנן\u0004 \u0005[לחכמים]\u0006 שישבו לפניו: \u0003במטותא\u0004 \u0005[בבקשה],\u0006 \u0003בעינא מינייכו\u0004 \u0005[אני מבקש מכם]\u0006 ש\u0003לא תתלוצצו,\u0004 כדי ש\u0003לא ליתו עלייכו\u0004 \u0005[יבואו עליכם]\u0006 \u0003יסורין.\u0004","\u0003אמר רב קטינא: כל המתלוצץ מזונותיו מתמעטין, שנאמר: \"משך ידו את לצצים\"\u0004 (הושע ז, ה), לומר שכל המתלוצץ הקב\"ה מושך ידו ממנו ואינו מפרנסו. \u0003אמר ר' שמעון בן לקיש: כל המתלוצץ נופל בגיהנם, שנאמר: \"זד יהיר לץ שמו עושה בעברת זדון\"\u0004 (משלי כא, כד), \u0003ואין עברה אלא גיהנם, שנאמר\u0004 בתיאור יום הדין הגדול ועונשיו: \u0003\"יום עברה היום ההוא\"\u0004 (צפניה א, טו).","וכן \u0003אמר ר' אושעיא\u0004 על פרט אחר בפסוק זה: \u0003כל המתייהר\u0004 (המתגאה) \u0003נופל בגיהנם, שנאמר: \"זד יהיר לץ שמו עושה בעברת זדון\", ואין עברה אלא גיהנם, שנאמר: \"יום עברה היום ההוא\". אמר ר' חנילאי בר חנילאי: כל המתלוצץ גורם כלייה לעולם, שנאמר: \"ועתה אל תתלוצצו פן יחזקו מוסריכם [כי] כלה\u0004 (כלייה) \u0003ונחרצה שמעתי\u0004 מאת ה' \" (ישעיה כח, כד).","\u0003אמר ר' אליעזר: קשה היא\u0004 הליצנות, \u0003שתחילתה יסורין וסופו כלייה. דרש ר' שמעון בן פזי:\u0004 נאמר: \u0003\"אשרי האיש אשר לא הלך\u0004 בעצת רשעים\" — כוונתו \u0003לטרטיאות ולקרקסיאות של גוים, \"ובדרך חטאים לא עמד\"\u0004 — \u0003זה שלא עמד בקנגיון\u0004 (במקום ציד), \u0003\"ובמושב לצים לא ישב\"\u0004 — \u0003שלא ישב בתחבולות\u0004 במקום בו אנשים יושבים ועוסקים בהתחכמות וליצנות.","\u0003שמא יאמר אדם: הואיל ולא הלכתי לטרטיאות ולקרקסיאות ולא עמדתי בקנגיון, אלך ואתגרה בשינה.\u0004 כלומר, ארבה בשינה ולא אעשה דבר? \u0003תלמוד לומר: \"ובתורתו יהגה יומם ולילה\"\u0004 (תהלים א, ב), כלומר, לא די לו להימנע מעבירה, אלא צריך לעסוק בפועל בלימוד התורה.","כיוון שהוזכר כתוב זה, מביאים דרשה אחרת עליו. \u0003אמר רב שמואל בר נחמני אמר ר' יונתן: \"אשרי האיש אשר לא הלך בעצת רשעים\"\u0004 (תהלים א, א) — \u0003זה\u0004"],["\u0003אברהם אבינו, שלא הלך בעצת אנשי דור הפלגה, שרשעים היו, שנאמר\u0004 בהם שנועצו ואמרו זה לזה: \u0003\"הבה נבנה לנו עיר\u0004 ומגדל וראשו בשמים\" (בראשית יא, ד), וכיוונו להרע. \u0003\"ובדרך חטאים לא עמד\"\u0004 (תהלים א, א) — \u0003שלא עמד בעמידת סדום, שחטאים היו, שנאמר: \"ואנשי סדם רעים וחטאים לה' מאד\"\u0004 (בראשית יג, יג),","\u0003\"ובמושב לצים לא ישב\"\u0004 (תהלים א, א) — \u0003שלא ישב במושב אנשי פלשתים, מפני שלצנים היו,\u0004 עוסקים במעשי ליצנות ושחוק, \u0003ש\u0004כן \u0003נאמר\u0004 בהם אף בתקופה מאוחרת יותר: \u0003\"ויהי כטוב לבם ויאמרו קראו לשמשון וישחק לנו\"\u0004 (שופטים טז, כה).","לאחר שנדרש הפסוק \"אשרי האיש\" שבתחילת ספר תהלים, מביאים כאן דרשה על פסוק דומה: \u0003\"אשרי איש ירא [את] ה'\u0004 במצוותיו חפץ מאד\" (תהלים קיב, א), ויש לשאול: וכי \u0003אשרי איש ולא אשרי אשה?\u0004 מדוע מדגיש הכתוב דווקא איש? \u0003אמר רב עמרם אמר רב: אשרי מי שעושה תשובה כשהוא איש,\u0004 כשעודו \"איש\" — במלוא אונו וכוחו, ולא כשהוא זקן. \u0003ר' יהושע בן לוי אמר: אשרי מי שמתגבר על יצרו\u0004 \u0003כאיש\u0004 בתוקף ועוז.","עוד נאמר שם: \u0003\"במצותיו חפץ מאד\"\u0004 — \u0003אמר ר' אלעזר: במצותיו\u0004 עצמן, \u0003ולא בשכר מצותיו. והיינו דתנן\u0004 \u0005[וזהו ששנינו]\u0006 במשנה במסכת אבות דברי אנטיגנוס איש סוכו, \u0003הוא היה אומר: אל תהיו כעבדים המשמשין את הרב\u0004 (האדון) \u0003על מנת לקבל פרס\u0004 (שכר), \u0003אלא היו כעבדים המשמשין את הרב שלא על מנת לקבל פרס.\u0004","ושבים לדרוש את הפסוק שעסקנו בו מתחילה: \u0003\"כי אם בתורת ה' חפצו\"\u0004 (תהלים א, ב), \u0003אמר רב: אין אדם לומד תורה אלא ממקום\u0004 בתורה \u0003ש\u0004בו \u0003לבו חפץ, שנאמר: \"כי אם בתורת ה' חפצו\",\u0004 בתורה שבה הוא חפץ ללמוד.","מסופר, \u0003לוי ור' שמעון ברבי\u0004 (בנו של רבי) \u0003יתבי קמיה\u0004 \u0005[\u0006היו \u0005יושבים לפני]\u0006 \u0003רבי, וקא פסקי סידרא\u0004 \u0005[והיו לומדים בסדרי המקרא],\u0006 \u0003סליק ספרא\u0004 \u0005[נסתיים הספר]\u0006 שלמדו, והיו צריכים להתחיל אחר, \u0003לוי אמר: לייתו [לן]\u0004 \u0005[יביאו לנו]\u0006 ספר \u0003משלי\u0004 ללמוד בו, \u0003ר' שמעון ברבי אמר: לייתו [לן] תילים\u0004 \u0005[יביאו לנו\u0006 ספר \u0005תהלים],\u0006 \u0003כפייה ללוי ואייתו תילים\u0004 \u0005[כפה אותו\u0006 ר' שמעון \u0005את לוי והביאו\u0006 ספר \u0005תהלים].\u0006 \u0003כי מטו הכא\u0004 \u0005[כאשר הגיעו לכאן]\u0006 לפסוק: \u0003\"כי אם בתורת ה' חפצו\", פריש\u0004 \u0005[פירש]\u0006 \u0003רבי ואמר: אין אדם לומד תורה אלא ממקום שלבו חפץ. אמר לוי: רבי, נתת לנו\u0004 (כלומר: לי) \u0003רשות לעמוד\u0004 ולצאת, מתוך דבריך אלו, שהרי אני חפץ ללמוד בספר משלי ולא בספר תהלים.","ועוד בדרשת פסוק זה, \u0003אמר ר' אבדימי בר חמא: כל העוסק בתורה\u0004 — \u0003הקדוש ברוך הוא עושה לו\u0004 את \u0003חפציו\u0004 (רצונו), \u0003שנאמר: \"כי אם בתורת ה' חפצו\",\u0004 מי שעוסק בתורת ה' — ה' עושה לו חפצו. וכדברי רבי לעיל גם \u0003אמר רבא: לעולם ילמוד אדם תורה במקום שלבו חפץ, שנאמר: \"כי אם בתורת ה' חפצו\". ו\u0004עוד","\u0003אמר רבא\u0004 בדרשה על אותו הפסוק: \u0003בתחילה נקראת\u0004 התורה \u0003על שמו של הקדוש ברוך הוא ולבסוף\u0004 היא \u0003נקראת על שמו\u0004 של הלומד בה, \u0003שנאמר\u0004 בתחילה: \u0003\"בתורת ה' חפצו\",\u0004 ובהמשך — \u0003\"ובתורתו יהגה יומם ולילה\",\u0004 נמצא שעל ידי שהוגה בה נקראת התורה תורתו של הלומד.","\u0003ו\u0004עוד \u0003אמר רבא\u0004 בדרשת פסוק זה: \u0003לעולם ילמד אדם תורה\u0004 ירבה בידיעתה, \u0003ואחר כך יהגה\u0004 יעיין ויתעמק בה, \u0003שנאמר\u0004 בתחילה: \u0003\"בתורת ה'\u0004 חפצו\", שלומד את התורה כמות שהיא, \u0003והדר\u0004 \u0005[ואחר כך]\u0006 נאמר \u0003\"ובתורתו יהגה\",\u0004 יעיין.","\u0003ו\u0004עוד \u0003אמר רבא\u0004 בדרך לימוד התורה: \u0003לעולם ליגריס איניש\u0004 \u0005[יגרוס אדם],\u0006 יחזור על משנתו, \u0003ואף על גב דמשכח, ואף על גב דלא ידע מאי קאמר\u0004 \u0005[ואף על פי ש\u0006הוא \u0005שוכח, ואף על פי שאינו יודע מה הוא אומר],\u0006 \u0003שנאמר\u0004 על לימוד התורה: \u0003\"גרסה נפשי לתאבה\u0004 אל משפטיך בכל עת\" (תהלים קיט, כ), \u0003\"גרסה\" כתיב\u0004 \u0005[נאמר],\u0006 \u0003ולא כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"טחנה\",\u0004 שאפילו גריסה בלבד (כעין טחינה גסה) גם היא דבר טוב שהנפש רוצה וצריכה לו.","\u0003רבא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]\u0006 בין מקראות, \u0003כתיב\u0004 \u0005[נאמר]\u0006 על התורה שהיא קוראת לו לאדם \u0003\"על גפי\u0004 מרומי קרת\" (משלי ט, ג), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"על כסא\u0004 מרומי קרת\" (משלי ט, יד)! ומסביר: \u0003בתחלה\u0004 לומד התורה הריהו \u0003על גפי\u0004 שנמצא כאילו על הכנפיים, בצד, \u0003ולבסוף,\u0004 כאשר הוא מתקדם בלימודו, הריהו \u0003על כסא,\u0004 במקום מיושב ומכובד.","ועוד סתירה דומה: \u0003כתיב\u0004 \u0005[נאמר]\u0006 על התורה שהיא \u0003\"בראש מרומים\"\u0004 (משלי ח, ב), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בה שהיא \u0003\"עלי דרך\"\u0004 (משלי ח, ב)! ומסבירים: \u0003בתחלה\u0004 לומד אדם \u0003בראש מרומים\u0004 במקום נסתר, \u0003ולבסוף\u0004 מגיע לכך שהוא אומר את הדברים \u0003עלי דרך\u0004 בפרסום.","\u0003עולא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005],\u0006 בין מקראות, \u0003כתיב\u0004 \u0005[נאמר]\u0006 במקום אחד \u0003\"שתה מים מבורך\"\u0004 (משלי ה, טו), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 אחרי כן: \u0003\"ונוזלים מתוך בארך\"\u0004 (משלי ה, טו)! והסביר: \u0003בתחלה שתה מבורך\u0004 שבבור יש מים מכונסים ממקום אחר, שתחילה לומד את הקיים והידוע, \u0003ולבסוף \"ונוזלים מתוך בארך\"\u0004 שהתורה תהיה נובעת ממנו, ויחדש בה דברים שלא שמע.","ועוד בעניין לימוד תורה, \u0003אמר רבא אמר רב סחורה אמר רב הונא, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"הון מהבל ימעט וקבץ על יד ירבה\"\u0004 (משלי יג, יא)? \u0003אם עושה אדם תורתו חבילות חבילות\u0004 (\"מהבל\" כמו \"מחבל\") שלומד הרבה, ואינו חוזר ואינו זוכר — הרי הוא \u0003מתמעט, ואם קובץ על יד\u0004 שלומד מעט מעט, וחוזר כל פעם על מה שלמד — \u0003ירבה\u0004 ויתגדל בה.","\u0003אמר רבא: ידעי רבנן להא מילתא ועברי עלה\u0004 \u0005[יודעים חכמים את הדבר הזה ועוברים עליו].\u0006 \u0003אמר רב נחמן בר יצחק: אנא עבידתה\u0004 \u0005[אני עשיתי זאת]\u0006 \u0003ו\u0004אכן נשאר \u0003קיים בידי.\u0004","\u0003אמר רב שיזבי משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' אלעזר בן עזריה, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"לא יחרך רמיה צידו\"\u0004 (משלי יב, כג)? \u0003לא יחיה ולא יאריך ימים\u0004 (\"יחרוך\" כעין נוטריקון של \"יחיה\" ו\"יאריך\") \u0003צייד הרמאי\u0004 כלומר, מי שמראה עצמו כלומד הרבה, וכל זה רק כדי להראות לאחרים.","\u0003ורב ששת אמר:\u0004 הכוונה בפסוק זה הפוכה היא, ש\u0003צייד הרמאי יחרוך\u0004 צידו, צייד הנוהג בערמה יגרום לצידו שלא יוכל עוד לברוח ממנו. \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בהסבר הפסוק על דרך זו: \u0003משל לאדם שצד צפרין\u0004 (ציפורים), \u0003אם משבר כנפיה של ראשונה\u0004 שהוא צד שלא תוכל לעוף ממנו — \u0003כולם\u0004 כל הציפורים שהוא צד \u0003מתקיימות בידו, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אין מתקיימות בידו,\u0004 וכשתופס את השניה הראשונה פורחת. וכן בדברים שלומד.","נאמר בהמשך הפסוק שנדרש לעיל: \u0003\"והיה כעץ שתול על פלגי מים\"\u0004 (תהלים א, ב), \u0003אמרי דבי\u0004 \u0005[אמרו\u0006 החכמים של \u0005בית]\u0006 \u0003ר' ינאי: כעץ שתול\u0004 שנעקר ממקומו הראשון ונשתל במקום אחר, \u0003ולא כעץ נטוע\u0004 הנשאר קבוע במקומו. לומר ש\u0003כל הלומד תורה מרב אחד\u0004 — \u0003אינו רואה סימן ברכה לעולם,\u0004 אלא צריך ללמוד תורה מאנשים שונים, שעל ידי כך תרבה חכמתו.","ובעניין זה \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב חסדא לרבנן\u0004 \u0005[לחכמים]:\u0006 \u0003בעינא דאימא לכו מלתא, ומסתפינא דשבקיתו לי ואזליתו\u0004 \u0005[רצוני לומר לכם דבר, ואני מפחד שתעזבו אותי ותלכו],\u0006 ומהו הדבר? \u0003כל הלומד תורה מרב אחד\u0004 — \u0003אינו רואה סימן ברכה לעולם,\u0004 ומסופר כי כששמעו זאת חכמים אכן \u0003שבקוהו ואזול קמיה\u0004 \u0005[עזבוהו והלכו\u0006 ללמוד \u0005לפני]\u0006 \u0003רבא. אמר להו\u0004 \u0005[להם]\u0006 רב חסדא לחכמים: \u0003הני מילי סברא\u0004 \u0005[דברים אלה\u0006 שאמרתי הינם לעניין \u0005סברה]\u0006 שלשם חידוד הסברה ראוי להתבונן ולהקשיב לשיטות שונות מפי אנשים שונים, \u0003אבל גמרא\u0004 \u0005[\u0006עיקר \u0005הלימוד,\u0006 הגרסה\u0005]\u0006 — \u0003מרב אחד עדיף,\u0004 \u0003כי היכי\u0004 \u0005[כדי]\u0006"],["ש\u0003לא ליפלוג לישני\u0004 \u0005[ייחלקו הלשונות],\u0006 שכל אחד מהם גורס את השמועה בלשון אחרת קצת, ואם לא תהיה לאדם גרסה ברורה ממקור אחד יתבלבלו הדברים בידו. ושבים לדרוש את הפסוק שעסקנו בו, שנאמר \"והיה כעץ שתול \u0003על פלגי מים\"\u0004 (תהלים א, ג) \u0003אמר ר' תנחום בר חנילאי:\u0004 יש לדרוש \"פלגי\" במובן חלוקה, \u0003לעולם ישלש\u0004 \u0003אדם שנותיו\u0004 לשלושה חלקים: ב\u0003שליש\u0004 מהם יעסוק \u0003במקרא,\u0004 ב\u0003שליש\u0004 האחר יעסוק \u0003במשנה,\u0004 וב\u0003שליש\u0004 האחר יעסוק \u0003בתלמוד,\u0004 כלומר, משא ומתן והבנה של המשנה.","ותמהים: \u0003מי ידע איניש\u0004 \u0005[והאם יודע אדם]\u0006 \u0003כמה חיי\u0004 \u0005[כמה\u0006 הוא \u0005חי]\u0006 כדי שידע לחלק את שנותיו? ומשיבים: \u0003כי קאמרינן\u0004 \u0005[כאשר אנו אומרים]\u0006 לחלק — הרי זה \u0003ביומי\u0004 \u0005[בימים],\u0006 כלומר שיחלק את הימים באופן זה.","נאמר בהמשך הפסוק: \u0003\"אשר פריו יתן בעתו\", אמר רבא\u0004 בפירוש הפסוק: \u0003אם \"פריו יתן בעתו\"\u0004 כלומר, אם יוציא פרי מתורתו, כלומר שיעשה מה שלמד, הרי אז — \u0003\"ועלהו לא יבול\",\u0004 התורה מחיה אותו, \u0003ואם לאו\u0004 \u0005[לא]\u0006 לומד לשם מעשה — \u0003על הלומד ועל המלמד עליהם\u0004 באופן זה \u0003הכתוב אומר: \"לא כן הרשעים כי אם\u0004 כמוץ אשר תדפנו רוח\" (תהלים א, ד).","\u0003אמר ר' אבא אמר רב הונא אמר רב, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"כי רבים חללים הפילה\"\u0004 (משלי ז, כו)? \u0003זה תלמיד שלא הגיע ל\u0004שלב של \u0003הוראה\u0004 לאחרים, \u0003ומורה\u0004 לרבים, שהוא כעין נפל (\"הפילה\"), \u0003\"ועצמים כל הרוגיה\"\u0004 — \u0003זה תלמיד שהגיע להוראה\u0004 שהוא כבר התעצם בתורה \u0003ואינו מורה\u0004 לאחרים.","\u0003ועד כמה?\u0004 עד איזה גיל אינו נחשב ראוי להוראה? \u0003עד ארבעין שנין\u0004 \u0005[שנים].\u0006 ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבא אורי\u0004 \u0005[הורה]\u0006 לרבים עוד לפני גיל ארבעים! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 מדובר שהם \u0003שוין,\u0004 כאשר אין מי שהוא גדול ממנו, מותר לו להורות קודם שימלאו לו שנים אלה.","ועוד על מה שנאמר: \u0003\"ועלהו לא יבול\"\u0004 (תהלים א, ג), \u0003אמר רב אחא בר אדא אמר רב, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003רב אחא בר אבא אמר רב המנונא אמר רב:\u0004 יש כאן רמז \u0003שאפילו שיחת חולין של תלמידי חכמים\u0004 שהיא בגדר עלים ולא בגדר פירות, גם היא \u0003צריכה תלמוד, שנאמר: \"ועלהו לא יבול\".\u0004","ובהמשך הפסוק נאמר: \u0003\"וכל אשר יעשה יצליח\", אמר ר' יהושע בן לוי: דבר זה כתוב בתורה ושנוי בנביאים ומשולש בכתובים,\u0004 ש\u0003כל העוסק בתורה\u0004 — \u0003נכסיו מצליחין לו.\u0004 ומפרטים: \u0003כתוב בתורה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ושמרתם את דברי הברית הזאת ועשיתם אתם למען תשכילו את כל אשר תעשון\"\u0004 (דברים כט, ח), לומר שיש לאדם הצלחה (\"תשכילו\") במעשיו ובקנייניו (\"כל אשר תעשון\") כאשר הוא עוסק בתורה.","\u0003שנוי בנביאים\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא ימוש ספר התורה [הזה] מפיך והגית בו יומם ולילה למען תשמר לעשות ככל הכתוב בו כי אז תצליח את דרכיך ואז תשכיל\"\u0004 (יהושע א, ח). \u0003משולש בכתובים\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי אם בתורת ה' חפצו ובתורתו יהגה יומם ולילה, והיה כעץ שתול על פלגי מים אשר פריו יתן בעתו ועלהו לא יבול וכל אשר יעשה יצליח\"\u0004 (תהלים א, ב—ג).","מסופר, היה \u0003מכריז\u0004 ברבים \u0003ר' אלכסנדרי,\u0004 כדרך המוכרים: \u0003מאן בעי חיי, מאן בעי חיי\u0004 \u0005[מי רוצה חיים, מי רוצה חיים]?\u0006 \u0003כנוף ואתו כולי עלמא לגביה\u0004 \u0005[התאספו ובאו הכל אליו]\u0006 לקנות ממנו\u0005,\u0006 \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003הב לן חיי\u0004 \u0005[תן לנו חיים],\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 את הפסוק: \u0003\"מי האיש החפץ חיים\u0004 אוהב ימים לראות טוב \u0003נצר לשונך מרע\u0004 ושפתיך מדבר מרמה\" (תהלים לד, יג —יד).","ומסבירים מה שנאמר בהמשך פסוק זה: \u0003\"סור מרע ועשה טוב\", שמא יאמר\u0004 אדם: \u0003נצרתי לשוני מרע ושפתי מדבר מרמה, [אלך] ואתגרה בשינה\u0004 ולא אעשה דבר? \u0003תלמוד לומר: \"סור מרע ועשה טוב\",\u0004 שצריך אדם גם לעשות טוב בפועל, ולא די לו בזה שהוא נמנע מעבירה, ו\u0003אין \"טוב\" אלא תורה, שנאמר: \"כי לקח טוב נתתי לכם תורתי אל תעזבו\"\u0004 (משלי ד, ב).","שנינו במשנה: בונים עמהם בימוסיאות ומרחצאות, \u0003הגיע לכיפה מקום שמעמידין בה עבודה זרה\u0004 מושך הבנאי היהודי ידו ואינו משתתף בבניה. \u0003אמר ר' אלעזר אמר ר' יוחנן:\u0004 מכל מקום \u0003אם בנה\u0004 את הכיפה — \u0003שכרו מותר.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, הלוא כיפה זו רק \u0003משמשי עבודה זרה הן,\u0004 דברים שמשתמשים בהם לעבודה זרה, \u0003ומשמשי עבודה זרה בין ל\u0004דעת \u0003ר' ישמעאל בין ל\u0004דעת \u0003ר' עקיבא,\u0004 שנחלקו בענין עבודה זרה לעצמה להלן (עבודה זרה נא,ב) — \u0003אינן אסורין\u0004 בהנאה \u0003עד שיעבדו\u0004 בהם עבודה זרה.","\u0003אמר ר' ירמיה: לא נצרכה\u0004 הלכה זו שאמר ר' אלעזר, \u0003אלא לעבודה זרה עצמה,\u0004 ששכרה מותר אם עשאה. ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]:\u0006 \u0003עבודה זרה של ישראל אסורה מיד\u0004 כשעושה אותה, \u0003ושל גוי\u0004 אינה אסורה בהנאה \u0003עד שתעבד\u0004 — \u0003שפיר\u0004 \u0005[יפה],\u0006 משום שעבודה זרה זו שבנה אותו ישראל עבור גוים עדיין לא נעבדה, ולכן היא מותרת בהנאה. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]:\u0006 עבודה זרה \u0003של גוי אסורה מיד\u0004 כשהיא נעשית, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","\u0003אלא אמר רבה בר עולא: לא נצרכה\u0004 הלכה זו ששכרה מותרת \u0003אלא במכוש אחרון\u0004 כלומר, במעשה האחרון שהוא עושה בה להשלים את עבודתה. וטעם הדבר, כי \u0003עבודה זרה מאן קא גרים\u0004 \u0005[מי גורם]\u0006 \u0003לה\u0004 שתיעשה לעבודה זרה? \u0003גמר מלאכה, ואימת הויא\u0004 \u0005[ואימתי הוא]\u0006 \u0003גמר\u0004 ה\u0003מלאכה? במכוש אחרון,\u0004 ואולם \u0003מכוש אחרון\u0004 שמכה \u0003לית ביה\u0004 \u0005[אין בו]\u0006 \u0003שוה פרוטה,\u0004 והשכר שהוא מקבל הריהו על כל מה שעשה קודם לכן, קודם שנאסרה.","ומעירים: \u0003אלמא קסבר\u0004 \u0005[מכאן שהוא סבור]\u0006 ש\u0003ישנה לשכירות מתחלה ועד סוף\u0004 כלומר, שזכות השכיר לשכר העבודה חלה בכל רגע ורגע של המלאכה ולא רק בגמר המלאכה, ולכן השכר שהוא מקבל נחשב כשכר עבור כל חלק וחלק שעשה במשך הזמן.","\u0003ואין עושין תכשיטין לעבודה זרה, קטלאות\u0004 (שרשרות) \u0003ונזמים וטבעות. ר' אליעזר אומר:\u0004 אם עושה זאת \u0003בשכר\u0004 — \u0003מותר.\u0004 ועוד בענייני מכירה לגוי: \u0003אין מוכרין להם\u0004 דבר \u0003במחובר לקרקע, אבל מוכר הוא משיקצץ. ר' יהודה אומר:\u0004 אינו צריך שייקצץ בפועל, אלא די לו אם \u0003מוכר הוא על מנת לקוץ.\u0004","ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שאסור למכור להם דבר המחובר לקרקע? \u0003אמר ר' יוסי בר חנינא:\u0004"],["ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"לא תחנם\"\u0004 (דברים ז, ב), וכוונתו: \u0003לא תתן להם חנייה בקרקע.\u0004 ושואלים: \u0003האי\u0004 \u0005[זה]\u0006 הכתוב \u0003\"לא תחנם\" מיבעי ליה\u0004 \u0005[צריך אותו]\u0006 לענין אחר, \u0003דהכי קאמר רחמנא\u0004 \u0005[שכך אמרה התורה]:\u0006 \u0003לא תתן להם חן\u0004 כלומר, שאסור לדבר בשבחם ולומר כמה הם יפים או טובים!","ומשיבים: \u0003אם כן,\u0004 אם לדבר זה בלבד כוונת הכתוב, \u0003לימא קרא\u0004 \u0005[שיאמר הכתוב]:\u0006 \u0003\"לא תחונם\",\u0004 שאז יהיה ברור שהוא מלשון חנינה וחן, \u0003מאי\u0004 \u0005[מה]\u0006 הדיוק בכתיבה \u0003\"לא תחנם\"\u0004 בחסר? \u0003שמע מינה תרתי\u0004 \u0005[למד מכאן שניים],\u0006 לעניין חן ולעניין חניה.","וחוזרים ושואלים: \u0003ואכתי מיבעי ליה\u0004 \u0005[ועדיין נזקק לו]\u0006 הפסוק לענין אחר, \u0003דהכי אמר רחמנא\u0004 \u0005[שכך אמרה התורה]:\u0006 \u0003לא תתן להם מתנת של חנם!\u0004 ואומרים: \u0003אם כן, לימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 בצורה ברורה: \u0003\"לא תחינם\", מאי\u0004 \u0005[מה]\u0006 הדיוק: \u0003\"לא תחנם\"? שמע מינה כולהו\u0004 \u0005[למד מכאן\u0006 את \u0005כולם],\u0006 כל הדרשות.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 כדרשות הללו: \u0003\"לא תחנם\"\u0004 — \u0003לא תתן להם חנייה בקרקע, דבר אחר: \"לא תחנם\"\u0004 — \u0003לא תתן להם חן, דבר אחר: \"לא תחנם\"\u0004 — \u0003לא תתן להם מתנת חנם. ו\u0004מעירים: ו","\u0003מתנת חנם גופה\u0004 \u0005[עצמה]\u0006 \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"לא תאכלו כל נבלה לגר אשר בשעריך תתננה ואכלה או מכר לנכרי\"\u0004 (דברים יד, כ), \u0003אין לי אלא לגר בנתינה ולגוי במכירה, לגר במכירה מנין? תלמוד לומר: \"תתננה\u0004 ואכלה \u0003או מכר\",\u0004","\u0003לגוי בנתינה מנין? תלמוד לומר: \"תתננה ואכלה או מכר לנכרי\", נמצא אתה אומר: אחד גר ואחד גוי בין בנתינה בין במכירה,\u0004 אלו דברי ר' מאיר. ר' יהודה אומר: דברים ככתבן, לגר — \u0003בנתינה, ולגוי\u0004 — \u0003במכירה\u0004 אבל לא בנתינה, שלדעתו אין נותנים להם מתנת חינם.","ומעירים: \u0003שפיר קאמר\u0004 \u0005[יפה אמר]\u0006 \u0003ר' מאיר,\u0004 שהרי מן הכתוב משמע ששני הדברים הם ראויים! \u0003ור' יהודה אמר לך\u0004 \u0005[היה אומר לך]\u0006 בתשובה לכך: \u0003אי סלקא דעתך כדקאמר\u0004 \u0005[אם עולה על דעתך כמו שאמר]\u0006 \u0003ר' מאיר, לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]:\u0006 \u0003\"תתננה ואכלה ומכר\"\u0004 בו' החיבור, \u0003\"או\u0004 מכור\" שנאמר שם \u0003למה לי? שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003לדברים ככתבן הוא דאתא\u0004 \u0005[שבא]\u0006 לחלק ביניהם.","ומן הצד השני, \u0003ור' מאיר,\u0004 מה הוא משיב לכך? \u0003ההוא\u0004 \u0005[אותו]\u0006 \"או\" בא להבהיר שבכל זאת יש חילוק בין הדברים, לומר שיש \u0003לאקדומי\u0004 \u0005[להקדים]\u0006 \u0003נתינה\u0004 במתנה ל\u0003גר ל\u0004פני \u0003מכירה\u0004 ל\u0003גוי. ור' יהודה\u0004 סבור: \u0003כיון\u0004 ש\u0003גר אתה מצווה להחיותו,\u0004 שנאמר \"וחי עמך\" (ויקרא כה, לה), \u0003וגוי אי\u0004 \u0005[אין]\u0006 \u0003אתה מצווה להחיותו,\u0004 אם כן \u0003להקדים\u0004 גר לגוי \u0003לא צריך קרא\u0004 \u0005[פסוק],\u0006 שהדבר ידוע לנו ממקור אחר.","שנינו בברייתא שהובאה קודם, \u0003דבר אחר: \"לא תחנם\"\u0004 — \u0003לא תתן להם חן.\u0004 ומעירים: \u0003מסייע ליה\u0004 \u0005[לו]\u0006 הדבר \u0003לרב,\u0004 ש\u0003אמר רב: אסור לאדם שיאמר \"כמה נאה גויה זו\".\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: \u0003מעשה ברבן שמעון בן גמליאל שהיה על גבי מעלה\u0004 (מקום מוגבה) \u0003בהר הבית, וראה גויה אחת נאה ביותר, אמר: \"מה רבו מעשיך ה'\"\u0004 (תהלים קד, כד)! \u0003ואף ר' עקיבא ראה\u0004 את \u0003אשת טורנוסרופוס הרשע, רק\u0004 (ירק) \u0003שחק ובכה,\u0004 ומסבירים: \u0003רק\u0004 — משום \u0003שהיתה באה\u0004 (נוצרה) \u0003מטיפה סרוחה, שחק\u0004 — משום שידע ש\u0003עתידה\u0004 היא \u0003דמגיירא ונסיב לה\u0004 \u0005[להתגייר ו\u0006הוא \u0005ישא אותה]\u0006 לאשה, \u0003בכה\u0004 — \u0003דהאי שופרא בלי עפרא\u0004 \u0005[שיופי זה\u0006 סופו ש\u0005יבלה בעפר]!\u0006","\u0003ורב,\u0004 כיצד מסביר הוא את מעשהו של רבן שמעון בן גמליאל? ומשיבים: \u0003אודויי הוא דקא מודה\u0004 \u0005[הודאה הוא שמודה]\u0006 לה' על מעשיו, ואינו משבח את הגוי לעצמו, וכפי ש\u0003אומר מר\u0004 \u0005[החכם]:\u0006 \u0003הרואה בריות טובות\u0004 כלומר, יצורים יפים ונאים, \u0003אומר: \"ברוך שככה ברא בעולמו\".\u0004","ושואלים: \u0003ולאסתכולי מי שרי\u0004 \u0005[ולהסתכל\u0006 באישה \u0005האם מותר]?\u0006 \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 הרי פירשו את הכתוב \u0003\"ונשמרת מכל דבר רע\"\u0004 (דברים כג, י) — \u0003שלא יסתכל אדם באשה נאה ואפילו\u0004 היא \u0003פנויה,\u0004 ולא יסתכל \u0003באשת איש ואפילו\u0004 היא \u0003מכוערת,\u0004"],["\u0003ולא בבגדי צבע [של] אשה, ולא בחמור ולא בחמורה, ולא בחזיר ולא בחזירה, ולא בעופות, בזמן שנזקקין\u0004 \u0003זה לזה\u0004 (מזדווגים), \u0003ואפילו\u0004 היה \u0003מלא עינים כמלאך המות\u0004 ורואה מכל צד — לא יסתכל.","\u0003אמרו עליו על מלאך המות, שכולו מלא עינים, בשעת פטירתו של חולה עומד\u0004 מלאך המות \u0003מעל מראשותיו וחרבו שלופה בידו, וטיפה של מרה\u0004 (ארס) \u0003תלויה בו\u0004 בקצה החרב, \u0003כיון שחולה רואה אותו\u0004 הריהו \u0003מזדעזע\u0004 מפניו \u0003ו\u0004מתוך כך \u0003פותח פיו, וזורקה\u0004 מלאך המות לאותה טיפה \u0003לתוך פיו, ממנה\u0004 מטיפה זו \u0003מת\u0004 החולה, \u0003ממנה מסריח, ממנה פניו מוריקות!\u0004","ומשיבים: רבן גמליאל לא הסתכל באישה בכוונה, אלא \u0003קרן זוית הואי\u0004 \u0005[היתה]\u0006 שם, שהאשה באה לקראתו מעבר לקרן הזוית, וראה אותה.","ועל מה שנאמר בברייתא: \u0003ולא\u0004 יסתכל \u0003בבגדי צבע [של] אשה, אמר רב יהודה אמר שמואל: אפילו\u0004 כשהבגדים \u0003שטוחין על גבי כותל,\u0004 ולא רק כשהיא לבושה בהם. ומן הצד האחר \u0003אמר רב פפא: ו\u0004מה שנאסר הוא דווקא \u0003במכיר בעליהן\u0004 את האשה הלובשת בגדים אלה, ולא בבגדים סתם. \u0003אמר רבא: דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 הדבר בלשון הברייתא, \u0003דקתני\u0004 \u0005[שהוא שונה]:\u0006 \u0003\"ולא בבגדי צבע [של] אשה\", ולא קתני\u0004 \u0005[ואינו שונה]\u0006 סתם \u0003\"ולא בבגדי צבעונין\",\u0004 משמע שמדובר בבגדי אישה הידועה לו. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך הוא.","ועוד בעניין ברייתא זו, \u0003אמר רב חסדא: הני מילי\u0004 \u0005[דברים אלה],\u0006 שאסור להסתכל בבגדי צבע של אשה, אמורים \u0003בעתיקי\u0004 \u0005[ב\u0006בגדים \u0005ישנים]\u0006 שכבר לבשה אותם האישה, \u0003אבל בחדתי, לית לן בה\u0004 \u0005[ב\u0006בגדים \u0005חדשים, אין לנו\u0006 כלום \u0005בכך],\u0006 \u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כן],\u0006 \u0003אנן מנא לאשפורי היכי יהבינן\u0004 \u0005[אנו בגד לכבס\u0006 לפני שימוש \u0005איך אנו נותנים]?\u0006 \u0003הא קא\u0004 \u0005[הרי הוא]\u0006 הכובס \u0003מסתכל\u0004 בהם!","ודוחים: \u0003ולטעמיך\u0004 \u0005[ולשיטתך]\u0006 שאתה מוכיח מכובס לכל אדם, \u0003הא\u0004 \u0005[זה]\u0006 ש\u0003אמר רב יהודה:\u0004 בעלי חיים שהם \u0003מין במינו\u0004 ואין בהם משום הרבעת כלאים — \u0003מותר\u0004 לעסוק בהרבעה שלהם ו\u0003להכניס\u0004 את איבר הזכר בנקבה \u0003כ\u0004מכניס \u0003מכחול בשפופרת\u0004 צבע — יש לשאול על כך: \u0003הא קא\u0004 \u0005[הרי הוא]\u0006 \u0003מסתכל,\u0004 ואמרנו שאסור להסתכל בהם בשעת תשמישם! \u0003אלא\u0004 יש לומר כי \u0003בעבידתיה טריד\u0004 \u0005[בעבודתו טרוד],\u0006 ולכן אינו מהרהר, \u0003הכי נמי בעבידתיה טריד\u0004 \u0005[כך גם כן\u0006 הכובס \u0005בעבודתו\u0006 הוא \u0005טרוד],\u0006 ואין להוכיח מכאן לכל אדם.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 באותה ברייתא: מטיפה זו של מרה שבקצה חרבו של מלאך המות, \u0003ממנה\u0004 הוא \u0003מת.\u0004 ושואלים: \u0003נימא, פליגא דאבוה\u0004 \u0005[האם נאמר,\u0006 ש\u0005חלוק\u0006 הדבר \u0005על אביו]\u0006 של \u0003שמואל,\u0004 ש\u0003אמר אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל, אמר לי מלאך המות: אי לא דחיישנא ליקרא דברייתא\u0004 \u0005[אם לא שהייתי חושש לכבוד הבריות],\u0006 \u0003הוה פרענא\u0004 \u0005[הייתי פורע,\u0006 מגלה\u0005]\u0006 את \u0003בית השחיטה כ\u0004דרך שעושים ל\u0003בהמה\u0004 הנשחטת; משמע שמלאך המות שוחט בחרבו את אלה שהוא הורג, ואין הוא ממית בהטלת טיפת המרה! ודוחים: \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003ההיא\u0004 \u0005[אותה]\u0006 \u0003טיפה\u0004 של מרה \u0003מחתכה להו\u0004 \u0005[מחתכת אותם]\u0006 את ה\u0003סימנין\u0004 את הקנה והושט שבצואר האדם, כעין שחיטה.","ועוד מעירים כי מה ששנינו בברייתא: \u0003ממנה מסריח, מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לר' חנינא בר כהנא,\u0004 ש\u0003אמר ר' חנינא בר כהנא, אמרי בי\u0004 \u0005[אומרים בבית\u0006 מדרשו של\u0005]\u0006 \u0003רב: הרוצה שלא יסריח מתו, יהפכנו על פניו\u0004 תחילה, משום שהטיפה המרה נכנסת לפיו, ומשם הוא מסריח.","ומביאים ברייתא נוספת על הפסוק שדרשנו. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 הכתוב \u0003\"ונשמרת מכל דבר רע\"\u0004 (דברים כב, י), שהמשכו: \"כי יהיה בך איש אשר לא יהיה טהור מקרה לילה\", בא ללמדנו \u0003שלא יהרהר אדם ביום ויבוא לידי טומאה בלילה.\u0004","\u0003מכאן\u0004 שהזהירה התורה בענין זה. \u0003אמר ר' פנחס בן יאיר: תורה מביאה לידי זהירות\u0004 במצוות, \u0003זהירות מביאה לידי זריזות\u0004 בהן, \u0003זריזות מביאה לידי נקיות\u0004 הנפש, \u0003נקיות מביאה לידי פרישות\u0004 התרחקות מכל רע, \u0003פרישות מביאה לידי טהרה\u0004 והסרת כל תאוה, \u0003טהרה מביאה לידי חסידות, חסידות מביאה לידי ענוה, ענוה מביאה לידי יראת חטא, יראת חטא מביאה לידי קדושה, קדושה מביאה לידי רוח הקודש, רוח הקודש מביאה לידי תחיית המתים, וחסידות גדולה מכולן, שנאמר: \"אז דברת בחזון לחסידיך\"\u0004 (תהלים פט, כ).","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוק\u0006 הדבר\u0005]\u0006 על שיטת \u0003ר' יהושע בן לוי,\u0004 ש\u0003אמר ר' יהושע בן לוי: ענוה\u0004 היא מעלה \u0003גדולה מכולן, שנאמר: \"רוח ה' אלהים עלי יען משח ה' אתי לבשר ענוים\"\u0004 (ישעיהו סא, א), \u0003\"חסידים\" לא נאמר אלא \"ענוים\", הא\u0004 \u0005[הרי]\u0006 \u0003למדת\u0004 מכאן \u0003שענוה גדולה מכולן.\u0004","שנינו במשנה ש\u0003אין מוכרין להן\u0004 דבר המחובר לקרקע. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מוכרין להן אילן על מנת לקוץ וקוצץ\u0004 אותו, \u0003דברי ר' יהודה. ר' מאיר אומר: אין מוכרין להן אלא קצוצה.\u0004 וכן מוכר להם \u0003שחת על מנת לגזוז וגוזז, דברי ר' יהודה. ר' מאיר אומר: אין מוכרין להן אלא גזוזה.\u0004 וכן מוכרים להם \u0003קמה על מנת לקצור וקוצר, דברי ר' יהודה. ר' מאיר אומר: אין מוכרין אלא קצורה.\u0004","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שייאמרו כל האופנים הללו, אף שלכאורה עניינם אחד, \u0003דאי אשמעינן\u0004 \u0005[שאילו היה משמיע לנו]\u0006 את מחלוקתם ב\u0003אילן\u0004 בלבד, היינו אומרים: דווקא \u0003בהא קאמר\u0004 \u0005[בזו אמר]\u0006 \u0003ר' מאיר\u0004 שאין מוכרים אלא קצוץ, כי יש לחשוש ש\u0003כיון דלא פסיד, משהי ליה\u0004 \u0005[שאינו נפסד\u0006 אם ישאר במקומו, \u0005משהה אותו]\u0006 הגוי מחובר לקרקע, \u0003אבל האי דכי משהי לה, פסיד\u0004 \u0005[זה,\u0006 הקמה, \u0005שאם ישהה אותה, יפסיד]\u0006 — \u0003אימא מודי ליה\u0004 \u0005[אמור\u0006 ש\u0005מודה לו]\u0006 \u0003לר' יהודה,\u0004 שיכול למכור בעודנה מחוברת","על מנת לקוצרה, משום שוודאי יקצור אותה. ומן הצד השני \u0003ואי אשמעינן בהני תרתי\u0004 \u0005[ואם היה משמיע לנו בשני אלה],\u0006 הייתי אומר כי דווקא בהם מתיר ר' יהודה למכור על מנת לקצוץ ולקצור, ואין לחשוש שמא ישהה אותם הגוי, \u0003משום\u0004 ש\u0003לא ידיע שבחייהו\u0004 \u0005[ידוע שבחם]\u0006 אם ישארו יותר זמן בקרקע, \u0003אבל\u0004 ב\u0003שחת דידיע שבחייהו\u0004 \u0005[שידוע השבח שלהם]\u0006 — \u0003אימא מודי ליה\u0004 \u0005[אמור\u0006 ש\u0005מודה לו]\u0006 ר' יהודה \u0003לר' מאיר\u0004 שיש לחשוש שמא ישהה הקונה את הגזיזה.","ולהיפך, \u0003ואי אשמעינן בהא\u0004 \u0005[ואם היה משמיע לנו\u0006 את מחלוקתם רק \u0005בזו,\u0006 בשחת\u0005],\u0006 היינו אומרים: \u0003בהא קאמר\u0004 \u0005[בזו\u0006 דווקא \u0005אמר]\u0006 \u0003ר' מאיר\u0004 שצריך לגזוז קודם המכירה, \u0003אבל בהנך אימא מודי ליה\u0004 \u0005[באלה\u0006 שמא \u0005מודה לו]\u0006 \u0003לר' יהודה,\u0004 משום שאין שבחם ידוע, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו כולם.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמים\u0005]:\u0006 \u0003בהמה\u0004 גסה, שאסור למוכרה שמא יעבוד בה (ראה לעיל עבודה זרה יד,ב), אם מכר לו \u0003על מנת לשחוט, מהו?\u0004","ונברר: \u0003התם טעמא מאי שרי\u0004 \u0005[שם,\u0006 במשנתנו, \u0005מה טעם התיר]\u0006 \u0003ר' יהודה\u0004 למכור אילן על מנת לקצוץ? משום \u0003דלאו ברשותיה קיימי ולא מצי משהי להו\u0004 \u0005[שלא ברשותו\u0006 של הגוי הם \u0005עומדים, ואינו יכול להשהות אותם],\u0006 והיהודי בעל הקרקע דוחק בו שיחתוך, \u0003אבל בהמה, כיון דברשותיה דגוי קיימא\u0004 \u0005[שברשותו של הגוי\u0006 היא \u0005עומדת]\u0006 לאחר מכירתה, האם יש לחשוש שמא \u0003משהי לה\u0004 \u0005[משהה אותה],\u0006 \u0003או דלמא לא שנא\u0004 \u0005[שמא אינו שונה]?\u0006","ומציעים, \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 תשובה לדבר, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 מותר לו למכור לו \u0003בהמה על מנת לשחוט ושוחט, דברי ר' יהודה. ר' מאיר אומר: אין מוכרין לו אלא שחוטה.\u0004 משמע שאף בזה נחלקו.","\u0003אין משכירין להם\u0004 לגוים \u0003בתים בארץ ישראל, ואין צריך לומר\u0004 שאין משכירין להם \u0003שדות,\u0004 כאשר יבואר בגמרא. \u0003ובסוריא\u0004"],["\u0003משכירין להם בתים אבל לא שדות, ובחוצה לארץ מוכרין להם בתים ומשכירין שדות, דברי ר' מאיר. ר' יוסי אומר: בארץ ישראל משכירין להם בתים אבל לא שדות, ובסוריא מוכרין בתים ומשכירין שדות, ובחוצה לארץ מוכרין אלו ואלו.\u0004","ומוסיפים: \u0003אף במקום שאמרו\u0004 שמותר \u0003להשכיר, לא לבית דירה אמרו, מפני שהוא\u0004 (הגוי) \u0003מכניס לתוכו עבודה זרה,\u0004 והדבר אסור, \u0003שנאמר: \"לא תביא תועבה אל ביתך\"\u0004 (דברים ז, כו), והרי ביתו של ישראל הוא. ועוד אמרו בענין דומה, \u0003ובכל מקום לא ישכיר לו את המרחץ, מפני שהוא נקרא על שמו\u0004 של המשכיר, והרואים סבורים שהוא עצמו משתמש בו בשבת.","ומבררים את משנתנו: \u0003מאי\u0004 \u0005[מה]\u0006 טעם נקטה המשנה בלשון \u0003\"אין צריך לומר שדות\"?\u0004 מדוע דין שדות ברור יותר מדין בתים? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דאית\u0004 \u0005[שיש]\u0006 \u0003בה\u0004 בשדה רגיל \u0003תרתי\u0004 \u0005[שני\u0006 דברים\u0005]:\u0006 \u0003חדא\u0004 \u0005[אחת],\u0006 שהוא נותן להם \u0003חניית קרקע; וחדא, דקא מפקע לה\u0004 \u0005[ואחת, שהוא מפקיע אותה]\u0006 את הקרקע \u0003ממעשר;\u0004","\u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003בתים נמי איכא תרתי\u0004 \u0005[גם כן יש שניים]:\u0006 \u0003חדא\u0004 \u0005[אחת],\u0006 \u0003חניית קרקע; וחדא, דקא מפקע לה\u0004 \u0005[ואחת, שהוא מפקיע אותה]\u0006 \u0003ממזוזה! אמר רב משרשיא: מזוזה חובת הדר\u0004 בבית \u0003הוא,\u0004 ואינה חובת הבית לעצמו, ולכן בבית שאין ישראל דר בו ממילא אין שייכת מצות מזוזה, ואין השכרת הבית לגוי מפקיעתו ממצות מזוזה.","עוד שנינו: \u0003בסוריא משכירין בתים\u0004 וכו', ושואלים: \u0003מאי שנא\u0004 \u0005[מה שונה]\u0006 \u0003מכירה\u0004 ש\u0003לא\u0004 ימכור בתים שם? גזירה \u0003משום מכירה\u0004 של בתים ב\u0003ארץ ישראל; אי הכי\u0004 \u0005[אם כך],\u0006 \u0003משכירות נמי\u0004 \u0005[גם כן]\u0006 \u0003נגזור,\u0004 שלא ישכירו להם בתים בסוריא, מחשש השכרת בתים בארץ ישראל! ומשיבים: השכרת בתים בארץ ישראל \u0003היא גופה\u0004 \u0005[עצמה]\u0006 אינה אלא \u0003גזרה\u0004 שמא יבוא למכור, \u0003ואנן ניקום\u0004 \u0005[ואנו נעמוד]\u0006 \u0003וניגזור גזרה לגזרה,\u0004 שיהא כן גם בסוריא?","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003שכירות שדה\u0004 ש\u0003בסוריא,\u0004 שגם היא \u0003גזרה לגזרה היא,\u0004 שהרי שכירות שדה גם בארץ ישראל היא רק גזירה, ונמצא שיש פה גזירה לגזירה, \u0003ו\u0004בכל זאת \u0003קא גזרינן\u0004 \u0005[אנו גוזרים]!\u0006 ומשיבים: לדעת ר' מאיר יש להבין אחרת את עצם איסור מכירת בתים ושדות בסוריא, \u0003התם\u0004 \u0005[שם]\u0006 בסוריא \u0003לאו\u0004 \u0005[לא]\u0006 \u0003גזרה הוא\u0004 משום ארץ ישראל, אלא איסור לעצמו, \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 ר' מאיר: \u0003כיבוש יחיד שמיה\u0004 \u0005[שמו\u0006 נקרא, נחשב\u0005]\u0006 \u0003כיבוש,\u0004 שכאשר כבש דוד המלך את סוריה — על ידי כיבושו זה נתקדשה בקדושת ארץ ישראל, ולכן","\u0003שדה דאית ביה תרתי\u0004 \u0005[שיש בו שני\u0006 נימוקים\u0005]\u0006 לאיסור, משום \"לא תחנם\" ומשום הפקעת מעשר — \u0003גזרו ביה רבנן\u0004 \u0005[בו חכמים]\u0006 גם שכירות, כמו ארץ ישראל. \u0003בתים דלית בהו תרתי\u0004 \u0005[שאין בהם שני\u0006 נימוקים\u0005]\u0006 — \u0003לא גזרו בהו רבנן\u0004 \u0005[בהם חכמים].\u0006","ועוד שנינו כי לדעת ר' מאיר \u0003בחוצה לארץ\u0004 מוכרים להם בתים, ומשכירים להם שדות אבל לא מוכרים. ומסבירים: \u0003שדה דאית ביה תרתי\u0004 \u0005[שיש בו שני\u0006 טעמים לאיסור\u0005]\u0006 בארץ ישראל — \u0003גזרו בהו רבנן\u0004 \u0005[בהם חכמים]\u0006 שלא למכור אף בחוצה לארץ, \u0003בתים דלית בהו תרתי\u0004 \u0005[שאין בהם שני\u0006 נימוקים\u0005]\u0006 — \u0003לא גזרו בהו רבנן\u0004 \u0005[בהם חכמים]\u0006 שלא למכור.","ועוד שנינו במשנה, \u0003ר' יוסי אומר: בארץ ישראל משכירין להם בתים\u0004 אבל לא שדות. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 \u0003שדות דאית בהו תרתי\u0004 \u0005[שיש בהם שני\u0006 נימוקים\u0005]\u0006 — \u0003גזרו בהו רבנן\u0004 \u0005[בהם חכמים]\u0006 שלא להשכיר, \u0003בתים דלית בהו תרתי\u0004 \u0005[שאין בהם שני\u0006 נימוקים\u0005]\u0006 — \u0003לא גזרו בהו רבנן\u0004 \u0005[בהם חכמים].\u0006","ועוד שנינו כי לשיטתו של ר' יוסי, \u0003ובסוריא מוכרין\u0004 בתים ומשכירים שדות, אבל לא מוכרים. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003כיבוש יחיד לא שמיה\u0004 \u0005[אין שמו]\u0006 \u0003כיבוש,\u0004 ולכן אין בה איסור \"לא תחנם\" ולא הפקעה ממעשר, \u0003ושדה דאית בה תרתי\u0004 \u0005[שיש בו שנים\u0006 טעמים לאיסור\u0005]\u0006 בארץ ישראל — \u0003גזרו בה רבנן\u0004 \u0005[חכמים]\u0006 שלא למכור אף בסוריא, \u0003בתים דלית בהו תרתי\u0004 \u0005[שאין בהם שני\u0006 נימוקים\u0005]\u0006 — \u0003לא גזרו בהו רבנן\u0004 \u0005[בהם חכמים].\u0006","\u0003\"ובחוצה לארץ מוכרין\u0004 בתים ושדות\". \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 \u0003כיון דמרחק\u0004 \u0005[שמרוחק]\u0006 המקום מארץ ישראל, ששם עיקר האיסור — \u0003לא גזרינן\u0004 \u0005[אין אנו גוזרים]\u0006 כלל כמו שגזרו בסוריא.","ובמסקנת ההלכה בעניין זה, \u0003אמר רב יהודה אמר שמואל: הלכה כר' יוסי\u0004 שמותר למכור בתים לגוי בחוצה לארץ. \u0003אמר רב יוסף: ובלבד שלא יעשנה שכונה\u0004 של גוים. \u0003וכמה\u0004 היא \u0003שכונה? תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003אין שכונה פחותה משלשה בני אדם.\u0004","ושואלים: \u0003ולחוש\u0004 \u0005[ונחשוש]\u0006 \u0003דלמא אזיל האי ישראל ומזבין לחד גוי\u0004 \u0005[שמא הולך ישראל זה ומוכר לגוי אחד],\u0006 \u0003ואזיל היאך ומזבין לה לתרי\u0004 \u0005[והולך האחר ומוכר לשניים]\u0006 ונמצא שיהיו שם שלושה גוים, ונעשתה שכונה! \u0003אמר אביי:\u0004 על \u0003\"לפני\u0004 עור לא תתן מכשול\" (ויקרא יט, יד) \u0003מפקדינן\u0004 \u0005[אנו מצווים],\u0006 על \u0003\"לפני\"\u0004 של \u0003\"לפני\" לא מפקדינן\u0004 \u0005[אין אנו מצווים]\u0006 כלומר, אנו מצווים רק כאשר המוכר גורם מכשול באופן ישיר, אבל אם זה דבר שנעשה בעקיפין אין בו איסור.","שנינו במשנה ש\u0003אף במקום שאמרו\u0004 והתירו \u0003להשכיר\u0004 לגוי, לא לבית דירה אמרו. ומעירים: \u0003מכלל דאיכא דוכתא דלא מוגרי\u0004 \u0005[מכאן שיש מקום שאין משכירים]\u0006 דירות כלל."],["\u0003וסתמא\u0004 \u0005[\u0006נמצא ש\u0005סתמה\u0006 של המשנה\u0005]\u0006 \u0003כ\u0004דעת \u0003ר' מאיר\u0004 היא, שאמר שבארץ ישראל אין משכירים. \u0003דאי\u0004 \u0005[שאם]\u0006 תאמר שהיא כדעת \u0003ר' יוסי,\u0004 הלוא \u0003בכל דוכתא מוגרי\u0004 \u0005[מקום משכירים],\u0006 אפילו בארץ ישראל.","שנינו במשנה, \u0003ובכל מקום לא ישכור\u0004 (ישכיר) את המרחץ לגוי, מפני שהוא נקרא על שמו. ועוד \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבן שמעון בן גמליאל אומר: לא ישכור אדם מרחצו לגוי, מפני שנקרא\u0004 המרחץ \u0003על שמו\u0004 של היהודי, \u0003וגוי זה עושה בו מלאכה בשבתות ובימים טובים.\u0004","ומדייקים: דווקא לגוי, \u0003אבל לכותי\u0004 (שומרוני), \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין? \u0003שרי\u0004 \u0005[מותר],\u0006 ויש לשאול: הלא \u0003כותי אימר עביד ביה\u0004 \u0005[אמור\u0006 ש\u0005יעשה בה]\u0006 \u0003מלאכה בחולו של מועד!\u0004 ודוחים: \u0003בחולו של מועד אנן נמי עבדינן\u0004 \u0005[אנו גם כן עושים]\u0006 ומחממים מרחץ.","ועוד מדייקים: לא ישכיר מרחץ לגוי, \u0003אבל\u0004 להשכיר \u0003שדהו לגוי מאי\u0004 \u0005[מה]\u0006 הדין? \u0003שרי\u0004 \u0005[מותר],\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 אין זה קרוי על שמו של היהודי המשכיר, משום שכולם יודעים כי \u0003אריסא, אריסותיה קעביד\u0004 \u0005[האריס,\u0006 את \u0005אריסותו עושה],\u0006 ועובד עבור עצמו, ואחר כך ישלם ליהודי חלקו שלו. ויש לשאול: \u0003מרחץ נמי אמרי\u0004 \u0005[גם כן אומרים]:\u0006 \u0003אריסא אריסותיה קעביד\u0004 \u0005[האריס, אריסותו הוא עושה],\u0006 ומדוע ייאסר? ומשיבים: \u0003אריסא דמרחץ לא עבדי אנשי\u0004 \u0005[אריס של מרחץ אין אנשים עושים]\u0006 כרגיל, ולכן הרואים מניחים שהגוי הוא רק שכיר העובד עבור היהודי.","ועוד בענין זה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר: לא ישכיר אדם שדהו לכותי, מפני שנקראת על שמו, וכותי זה עושה בו מלאכה בחולו של מועד.\u0004 ומדייקים: דווקא לכותי לא ישכיר \u0003אבל גוי מאי\u0004 \u0005[מה]\u0006 יהא דינו? \u0003שרי\u0004 \u0005[מותר]\u0006 להשכיר, \u0003דאמרי\u0004 \u0005[שאומרים]:\u0006 \u0003אריסא, אריסותיה עביד\u0004 \u0005[האריס,\u0006 את \u0005אריסותו עושה]\u0006 ואינו עושה עבור היהודי. ויש לשאול: \u0003אי הכי\u0004 \u0005[אם כן],\u0006 \u0003כותי נמי אמרי\u0004 \u0005[גם כן אומרים]:\u0006 \u0003אריסא, אריסותיה עביד\u0004 \u0005[האריס,\u0006 את \u0005אריסותו עושה]!\u0006"],["ומשיבים: הטעם הזה של \u0003אריסותא\u0004 \u0005[אריסות],\u0006 שהאריס עושה את אריסותו, ואינו עושה עבור ישראל, \u0003לר' שמעון בן אלעזר לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 נימוק זה. ושואלים: \u0003אלא\u0004 על דרך זו, \u0003גוי מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003מותר\u0004 להשכיר לו? ומשיבים: \u0003דאמרינן ליה\u0004 \u0005[שאנו אומרים לו]\u0006 שביום זה אסור לעשות מלאכה \u0003וציית\u0004 \u0005[ו\u0006הוא \u0005מציית],\u0006 ואינו עושה מלאכה. ושואלים: \u0003כותי נמי אמרינן ליה וציית\u0004 \u0005[גם כן אומרים אנו לו ו\u0006הוא \u0005מציית]!\u0006 ומשיבים: \u0003כותי לא ציית\u0004 \u0005[אינו מציית],\u0006 משום \u0003דאמר\u0004 \u0005[ש\u0006הוא \u0005אומר]:\u0006 \u0003אנא גמירנא טפי מינך\u0004 \u0005[אני מלומד יותר ממך]\u0006 בדין, ואני יודע שהדבר מותר. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מסביר, \u0003מאי איריא\u0004 \u0005[מה שייך]\u0006 מדוע נתן ר' שמעון בן אלעזר את הטעם שאסור להשכיר את שדהו לכותי \u0003מפני שנקראת על שמו? תיפוק ליה\u0004 \u0005[תצא לו]\u0006 הלכה זו מטעם אחר \u0003משום \"לפני עור לא תתן מכשל\"\u0004 (ויקרא יט, יד), שהרי אף הכותי מצווה (כישראל) שלא לעשות מלאכה בחול המועד, והוא עובר על כך! ומשיבים: אכן, סיבה \u0003חדא\u0004 \u0005[אחת]\u0006 \u0003ועוד\u0004 סיבה \u0003קאמר\u0004 \u0005[אמר]:\u0006 \u0003חדא\u0004 \u0005[אחת]\u0006 — \u0003משום \"לפני עור\", ועוד\u0004 — \u0003מפני שנקראת על שמו\u0004 של היהודי.","","מסופר, \u0003הנהו מוריקאי\u0004 \u0005[מגדלי כרכום]\u0006 שהיו שותפים בשדה באופן שה\u0003גוי נקיט\u0004 \u0005[היה מחזיק]\u0006 בשדה ועובד בה \u0003בשבתא\u0004 \u0005[בשבת]\u0006 \u0003וישראל בחד בשבתא\u0004 \u0005[באחד בשבת],\u0006 \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רבא\u0004 לשאול האם מותר ליהודי להתחלק בשכר בשווה, \u0003שרא להו\u0004 \u0005[התיר להם].\u0006","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבינא לרבא\u0004 ממה ששנינו: \u0003ישראל וגוי שקיבלו שדה בשותפות\u0004 לעבוד בה וליטול מתבואתה, \u0003לא יאמר ישראל לגוי: \"טול\u0004 אתה את \u0003חלקך\u0004 בעבודה \u0003בשבת, ואני\u0004 אטול את חלקי \u0003בחול\",\u0004 שנמצא הגוי עושה גם את חלקו של היהודי בשבת, \u0003ואם התנו מתחלה\u0004 כשנכנסו לשותפות, שזה יטול חלקו בשבת וזה באחד מימי החול — \u0003מותר,\u0004 שאז כל אחד מהם עובד בשלו. \u0003ואם\u0004 עשו בסתם, הגוי בשבת והיהודי ביום אחר, ולבסוף \u0003באו לחשבון\u0004 כמה עבד היהודי בחול — \u0003אסור,\u0004 משום שהיהודי גילה בכך את דעתו שהגוי היה שלוחו בשבת. \u0003איכסיף\u0004 \u0005[התבייש]\u0006 רבא שנמצא שפסק שלא כדין. \u0003לסוף איגלאי מלתא דהתנו מעיקרא הוו\u0004 \u0005[לבסוף התגלה הדבר שמתחילה התנו],\u0006 וגם לפי הברייתא מותר הדבר.","","\u0003רב גביהה מבי כתיל אמר,\u0004 לא כך היה מעשה, אלא קיבלו בשותפות \u0003הנהו שתילי\u0004 \u0005[אותם שתילים]\u0006 של \u0003ערלה\u0004 לעבוד בהם ולמוכרם, \u0003הוה גוי אכיל שני דערלה\u0004 \u0005[היה הגוי אוכל\u0006 את \u0005השנים של הערלה]\u0006 \u0003וישראל\u0004 אוכל \u0003שני דהתירא\u0004 \u0005[\u0006את \u0005השנים של ההיתר],\u0006 \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רבא, שרא להו\u0004 \u0005[התיר להם].\u0006","ומקשים: \u0003והא אותביה\u0004 \u0005[והרי הקשה לו]\u0006 \u0003רבינא לרבא!\u0004 ומשיבים: לא להקשות לו בא אלא \u0003לסיועי סייעיה\u0004 \u0005[לסייע לו],\u0006 שאם היתנו שכל אחד יעבור וירויח בשנים מסוימות — מותר. ומקשים: \u0003והא אכסיף\u0004 \u0005[והרי התבייש]\u0006 רבא בדבר! ומשיבים: לא התבייש, כי \u0003לא היו דברים מעולם.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמים\u0005]:\u0006 \u0003סתמא מאי\u0004 \u0005[סתם מהו],\u0006 מה דינו? כשלא התנו מתחילה במפורש שהם מחלקים את הימים, וגם לא באו בחשבון להתחלק ברווחים בשווה, יום כנגד יום? \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ממה ששנינו בברייתא: \u0003אם התנו מתחילה\u0004 — \u0003מותר,\u0004 ונדייק מכאן: \u0003הא סתמא\u0004 \u0005[הרי בסתם]\u0006 — \u0003אסור.\u0004","ודוחים, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005הסוף]:\u0006 \u0003אם באו לחשבון\u0004 — \u0003אסור,\u0004 ונדייק מכאן: \u0003הא סתמא\u0004 \u0005[הרי סתם]\u0006 — \u0003מותר! אלא\u0004 מכיון שהדיוקים סותרים זה את זה, \u0003מהא ליכא למשמע מינה\u0004 \u0005[מזו אי אפשר לשמוע\u0006 ללמוד \u0005ממנה].\u0006","","\u0003אין מעמידין בהמה בפונדקאות של גוים, מפני שחשודין על הרביעה,\u0004 שמא הנמצאים בפונדק ירבעו את הבהמה, והדבר אסור להם, ונמצא שבהעמדת הבהמה שם הריהו נותן מכשול בפני עיוור. \u0003ולא תתייחד אשה עמהן, מפני שחשודין על העריות. ולא יתייחד אדם\u0004 מישראל \u0003עמהן, מפני שחשודין על שפיכות דמים.\u0004"],["מן המשנה עולה שגוים חשודים על רביעת בהמות. \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003לוקחין\u0004 (קונים) \u0003מהן\u0004 מן הגוים \u0003בהמה לקרבן, ואין חוששין\u0004 באותה בהמה \u0003לא משום רובע\u0004 אדם \u0003ולא משום נרבע\u0004 לאדם, \u0003ולא משום מוקצה\u0004 שייחדה לעבודה זרה, \u0003ולא משום נעבד\u0004 שעבדו אותו כעבודה זרה, שכל אלה פסולים לקרבן.","ונדון: \u0003בשלמא\u0004 \u0005[נניח]\u0006 שבהמה זו היתה \u0003מוקצה ונעבד\u0004 אין חוששים, לפי ש\u0003אם איתא דאקצייה\u0004 \u0005[אכן הקצה אותו]\u0006 לעבודה זרה \u0003ואם איתא דפלחיה\u0004 \u0005[אכן עבד אותו]\u0006 \u0003לא הוה מזבין ליה\u0004 \u0005[היה מוכר אותו],\u0006 ואם מכרו משמע שלא ייחדו ולא עבדו לעבודה זרה, \u0003אלא\u0004 לפסול \u0003רובע ונרבע לחוש\u0004 \u0005[נחשוש],\u0006 שהרי שנינו במשנתנו שאנו חוששים לכך בגוים! \u0003אמר רב תחליפא אמר רב שילא בר אבינא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב:\u0004 אין לחשוש לכך, מפני ש\u0003גוי חס על בהמתו שלא תעקר,\u0004 ורביעה זו עשויה לעקר אותה. אבל במשנתנו הרי מדובר על בהמה של ישראל.","ושואלים: \u0003התינח\u0004 \u0005[\u0006דבר \u0005זה נוח]\u0006 בבהמות \u0003נקבות\u0004 שהן נעשות עקרות על ידי רביעת אנשים, ואולם בבהמות \u0003זכרים מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 \u0003אמר רב כהנא:\u0004 אף זכרים שלהם אין הם נוהגים לרבוע, \u0003הואיל ומכחישין בבשר\u0004 על ידי רביעה זו.","ושואלים: \u0003אלא הא דתניא\u0004 \u0005[זו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003לוקחין\u0004 (קונים) \u0003בהמה מרועה שלהן, ליחוש דלמא רבעה לה\u0004 \u0005[נחשוש שמא רבע אותה],\u0006 שהרי אינה שלו ואינו חס עליה! ומשיבים: \u0003רועה שלהן מתיירא משום הפסד שכר,\u0004 שאם יתפסו אותו שעשה כן, יפסיד את שכרו.","ומקשים: \u0003אלא הא דתניא\u0004 \u0005[זו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003אין מוסרין בהמה לרועה שלהן,\u0004 משמע שאנו חוששים לכך, ומדוע? \u0003לימא\u0004 \u0005[נאמר]\u0006 ש\u0003רועה שלהן מתיירא משום הפסד שכרו!\u0004","ומשיבים: \u0003אינהו דידעי בהדדי, מרתתי\u0004 \u0005[הם, שיודעים זה בזה\u0006 במעשיהם הרעים, הם \u0005מפחדים],\u0006 ולכן לא יעשה כן הרועה בבהמתו של גוי אחר. \u0003אנן דלא ידעינן בהו, לא מרתתי\u0004 \u0005[אנו, שאין אנו יודעים בהם, אין\u0006 הם \u0005מפחדים\u0006 מפנינו\u0005].\u0006 \u0003אמר רבה, היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים בני אדם]\u0006 בפתגם מקובל: \u0003מכתבא גללא בזע\u0004 \u0005[\u0006כשם ש\u0005המכתב חותך\u0006 את \u0005השיש],\u0006 \u0003רגלא בחבריה ידע\u0004 \u0005[המרגל בחבירו\u0006 הוא \u0005יודע]\u0006 כלומר, העובר עבירה מכיר באחרים העוברים עליה.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שלוקחים מהם בהמה לקרבן משום שגוי חס על בהמתו ואינו רובע אותה, בהמות \u0003זכרים מנקבות\u0004 (נשים) \u0003לא ניזבון\u0004 \u0005[נקנה],\u0006 \u0003דחיישינן דלמא מרבעא ליה עילוה\u0004 \u0005[שאנו חוששים שמא\u0006 היא \u0005מרביעה אותו\u0006 את הזכר \u0005עליה]!\u0006 ומשיבים: \u0003כיון דמיגרי בה, מרתתא\u0004 \u0005[ש\u0006אם היא נוהגת כך \u0005מתגרה בה\u0006 הזכר ורודף אחריה, היא \u0005מפחדת]\u0006 ואינה עושה כן, שלא יתגלה קלונה ברבים.","ומקשים, \u0003אלא הא דתני\u0004 \u0005[זו ששנה]\u0006 \u0003רב יוסף: ארמלתא לא תרבי כלבא\u0004 \u0005[אלמנה לא תגדל כלב],\u0006 \u0003ולא תשרי בר בי רב באושפיזא\u0004 \u0005[ולא תשהה\u0006 בביתה \u0005תלמיד ישיבה\u0006 כאורח\u0005],\u0006 מפני שבשני אלה אנו חוששים בה לזנות; \u0003בשלמא בר בי רב צניע לה\u0004 \u0005[נניח תלמיד ישיבה צנוע לה]\u0006 והיא סומכת עליו שהוא לא יגלה את מעשיה, \u0003אלא כלבא\u0004 \u0005[כלב]\u0006 מדוע יש לחשוש? \u0003כיון דמיגרה\u0004 \u0005[שמתגרה]\u0006 \u0003בה\u0004 ורודף אחריה היא \u0003מרתתא\u0004 \u0005[מפחדת]!\u0006","ומשיבים: כלב \u0003כיון דכי שדיא ליה אומצא ומסריך אבתרה\u0004 \u0005[שכאשר\u0006 היא \u0005זורקת לו חתיכת בשר ו\u0006הוא \u0005נכרך אחריה],\u0006 \u0003מימר אמרי אינשי\u0004 \u0005[אומרים אנשים]\u0006 הרואים אותו בכך: \u0003האי דמסריך אבתרה, משום אומצא דקא מסריך\u0004 \u0005[זה ש\u0006הוא \u0005כרוך אחריה, משום הבשר\u0006 הוא \u0005כרוך]\u0006 ואינם חושדים שסיבת הדבר היא רביעה, ועל כך היא סומכת.","ומוסיפים לשאול לדרך זו: בהמות \u0003נקבות אצל נקבות\u0004 (נשים) \u0003מאי טעמא לא מייחדינן\u0004 \u0005[מה הטעם אין אנו מייחדים],\u0006 מה יש לחשוש כאן? \u0003אמר מר עוקבא בר חמא: מפני שהגוים מצויין אצל נשי חבריהן\u0004 לזנות אתן, \u0003ופעמים ש\u0004הגוי \u0003אינו מוצאה\u0004 את האישה, \u0003ומוצא\u0004 בביתה \u0003את הבהמה\u0004 הנקבה \u0003ורובעה.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003אפילו מוצאה\u0004 \u0005[מוצא]\u0006 את האישה \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003רובעה\u0004 את הבהמה, ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003חביבה עליהן\u0004 על הגוים \u0003בהמתן של ישראל יותר מנשותיהן\u0004 שלהם; וטעם הדבר כפי ש\u0003אמר\u0004 \u0003ר' יוחנן: בשעה שבא נחש על חוה\u0004 בחטא עץ הדעת \u0003הטיל בה זוהמא,\u0004 וזוהמה זו גורמת שיש לאנשים סטיות ונטיות רעות. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003ישראל נמי\u0004 \u0005[גם כן]\u0006 נחשוש לגביהם! ומשיבים: \u0003ישראל שעמדו על הר סיני\u0004 — \u0003פסקה זוהמתן\u0004 זו, \u0003גוים שלא עמדו על הר סיני\u0004 — \u0003לא פסקה זוהמתן.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמים\u0005]:\u0006 \u0003עופות מאי\u0004 \u0005[מה]\u0006 דינם? האם חוששים גם בהם לרביעה? \u0003תא שמע\u0004 \u0005[בוא ושמע],\u0006 פתרון לשאלה ש\u0003אמר רב יהודה אמר שמואל משום\u0004 (בשם) \u0003ר' חנינא: אני ראיתי גוי שלקח אווז מן השוק, רבעה,\u0004 ואחר כך \u0003חנקה, צלאה, ואכלה. ואמר ר' ירמיה מדיפתי: אני ראיתי ערבי אחד שלקח ירך\u0004 של בהמה \u0003מן השוק, וחקק\u0004 (עשה) \u0003בה\u0004 חור \u0003כדי\u0004 אפשרות של \u0003רביעה, רבעה,\u0004 ואחר כך \u0003צלאה ואכלה,\u0004 משמע שהם חשודים גם על העופות."],["ועוד ביישוב הסתירה שבין המשנה שאוסרת לייחד בהמות עם גוים, לבין הברייתא המתירה לקנות מהם לקרבן, \u0003רבינא אמר, לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זו,\u0006 משנתנו\u0005]\u0006 אוסרת \u0003לכתחלה\u0004 לייחד עימהם, ואילו \u0003הא\u0004 \u0005[זו,\u0006 הברייתא\u0005]\u0006 עוסקת ב\u0003דיעבד\u0004 שאין חוששים שאכן רבע.","\u0003ומנא תימרא\u0004 \u0005[ומנין אתה אומר]\u0006 \u0003דשאני\u0004 \u0005[ששונה]\u0006 הדין בענין זה של חשד בעריות \u0003בין לכתחלה בין\u0004 \u0003לדיעבד? דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003לא תתייחד אשה עמהם, מפני שחשודין על העריות. ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005],\u0006 ששנינו במשנה במסכת כתובות, \u0003האשה שנחבשה\u0004 (נאסרה) \u0003בידי גוים,\u0004 אם נאסרה \u0003על ידי\u0004 (בגלל) חוב של \u0003ממון\u0004 — \u0003מותרת לבעלה,\u0004 שאין חוששים שמא באו עליה. ואם נחבשה \u0003על ידי\u0004 האשמה שיש בה חיוב \u0003נפשות\u0004 (מוות) — \u0003אסורה לבעלה,\u0004 שאז היא נעשית להם כהפקר. ומדוע אומרים שאם נאסרה משום ממונות מותרת ואין חוששים לבעילה, ואילו במשנתנו חוששים לבעילה?","\u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 ש\u0003שאני לן\u0004 \u0005[שונה לנו]\u0006 \u0003בין לכתחלה\u0004 כדין משנתנו, \u0003לדיעבד\u0004 כענין שנחבשה האשה? ודוחים: \u0003ממאי\u0004 \u0005[ממה]\u0006 אתה מדייק כך? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך:\u0004 בדרך כלל \u0003אפילו דיעבד נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 נתיר, משום החשד בעריות, \u0003והכא\u0004 \u0005[וכאן]\u0006 לגבי האשה שנאסרה, \u0003היינו טעמא\u0004 \u0005[זהו הטעם],\u0006 שהותרה לבעלה — ש\u0003מתיירא\u0004 הגוי לבעול אותה \u0003משום הפסד ממונו,\u0004 שאם יבואו עליה לא ירצה הבעל לפדותה ולהחזיר את הממון.","\u0003תדע\u0004 שזהו הטעם, \u0003דקתני סיפא\u0004 \u0005[ששנה בסוף]\u0006 שאם נחבשה \u0003על ידי נפשות אסורה לבעלה,\u0004 \u0003ותו לא מידי\u0004 \u0005[ושוב אין דבר]\u0006 כלומר, אין להאריך בענין זה, שהראייה פשוטה וברורה.","\u0003ר' פדת אמר\u0004 הסבר אחר לסתירה בין משנתנו, שחוששים בה לרביעה, לברייתא, שמתירה ליקח מגוים בהמה לקרבן, \u0003לא קשיא\u0004 \u0005[קשה\u0006 הדבר\u0005]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 משנתנו היא לפי שיטת \u0003ר' אליעזר,\u0004 \u0003הא\u0004 \u0005[זו]\u0006 הברייתא שיטת \u0003רבנן\u0004 \u0005[חכמים].\u0006 ומה הן שיטות אלה? \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003פרת חטאת\u0004 (פרה אדומה), \u0003ר' אליעזר אומר: אינה נקחת\u0004 (נקנית) \u0003מן הגוים, וחכמים מתירין. מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא ב\u0006דבר \u0005זה הם חלוקים],\u0006 ש\u0003ר' אליעזר סבר\u0004 \u0005[סבור]:\u0006 \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003לרביעה, ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים]\u0006 \u0003לרביעה?\u0004","ודוחים: \u0003ממאי\u0004 \u0005[ממה]\u0006 אתה מסיק דבר זה? \u0003דלמא דכולי עלמא לא חיישינן\u0004 \u0005[שמא לדעת הכל אין אנו חוששים]\u0006 \u0003לרביעה, והכא היינו טעמא\u0004 \u0005[וכאן זהו הטעם]\u0006 של \u0003ר' אליעזר\u0004 — \u0003כ\u0004דברי \u0003רב יהודה אמר רב,\u0004 ש\u0003אמר רב יהודה אמר רב: הניח עליהן\u0004 על פרה אדומה \u0003עודה\u0004 (חבילה) \u0003של שקין\u0004 ריקים — \u0003פסלה\u0004 בעצם ההנחה, שנאמר: \"אשר לא עלה עליה עול\" (במדבר יט, ב), \u0003ובעגלה\u0004 ערופה — אינה נפסלת בהנחה אלא \u0003עד שתמשוך בה,\u0004 שנאמר: \"אשר לא משכה בעול\" (דברים כא, ג), וזהו טעם המחלוקת,","\u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' אליעזר, \u0005סבור]:\u0006 \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 שמא עשה בה הגוי מלאכה כלשהי, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים]\u0006 לכך! ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 שחוששים שהניח עליה משא, כי \u0003משום ניחא פורתא\u0004 \u0005[נוחות מעט]\u0006 שמניח עליה דבר מה, \u0003לא מפסיד טובא\u0004 \u0005[אינו\u0006 מוכן \u0005להפסיד הרבה]\u0006 את כל דמי הפרה אדומה.","ואומרים: אם כן, \u0003הכי נמי לימא\u0004 \u0005[כאן גם כן,\u0006 לענין רביעה, \u0005נאמר]:\u0006 \u0003משום הנאה פורתא\u0004 \u0005[מעט]\u0006 \u0003לא מפסיד טובא\u0004 \u0005[הרבה]!\u0006 ודוחים: \u0003התם\u0004 \u0005[שם]\u0006 לענין רביעה, \u0003יצרו תוקפו\u0004 ואינו עושה באותה שעה חשבון של הפסד ממון הכרוך בכך.","ומציעים הצעה אחרת, \u0003ודלמא\u0004 \u0005[ושמא]\u0006 נאמר כך: \u0003דכולי עלמא לא חיישינן\u0004 \u0005[לדעת הכל אין אנו חוששים]\u0006 \u0003לרביעה, והכא היינו טעמא\u0004 \u0005[וכאן זהו הטעם]\u0006 של \u0003ר' אליעזר\u0004 — \u0003כדתני\u0004 \u0005[כמו ששנה]\u0006 החכם \u0003שילא, דתני\u0004 \u0005[ששנה]\u0006 \u0003שילא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אליעזר?\u0004 שנאמר: \u0003\"דבר אל בני ישראל ויקחו אליך\u0004 פרה אדומה\" (במדבר יט, ב), לדייק מכאן: משל \u0003בני ישראל יקחו, ואין\u0004 (ולא) משל \u0003הגוים יקחו!\u0004","ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לפרש כך, \u0003דקתני סיפא\u0004 \u0005[ששנה בסופה]\u0006 של אותה ברייתא: \u0003וכן היה ר' אליעזר פוסל בכל הקרבנות כולן; ואי סלקא דעתך כדתני\u0004 \u0005[ואם עולה על דעתך\u0006 שהטעם הוא \u0005כמו ששנה]\u0006 \u0003שילא, בשלמא\u0004 \u0005[נניח]\u0006 \u0003פרה\u0004 — \u0003כתיב\u0004 \u0005[כתוב]\u0006 \u0003בה\u0004 לשון \u0003קיחה,\u0004 ואפשר ללמוד שאין לוקחים אלא מישראל, \u0003אלא כולהו\u0004 \u0005[כל]\u0006 ה\u0003קרבנות\u0004 האחרים, וכי \u0003קיחה כתיב בהו\u0004 \u0005[כתוב בהם]?\u0006 ועוד מציעים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003עד כאן לא\u0004 שמענו ש\u0003פליגי רבנן עליה\u0004 \u0005[חלוקים חכמים עליו]\u0006 על \u0003ר' אליעזר,\u0004"],["\u0003אלא בפרה\u0004 ש\u0003דמיה יקרין\u0004 שאין חוששים שירבענה, בגלל ההפסד הגדול שיבוא לו אם יגלו שעשה זאת, \u0003אבל בשאר\u0004 ה\u0003קרבנות מודו ליה\u0004 \u0005[מודים לו]\u0006 שלא לוקחים בהמות מן הגוים כדי להקריבם!","ודוחים: \u0003ואלא הא דתניא\u0004 \u0005[זו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003לוקחין מהן בהמה לקרבן,\u0004 אם כן, \u0003מני\u0004 \u0005[\u0006כדעת \u0005מי היא]?\u0006 הרי לדרך זו נמצא שהיא \u0003לא\u0004 כדעת \u0003ר' אליעזר ולא\u0004 דעת \u0003רבנן\u0004 \u0005[חכמים]!\u0006","\u0003ועוד, תניא בהדיא\u0004 \u0005[שנויה\u0006 ברייתא \u0005במפורש]:\u0006 \u0003מאי אותיבו ליה חברוהי\u0004 \u0005[מה השיבו לו חביריו]\u0006 \u0003לר' אליעזר?\u0004 ממה שנאמר: \u0003\"כל צאן קדר יקבצו לך\u0004 אילי נביות ישרתונך \u0003יעלו על רצון מזבחי\"\u0004 (ישעיהו ס, ז), הרי שבהמות של גוים עולים לשם קרבן (\"על רצון מזבחי\"), ונמצא שאין הם מחלקים בין פרה לבין שאר כל הקרבנות.","עקב דברים אלה מעירים: \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003אלא בחששא\u0004 \u0005[בחשש]\u0006 בפרה שלא ידוע אם נרבעה, \u0003אבל היכא\u0004 \u0005[במקום]\u0006 ש\u0003ודאי רבעה\u0004 הגוי — \u0003פסלה; שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003פרה קדשי מזבח היא\u0004 שדינה כקרבן לכל דבר, שבו אסור הנרבע, \u0003דאי\u0004 \u0005[שאם]\u0006 היא נחשבת כ\u0003קדשי בדק הבית, מי מיפסלא\u0004 \u0005[האם פוסלת]\u0006 \u0003בה רביעה?\u0004","ודוחים: אפשר לומר כי \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003פרה\u0004 אדומה, שאף על פי שקדשי בדק הבית היא, \u0003חטאת קרייה רחמנא\u0004 \u0005[קראה אותה התורה]\u0006 (\"חטאת היא\", במדבר יט, ט) ולכן יש בה דין קרבן חטאת לפוסלה ברביעה.","ואומרים: \u0003אלא מעתה,\u0004 לדרך זו, \u0003תיפסל\u0004 אף \u0003ביוצא דופן,\u0004 כלומר, אם לא נולדה כרגיל אלא על ידי ניתוח, שהולד יוצא מן הדופן — כמו קרבן חטאת, שאינו נלקח אלא מבהמה שנולדה כדרכה! \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הכי נמי\u0004 \u0005[כך\u0006 הוא \u0005גם כן]\u0006 ובאמת היא פסולה בכך, \u0003אלמה תניא\u0004 \u0005[מדוע שנויה\u0006 הברייתא\u0005]:\u0006 אם \u0003הקדישה\u0004 את הפרה האדומה \u0003ביוצא דופן\u0004 — \u0003פסולה, ור' שמעון מכשיר,\u0004 משמע שלא הכל סבורים שדין פרה אדומה כדין קרבן!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ש\u0003ר' שמעון\u0004 הולך בענין זה \u0003לטעמיה\u0004 \u0005[לשיטתו],\u0006 ש\u0003אמר\u0004 לענין דין אשה יולדת: \u0003יוצא דופן ולד מעליא\u0004 \u0005[מעולה]\u0006 \u0003הוא\u0004 ודינו כשאר ולדות לענין טומאה וקרבן, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן: מודה היה ר' שמעון לענין קדשים ש\u0004יוצא דופן \u0003אינו קדוש!\u0004","\u0003אלא\u0004 כך צריך לומר: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003פרה, הואיל ומום פוסל בה\u0004 — \u0003דבר ערוה\u0004 (רובע ונרבע) \u0003ועבודה זרה\u0004 (אם הם נעבדים או משמשים לעבודה זרה) \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003פוסל בה,\u0004 ומנין? \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 לגבי קרבנות פסולים: \u0003\"כי משחתם בהם מום בם\"\u0004 (ויקרא כב, כה), ולכן בהמה שיש בה צד השחתה — הרי היא פסולה לקרבן כבעלת מום; \u0003ותנא דבי\u0004 \u0005[ושנה\u0006 החכם \u0005שמבית מדרשו]\u0006 של \u0003ר' ישמעאל: כל מקום שנאמר\u0004 לשון \u0003השחתה אינו אלא דבר ערוה ועבודה זרה,\u0004","\u0003דבר ערוה\u0004 שנקרא השחתה — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי השחית כל בשר את דרכו על הארץ\"\u0004 (בראשית ו, יב), \u0003ועבודה זרה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"פן תשחתון ועשיתם לכם פסל\"\u0004 (דברים ד, טז); \u0003והא פרה נמי\u0004 \u0005[ופרה זו גם כן]\u0006 \u0003הואיל ומום פוסל בה,\u0004 גם \u0003דבר ערוה ועבודה זרה פסלי\u0004 \u0005[פוסלים]\u0006 \u0003בה.\u0004","\u0003גופא\u0004 \u0005[לגופו]\u0006 של דבר שהוזכר קודם, \u0003תני\u0004 \u0005[שנה]\u0006 החכם \u0003שילא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אליעזר\u0004 שאמר שאין לוקחים פרה מן הגוים? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"דבר אל בני ישראל ויקחו\u0004 אליך פרה אדומה\" (במדבר יט, ב), \u0003בני ישראל יקחו, ואין הגוים יקחו.\u0004 ותמהים: \u0003אלא מעתה\u0004 לפי שיטה זו, מה שנאמר בתרומה שלצורך המשכן: \u0003\"דבר אל בני ישראל ויקחו לי תרומה\"\u0004 (שמות כה, ב) \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003בני ישראל יקחו, ואין הגוים יקחו,\u0004 שאין קונים דבר למקדש מן הגוים?","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הכי נמי\u0004 \u0005[כך\u0006 הוא \u0005גם כן],\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה אמר שמואל, שאלו את ר' אליעזר: עד היכן\u0004 גבול החובה של \u0003כיבוד אב ואם? אמר להם: צאו וראו מה עשה גוי אחד לאביו באשקלון ודמא\u0004 \u0003בן נתינה שמו, פעם אחת בקשו\u0004 לקנות \u0003ממנו אבנים לאפוד\u0004"],["\u0003ב\u0004עבור \u0003ששים רבוא\u0004 (שש מאות אלף) דינרים \u0003שכר\u0004 שהיה מרויח בעסקה זו; \u0003רב כהנא מתני\u0004 \u0005[היה שונה]\u0006 במעשה זה: \u0003בשמונים רבוא\u0004 (שמונה מאות אלף) דינרים; \u0003והיו מפתחות\u0004 של אוצרותיו \u0003מונחות תחת מראשותיו של אביו, ולא\u0004 העיר אותו כי לא רצה ל\u0003צערו\u0004 בכך, אף על פי שהפסיד על ידי כך את כל הרווח!","ומשיבים: \u0003\"אבני שהם\"\u0004 שכתובות אחרי \"ויקחו אליך\", כתובות בלי ו' החיבור, לומר שכאן \u0003הפסיק הענין,\u0004 שאין להן דין של \"ויקחו אליך\", שצריך לקנות מישראל דווקא. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"ואבני מלואים\"\u0004 (שמות כה, ב) \u0003כתיב\u0004 \u0005[נאמר]\u0006 מיד לאחר מכן, \u0003דהדר ערביה\u0004 \u0005[שחזר\u0006 הכתוב ו\u0005עירב אותו]\u0006 עם הדברים הראשונים, ואם כן ייאסרו גם אבני שהם להיקנות מגוי!","\u0003ועוד\u0004 יש להקשות על עצם דברי שילא, שלדעת ר' אליעזר אין פרה נקנית מגוי: והרי \u0003קתני סיפא\u0004 \u0005[שנויה בסופה]\u0006 של אותה ברייתא: \u0003לשנה אחרת נולדה לו\u0004 לדמא בן נתינה \u0003פרה אדומה בעדרו, נכנסו חכמי ישראל אצלו\u0004 לדון עימו לגבי קנייתה, \u0003אמר להם: יודע אני בכם שאם אני מבקש מכם כל ממון שבעולם\u0004 בעבורה \u0003אתם נותנין לי, עכשיו איני מבקש מכם אלא אותו ממון שהפסדתי בשביל אבא\u0004 שלא מכרתי את האבנים לאפוד. משמע שאף פרה אדומה אפשר לקנות מגוי!","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003על ידי תגרי ישראל זבון\u0004 \u0005[קנו],\u0006 שהתגרים קנו את הבהמה מן הגוי, ואחר כך חזרו ומכרוה לציבור, ונמצא","שהפרה האדומה נקנתה מישראל. ושואלים: \u0003ו\u0004לדעת שילא, שלדברי ר' אליעזר אין קונים פרה מגוי רק בגלל גזירת הכתוב, האם \u0003ר' אליעזר לא חייש\u0004 \u0005[אינו חושש]\u0006 \u0003לרביעה?\u0004","\u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמרו לו לר' אליעזר: מעשה ולקחוה מן הגוי ודמא שמו, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003רמץ שמו, אמר להן ר' אליעזר: משם\u0004 מביאים אתם \u0003ראיה? ישראל היו משמרין אותה\u0004 את העגלה הזו \u0003משעה שנולדה,\u0004 ובוודאי לא נרבעה. וכיון שמצריך ר' אליעזר שמירה זו, משמע שהוא חושש לרביעה! ומשיבים: \u0003ר' אליעזר תרתי אית ליה\u0004 \u0005[שני\u0006 חששות \u0005יש לו]: הוא חושש משום\u0006 \u0003קיחה\u0004 מגוי, \u0003וחייש נמי\u0004 \u0005[וחושש גם כן]\u0006 \u0003לרביעה.\u0004","ודנים במה ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003ישראל היו משמרין אותה משעה שנולדה.\u0004 ושואלים: \u0003וניחוש דלמא רבעי לאמא כי הוה מעברה\u0004 \u0005[ו\u0006עדיין יש לחשוש \u0005שמא רבעו את האם כשהיתה מעוברת\u0006 בפרה זו\u0005],\u0006 ואז היא נאסרה, ש\u0003אמר רבא: וולד\u0004 פרה \u0003הנוגחת\u0004 שהרגה אדם בהיותה מעוברת — \u0003אסורה\u0004 למזבח, משום שאנו אומרים ש\u0003היא וולדה נגחו, ו\u0004כן \u0003וולד הנרבעת\u0004 — \u0003אסורה, היא וולדה נרבעו!\u0004 ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 ותקן את הלשון כך: \u0003ישראל היו משמרין אותה משעה שנוצרה\u0004 במעי אמה, ולא נרבעה אמה.","ומקשים: \u0003וניחוש דלמא רבעוה לאמא מעיקרא\u0004 \u0005[ו\u0006עדיין יש \u0005לחשוש שמא רבעו את האם מתחילה]\u0006 לפני שנתעברה, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003כל הפסולין לגבי מזבח\u0004 כגון הנעבד והנרבע — \u0003ולדותיהן\u0004 שנתעברו בהם לאחר מכן, \u0003מותרין, ותני עלה\u0004 \u0005[ושנויה\u0006 ברייתא \u0005עליה]\u0006 ש\u0003ר' אליעזר אוסר\u0004 בזה, ואם כן ר' אליעזר צריך לאסור גם בפרה אדומה זו שמא רבעו את אמה!","ומעירים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003רבא,\u0004 ש\u0003אמר רבא אמר רב נחמן: מחלוקת\u0004 זו, בין ר' אליעזר וחכמים, היא \u0003כשנרבעו כשהן מוקדשין\u0004 שאז אוסר ר' אליעזר את הוולדות שנתעברו בהם לאחר מכן, \u0003אבל\u0004 כשנעשתה בהן עבירה \u0003כשהן חולין\u0004 — \u0003דברי הכל מותרין\u0004 הולדות,","\u0003אלא ל\u0004דעת \u0003רב הונא בר חיננא אמר רב נחמן\u0004 שאמר: \u0003מחלוקת כשנרבעו כשהן חולין, אבל כשהן מוקדשין\u0004 — \u0003דברי הכל אסורין, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 מדוע לא אסר ר' אליעזר?","ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 כך: \u0003ישראל היו משמרין אותה\u0004 אף \u0003לאמא\u0004 של פרה אדומה זו \u0003משעה שנוצרה. ו\u0004שואלים: מכל מקום \u0003ניחוש דילמא רבעוה לאמא דאמא\u0004 \u0005[ו\u0006עדיין יש \u0005לחשוש שמא רבעו את האם של האם]!\u0006 ודוחים: \u0003כולי האי לא חיישינן\u0004 \u0005[כל זאת\u0006 (עד לדור שלישי) \u0005אין אנו חוששים].\u0006","ודנים בתירוץ ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003ישראל היו משמרין אותה משעה שנוצרה.\u0004 ושואלים: \u0003מנא ידעינן\u0004 \u0005[מנין אנו יודעים]\u0006 שתיוולד פרה אדומה, כדי שישמרוה? \u0003אמר רב כהנא: כוס אדום מעבירין לפניה\u0004 של הפרה האם \u0003בשעה שעולה עליה זכר,\u0004 ועל ידי כך הוולד הנוצר יהיה גם כן אדום.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שיש אופן פשוט שכזה ליצירת פרה אדומה, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003דמיה\u0004 של פרה אדומה \u0003יקרין\u0004 כל כך? ודוחים: עדיין פרה אדומה כשרה דבר נדיר הוא, \u0003הואיל ושתי שערות\u0004 בצבע אחר \u0003פוסלות בה,\u0004 ולא כל פרה נעשית אדומה בשלימות. ועוד שואלים: \u0003ומאי שנא דידהו\u0004 \u0005[מה שונה\u0006 פרה \u0005שלהם]\u0006 של הגוים שהוצרכו לקנות מהם פרה אדומה, אם יש דרך לעשות כן גם בשל ישראל? \u0003אמר רב כהנא:\u0004 אצל דמא בן נתינה מדובר היה \u0003במוחזקת,\u0004 שהיתה בידו משפחת פרות שהיתה מוחזקת שהיא יולדת וולדות אדומים בדרך זו.","מסופר: \u0003יתיב\u0004 \u0005[ישבו]\u0006 \u0003ר' אמי ור' יצחק נפחא אקלעא\u0004 \u0005[על המרפסת]\u0006 של \u0003ר' יצחק נפחא, פתח חד מינייהו\u0004 \u0005[אחד מהם]\u0006 \u0003ואמר: וכן היה ר' אליעזר פוסל\u0004 בהמות שנלקחו מן הגוים \u0003בכל הקרבנות כולן,\u0004 משום חשש רביעה.","\u0003פתח אידך מינייהו\u0004 \u0005[האחר מהם]\u0006 \u0003ואמר: מאי אותיבו ליה חברוהי\u0004 \u0005[מה השיבו,\u0006 הקשו \u0005לו חביריו]\u0006 \u0003לר' אליעזר?\u0004 והרי ישעיהו מנבא שלעתיד לבוא \u0003\"כל צאן קדר יקבצו לך\" וגו'\u0004 (ישעיהו ס, ז), אם כן לוקחים קרבנות מן הגוים! \u0003אמר להן ר' אליעזר:\u0004 כל הגוים \u0003כולם גרים גרורים הם לעתיד לבא,\u0004 וממילא לא יהיה עוד חשש שרבעו את בהמותיהם.","\u0003אמר רב יוסף: מאי קרא\u0004 \u0005[מה המקרא]\u0006 המלמד שכולם יתגיירו לעתיד לבוא? שנאמר: \u0003\"כי אז אהפך אל עמים שפה ברורה\u0004 לקרוא כולם בשם ה' \" (צפניה ג, ט). \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ודלמא\u0004 \u0005[ושמא]\u0006 \u0003מעבודה זרה\u0004 בלבד \u0003הוא דהדור בהו\u0004 \u0005[שחוזרים בהם]\u0006 הגוים לעתיד לבוא, אבל לא משאר עבירות, כגון רביעה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף:\u0004 הרי \u0003\"לעבדו שכם אחד\" כתיב\u0004 \u0005[נאמר]\u0006 (צפניה ג, ט), משמע שכולם יקבלו על עצמם את כל המצוות כישראל.","\u0003רב פפא מתני הכי\u0004 \u0005[היה שונה כך],\u0006 כפי שאמרנו. \u0003ורב זביד מתני הכי\u0004 \u0005[היה שונה כך],\u0006 בנוסח אחר, שלא היו ר' אמי ור' יצחק נפחא מדברים אחר זה, אלא \u0003ותרוייהו אמרי\u0004 \u0005[ושניהם אמרו]:\u0006 \u0003וכן היה ר' אליעזר פוסל בכל הקרבנות, ותרוייהו אמרי\u0004 \u0005[ושניהם אמרו]:\u0006 \u0003ומאי אותיבו ליה חברוהי\u0004 \u0005[ומה השיבו,\u0006 הקשו \u0005לו חביריו]\u0006 \u0003לר' אליעזר? \"כל צאן קדר יקבצו לך\" וגו'\u0004 ואת התשובה \u0003אמר ר' אליעזר: כולם גרים גרורים הם לעתיד לבא.\u0004","ושניהם אמרו: \u0003ומאי קראה\u0004 \u0005[ומה המקרא]\u0006 המלמד על כך? \u0003\"כי אז אהפך אל עמים שפה ברורה לקרא כלם בשם ה'\". מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף: ודלמא\u0004 \u0005[ושמא]\u0006 \u0003מעבודה זרה\u0004 בלבד \u0003הוא דהדרי בהו\u0004 \u0005[שחוזרים בהם]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: \"לעבדו שכם אחד\" כתיב\u0004 \u0005[נאמר].\u0006","על הסברה האוסרת לקחת קרבנות מגוים, \u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 \u0003\"ויאמר משה גם אתה תתן בידנו זבחים ועלת\"\u0004 (שמות י, כה), ואם לוקחים זבחים מפרעה, משמע שאפשר לקחת זבחים ועולות מגוי! ומשיבים: \u0003קודם מתן תורה שאני\u0004 \u0005[שונה],\u0006 שעדיין לא נאסר הדבר.","ומקשים עוד, \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ממה שנאמר: \u0003\"ויקח יתרו חתן משה עלה וזבחים לאלהים\"\u0004 (שמות יח, יב)! ודוחים: מעשה \u0003יתרו נמי\u0004 \u0005[גם כן]\u0006 \u0003קודם מתן תורה הוה\u0004 \u0005[היה].\u0006 ומקשים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח\u0006 \u0005למי שאומר]:\u0006 בואו של \u0003יתרו\u0004 למשה \u0003קודם מתן תורה הוה\u0004 \u0005[היה],\u0006 כסדר הפרשה. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]:\u0006"],["\u0003יתרו לאחר מתן תורה הוה\u0004 \u0005[היה]\u0006 \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי אסור היה לקבל ממנו! \u0003אלא,\u0004 יש לומר כי \u0003יתרו מישראל זבן\u0004 \u0005[קנה]\u0006 את הבהמות לקרבן.","ומציעים ראיה, \u0003תא שמע\u0004 \u0005[בוא ושמע]:\u0006 \u0003\"ויאמר שאול מעמלקי הביאום אשר חמל העם על מיטב הצאן והבקר למען זבח לה' אלהיך\"\u0004 (שמואל א טו, טו), משמע שאפשר להקריב בהמות של גוים! ומשיבים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"מיטב\"?\u0004 לא שהשתמשו במיטב הבהמות עצמן, אלא ב\u0003דמי מיטב\u0004 הבהמות, שמכרון ובדמיהן הביאו קרבנות.","ושואלים: \u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 מדוע דווקא \u0003מיטב?\u0004 מדוע מכרו דווקא מן המיטב? ומשיבים: \u0003כי היכי דליקפץ עליהן זבינא\u0004 \u0005[כדי שיקפצו עליהם קונים]\u0006 על הבהמות הללו שהם מוכרים, שהכל רוצים לקנות מן המיטב.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא ושמע]:\u0006 \u0003\"ויאמר ארונה אל דוד יקח ויעל אדני המלך הטוב בעינו [ראה] הבקר לעלה והמרגים וכלי הבקר לעצים\"\u0004 (שמואל ב כד, כב), הרי אפשר להשתמש בבהמת גוי לקרבן! \u0003אמר רב נחמן: ארונה גר תושב היה,\u0004 שקיבל על עצמו שבע מצוות בני נח, ובכללן איסור רביעת בהמה, ולכן מותר היה לקבל ממנו בהמות לקרבן.","אגב הזכרת הפסוק שואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"מורגים\"? אמר עולא: מטה של טורביל.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003מטה של טורביל?\u0004 שמונח זה לא היה ידוע בבבל; ומשיבים: \u0003עיזא דקורקסא דדיישן\u0004 \u0005[לוח כבד ומשונן שדשות\u0006 בו הבהמות\u0005].\u0006 \u0003אמר רב יוסף: מאי קרא\u0004 \u0005[מהו המקרא]\u0006 שממנו אפשר ללמוד שזה פירוש \"מוריגים\"? שנאמר: \u0003\"הנה שמתיך למורג חרוץ חדש בעל פיפיות תדוש הרים ותדק וגבעות כמץ תשים\"\u0004 (ישעיהו מא, טו), הרי שמורג יש בו חריצים (\"חרוץ\") ושיניים (\"פיפיות\"), והוא משמש לדישה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה שמסופר כי לאחר ששלחו פלישתים את ארון הברית על ידי פרות וחזר לישראל — \u0003\"ואת הפרות העלו עלה לה'\"\u0004 (שמואל א ו, יד)! ומשיבים: \u0003הוראת שעה היתה\u0004 זו שהקריבום.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 שהיתה זו הוראת שעה, \u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כך],\u0006 \u0003עולה נקבה מי איכא\u0004 \u0005[האם יש]?\u0006 והרי אין מקריבים עולה אלא מן הזכרים, וכאן מדובר בפרות!","ודוחים את הראיה הזו: \u0003ומאי קושיא\u0004 \u0005[ומה קושיה\u0006 היא זו\u0005]?\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003בבמת יחיד\u0004 היה הדבר, \u0003וכדרב אדא בר אהבה,\u0004 ש\u0003אמר רב אדא בר אהבה: מנין לעולה נקבה שהיא כשרה בבמת יחיד? שנאמר: \"ויקח שמואל טלה חלב אחד ויעלהו עולה\"\u0004 (שמואל א ז, ט), ו\"טלה חלב\" מבינים כטלה שנותן חלב, כלומר נקבה.","ומקשים: הרי לשון \u0003\"ויעלהו\"\u0004 האמורה בענין זה \u0003זכר משמע! אמר רב נחמן בר יצחק: \"ויעלה\" כתיב\u0004 \u0005[כתוב]\u0006 במקרא, והיא לשון נקבה.","ועוד בישוב הסתירה שבין משנתנו, לפיה גוים חשודים על הרביעה, לבין הברייתא שהתירה לקחת מהם בהמה לקרבן, \u0003ר' יוחנן אמר:\u0004 \u0003גבול יש לה\u0004 לבהמה, אם היא \u0003פחותה מבת שלש שנים\u0004 — הרי היא \u0003נעקרת\u0004 (נעשית עקרה) על ידי רביעת אדם, אם היא \u0003בת שלש שנים\u0004 — \u0003אינה נעקרת,\u0004 ומה שהתירה הברייתא לקחת מן הגוים הרי זו בהמה פחותה משלוש שנים, שוודאי לא רבעוה, מחשש שתיעקר בכך.","\u0003איתיביה\u0004 \u0005[הקשו]\u0006 לו \u0003כל הני תיובתא\u0004 \u0005[אותן הקושיות\u0006 שהקשינו\u0005],\u0006 שמביאים קרבנות מן הגוים, \u0003שני להו\u0004 \u0005[\u0006ו\u0005תירץ להם]\u0006 שהכל מדובר ב\u0003פחותה מבת שלש שנים.\u0004 ומקשים עוד, \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 מן הכתוב \"ואת הפרות העלו עלה לה'\" (שמואל א ו, יד)! ומתרצים: מדובר \u0003בפחותה מבת שלש שנים.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן: אם כן, היינו\u0004 \u0005[זהו]\u0006 שכתוב \u0003\"ואת בניהם כלו בבית\"\u0004 (שמואל א ו, י), ואתה טוען שמדובר ב\u0003פחותה מבת שלש שנים,\u0004","\u0003ופחותה מבת שלש שנים מי קא ילדה\u0004 \u0005[האם היא יולדת]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003פרה וחמור\u0004 שנקנו מן הגוי, ולא ידוע אם כבר ילדה הבהמה, אם היתה בהמה זו \u0003מבת שלש\u0004 בשנתה השלישית וילדה זכר, — הריהו \u0003ודאי לכהן,\u0004 שהוא ודאי בכור, לפי שאין פרה יולדת בפחות מבת שלוש, \u0003מכאן ואילך,\u0004 אם קנה אותה מבוגרת מבת שלוש שנים, \u0003ספק\u0004 הוא אם ולד זה בכור או אינו בכור! \u0003אלא, מחוורתא כדשנין מעיקרא\u0004 \u0005[מחוור,\u0006 ברור \u0005כמו שתירצנו מתחילה],\u0006 שהוראת שעה היתה.","כיון שהוזכר ענין זה של הפרות שהביאו הפלישתים, דנים עוד בענין זה. נאמר שם: \u0003\"וישרנה הפרות בדרך על דרך בית שמש\" וגו'\u0004 (שמואל א, ו, יב), \u0003מאי\u0004 \u0005[מה]\u0006 פירוש המלה \u0003\"וישרנה\"? אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' מאיר: שאמרו שירה. ורב זוטרא בר טוביה אמר רב: שישרו פניהם כנגד ארון ואמרו שירה.\u0004","\u0003ומאי\u0004 \u0005[ומה]\u0006 \u0003שירה אמרו? אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' מאיר: \"אז ישיר משה ובני ישראל\"\u0004 (שמות טו, א ואילך). \u0003ור' יוחנן דידיה\u0004 \u0005[משלו,\u0006 משל עצמו\u0005]\u0006 \u0003אמר\u0004 שהשירה היתה: \u0003\"ואמרתם ביום ההוא הודו לה' קראו בשמו\u0004 הודיעו בעמים עלילותיו\"","(ישעיהו יב, ד). \u0003ור' שמעון בן לקיש אמר: מזמורא יתמא\u0004 \u0005[המזמור היתום]\u0006 כלומר, מזמור שלא נזכר שם אומרו, וגם לא על איזה אירוע נאמר: \u0003\"מזמור שירו לה' שיר חדש כי נפלאות עשה הושיעה לו ימינו וזרוע קדשו\"\u0004 (תהלים צח, א ואילך). \u0003ר' אלעזר אמר,\u0004 מזמור זה אמרו: \u0003\"ה' מלך ירגזו עמים\"\u0004 (תהלים צט, א ואילך).","\u0003ר' שמואל בר נחמני אמר: \"ה' מלך גאות לבש\"\u0004 (תהלים צג, א ואילך). \u0003ר' יצחק נפחא אמר,\u0004 שכך היתה שירתן: \u0003\"רוני רוני השיטה\u0004 (רמז לארון הברית שעשוי היה מעצי שיטים) \u0003התנופפי ברוב הדרך, המחושקת בריקמי זהב\u0004 (שהארון היה מצופה זהב) \u0003המהוללה בדביר ארמון\u0004 (בספר התורה שבו), \u0003ומפוארה בעדי עדיים\".\u0004","\u0003רב אשי מתני לה להא\u0004 \u0005[היה שונה את זו]\u0006 השירה שאמר \u0003ר' יצחק, אהא\u0004 \u0005[על זה],\u0006 שנאמר: \u0003\"ויהי בנסע הארן ויאמר משה קומה ה'\"\u0004 (במדבר י, לה), ושואלים: \u0003ישראל מאי\u0004 \u0005[מה]\u0006 \u0003אמרו\u0004 באותה שעה? \u0003אמר ר' יצחק: \"רוני רוני השיטה\"\u0004","\u0003אמר רב: כמאן קרו פרסאי לספרא\u0004 \u0005[כמי\u0006 על סמך מה \u0005קוראים הפרסיים לספר]\u0006 \u0003\"דביר\"? מהכא\u0004 \u0005[מכאן],\u0006 שנאמר: \u0003\"ושם דביר לפנים קרית ספר\"\u0004 (שופטים א, יא) — הרי שדביר קשור לספר.","\u0003רב אשי אמר: כמאן קרו פרסאי\u0004 \u0005[כמי,\u0006 על סמך מה \u0005קוראים הפרסיים]\u0006 \u0003לנידה \"דשתנא\"? מהכא\u0004 \u0005[מכאן],\u0006 שנאמר: \u0003\"כי דרך נשים לי\"\u0004 (בראשית לא, לה), ו\"דשתנא\" הוא כעין קיצור של מילים אלה."],["נאמר: \u0003\"וידם השמש וירח עמד עד יקם גוי איביו הלא היא כתובה על ספר הישר\"\u0004 (יהושע י, יג), \u0003מאי\u0004 \u0005[מה]\u0006 הוא אותו \u0003\"ספר הישר\"? אמר ר' חייא בר אבא אמר ר' יוחנן: זה ספר אברהם יצחק ויעקב\u0004 (כלומר, ספר בראשית) ונקרא כך משום \u0003ש\u0004האבות \u0003נקראו \"ישרים\", שנאמר\u0004 בדברי בלעם: \u0003\"תמת נפשי מות ישרים\"\u0004 (במדבר כג, י), שביקש שתהא אחריתו כמותם.","ושואלים: \u0003והיכא רמיזא\u0004 \u0005[והיכן נרמז]\u0006 ענין זה בספר בראשית שהשמש תעמוד ליהושע? שנאמר בברכת יעקב לאפרים: \u0003\"וזרעו יהיה מלא הגוים\"\u0004 (בראשית מח, יט), \u0003[אימתי יהיה\u0004 איש מזרע אפרים \u0003מלא הגוים],\u0004 שיהיה ידוע בכל העולם? \u0003בשעה שעמדה לו חמה ליהושע\u0004 שהוא משבט אפרים. באותו פסוק שבספר יהושע נאמר עוד: \u0003\"ויעמד השמש בחצי השמים ולא אץ לבוא כיום תמים\"\u0004 (יהושע י, יג),","\u0003וכמה\u0004 זמן עד ששקעה? \u0003אמר ר' יהושע בן לוי: עשרים וארבעה [שעי\u0004 \u0005[שעות]\u0006\u0003],\u0004 וכך היה הדבר: \u0003אזיל שית וקם שית, אזיל שית וקם שית\u0004 \u0005[הלכה\u0006 מהלך \u0005שש\u0006 שעות \u0005ועמדה שש, הלכה שש ועמדה שש],\u0006 שזרחה השמש ועלתה כרגיל עד חצי היום, ואז עמדה שש שעות (\"ויעמד השמש בחצי השמים\") ולאחר מכן שקעה השמש כרגיל, ולפני שקיעתה עמדה שוב שש שעות (\"ולא אץ לבוא\"), ונמצא \u0003כולה מלתא\u0004 \u0005[כל הדבר\u0006 כולו\u0005]\u0006 היה \u0003כיום תמים,\u0004 שהוא עשרים וארבע שעות.","\u0003ר' אלעזר אמר: שלשים ושית\u0004 \u0005[ושש]\u0006 שעות היה המעשה, כיצד? \u0003אזיל שית וקם תריסר\u0004 \u0005[הלכה שש\u0006 שעות \u0005ועמדה שתים עשרה],\u0006 \u0003אזיל שית וקם תריסר\u0004 \u0005[הלכה שש ועמדה שתים עשרה],\u0006 \u0003עמידתו\u0004 (\"ויעמוד השמש\") היתה עשרים וארבע שעות \u0003כיום תמים,\u0004 והליכתו שתים עשרה. ואילו \u0003ר' שמואל בר נחמני אמר: ארבעים ושמונה\u0004 שעות נמשך הכל, \u0003אזיל שית וקם תריסר\u0004 \u0005[הלכה שש ועמדה שתים עשרה],\u0006 \u0003אזיל שית וקם\u0004 \u0005[הלכה שש ועמדה]\u0006 \u0003עשרים וארבעה, [שנאמר]\u0004 בתחילה: \"ויעמוד השמש בחצי השמים\", ואחר כך נאמרה עמידה נוספת: \u0003\"ולא אץ לבוא כיום תמים\", מכלל דמעיקרא\u0004 \u0005[שמתחילה]\u0006 בעמידה ראשונה \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כיום תמים [הוה\u0004 \u0005[היה]\u0006\u0003]\u0004 אלא פחות מכן, שתים עשרה שעות.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שדברים אלה לא נאמרו לגבי אורך המאורע כולו, אלא \u0003בתוספתא\u0004 \u0003פליגי\u0004 \u0005[בתוספת\u0006 שנוסף היום \u0005נחלקו]\u0006 חכמים, ש\u0003ר' יהושע בן לוי אמר: עשרים וארבעה\u0004 שעות נוספו לאותו יום, כיצד? \u0003אזיל שית וקם תריסר, אזיל שית וקם תריסר\u0004 \u0005[הלכה שש ועמדה שתים עשרה, הלכה שש ועמדה שתים עשרה],\u0006 \u0003עמידתו\u0004 של השמש \u0003כיום תמים. ר' אלעזר אמר: שלשים ושש,\u0004 כיצד? \u0003אזיל שית וקם תריסר\u0004 \u0005[הלכה שש ועמדה שתים עשרה],\u0006 \u0003אזיל שית וקם\u0004 \u0005[הלכה שש ועמדה]\u0006 \u0003עשרים וארבעה,\u0004 ועל עמידת השמש השניה הוא שנאמר \u0003\"ולא אץ לבוא כיום תמים\".\u0004","\u0003ר' שמואל בר נחמני אמר: ארבעים ושמונה\u0004 שעות היו בתוספת, \u0003אזיל שית וקם\u0004 \u0005[הלכה שש ועמדה]\u0006 \u0003עשרים וארבעה, אזיל שית וקם\u0004 \u0005[הלכה שש ועמדה]\u0006 \u0003עשרים וארבעה,\u0004 וטעמו: \u0003מקיש\u0004 (משוה) הכתוב \u0003עמידתו\u0004 (\"ויעמוד השמש\") \u0003לביאתו\u0004 (\"ולא אץ לבוא\"), ששניהם כתובים יחד, \u0003מה ביאתו\u0004 של השמש היא \u0003כיום תמים, אף עמידתו\u0004 היתה \u0003כיום תמים.\u0004","\u0003תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003כשם שעמדה לו חמה ליהושע, כך עמדה לו חמה למשה ולנקדימון בן גוריון.\u0004 ומסבירים: בענין \u0003יהושע\u0004 — \u0003קראי\u0004 \u0005[מקראות\u0006 מפורשים הם\u0005].\u0006 בענין \u0003נקדימון בן גוריון, גמרא\u0004 \u0005[מסורת]\u0006 היא. \u0003למשה מנלן\u0004 \u0005[מנין לנו]\u0006 שעמדה השמש? \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד הדבר\u0005]\u0006 בגזירה שווה של \u0003\"אחל\" \"אחל\", כתיב הכא\u0004 \u0005[נאמר כאן\u0006 במשה\u0005]:\u0006 \u0003\"אחל תת פחדך\u0004 ויראתך על פני העמים תחת כל השמים\" (דברים ב, כה), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 \u0003ביהושע: \"אחל גדלך\"\u0004 (יהושע ג, ז).","\u0003ור' יוחנן אמר: אתיא\u0004 \u0005[בא,\u0006 נלמד הדבר\u0005]\u0006 בגזירה שווה של המילים \u0003\"תת\" \"תת\", כתיב הכא\u0004 \u0005[נאמר כאן\u0006 במשה\u0005]:\u0006 \u0003\"אחל תת פחדך\", וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003ביהושע\u0004 בקשר לאותו מעשה: \u0003\"ביום תת ה' את האמרי\"\u0004 (יהושע י, יב).","\u0003ר' שמואל בר נחמני אמר, מגופיה דקרא שמעת ליה\u0004 \u0005[מגופו של המקרא אתה לומד זאת],\u0006 שנאמר: \"אחל תת פחדך ויראתך על פני כל העמים \u0003אשר ישמעון שמעך ורגזו וחלו מפניך\"\u0004 (דברים ב, כה), \u0003אימתי\u0004 מתקיים \u0003\"רגזו וחלו מפניך\u0004 כל העמים\"? \u0003בשעה שעמדה לו חמה למשה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]:\u0006 הרי נאמר בסוף המעשה של יהושע בעמידת השמש: \u0003\"ולא היה כיום ההוא לפניו ואחריו\"\u0004 (יהושע י, יד)! ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003שעות\u0004 עמידת השמש אצל משה \u0003הוא\u0004 ש\u0003לא הוו נפיש כולי האי\u0004 \u0005[היו מרובות כל כך],\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003אבני ברד לא הוו\u0004 \u0005[היו]\u0006 באותו נס של משה, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 ביהושע: \u0003\"ויהי בנסם מפני בני ישראל הם במורד בית חורן וה' השליך עליהם אבנים גדלות מן השמים עד עזקה וימתו\"\u0004 (דברים י, יא).","ועוד מחלוקת בפירוש הביטוי \"ספר הישר\", \u0003כתיב\u0004 \u0005[נאמר]\u0006 בקינת דוד על שאול ויהונתן: \u0003\"ויאמר ללמד בני יהודה קשת הנה כתובה על ספר הישר\"\u0004 (שמואל ב א, יח), ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 הוא אותו \u0003\"ספר הישר\"? אמר ר' חייא בר אבא אמר ר' יוחנן: זה ספר אברהם יצחק ויעקב\u0004 (ספר בראשית) \u0003שנקראו \"ישרים\", דכתיב בהו\u0004 \u0005[שנאמר בהם]\u0006 בדברי בלעם: \u0003\"תמת נפשי מות ישרים ותהי אחריתי כמוהו\"\u0004 (במדבר כג, י).","\u0003והיכא רמיזא\u0004 \u0005[והיכן נרמז\u0006 הדבר\u0005]\u0006 בספר בראשית? שנאמר: \u0003\"יהודה אתה יודוך אחיך ידך בערף איביך\"\u0004 (בראשית מט, ח), \u0003ואיזו היא מלחמה שצריכה יד כנגד עורף\u0004 שיד אחת של הלוחם נמצאת סמוך לעורפו? \u0003הוי אומר: זו\u0004 יריה ב\u0003קשת\u0004 כשהוא מותח אותה לאחוריו, ועל זה נאמר \"ללמד בני יהודה קשת\".","\u0003ר' אלעזר אומר:\u0004 \"ספר הישר\" \u0003זה ספר משנה תורה\u0004 (ספר דברים), \u0003ואמאי קרו ליה\u0004 \u0005[ומדוע קוראים לו]\u0006 \u0003\"ספר הישר\"? דכתיב\u0004 \u0005[שנאמר\u0006 בו\u0005]:\u0006 \u0003\"ועשית הישר והטוב בעיני ה'\"\u0004 (דברים ו, יח). \u0003והיכא רמיזא\u0004 \u0005[והיכן נרמז]\u0006 בספר דברים שיש ללמד את בני יהודה קשת? שנאמר בברכה לשבט יהודה \u0003\"ידיו רב לו\"\u0004 (דברים לג, ז), \u0003ואיזו היא מלחמה שצריכה שתי ידים\u0004 (שנאמר \"ידיו\")? \u0003הוי אומר: זו קשת.\u0004","\u0003ר' שמואל בר נחמני אמר:\u0004 \"ספר הישר\" \u0003זה ספר שופטים, ואמאי קרו ליה\u0004 \u0005[ומדוע קוראים לו]\u0006 \u0003\"ספר הישר\"? דכתיב\u0004 \u0005[שנאמר\u0006 בו\u0005]:\u0006 \u0003\"בימים ההם אין מלך בישראל איש הישר בעיניו יעשה\"\u0004 (שופטים יז, ו). \u0003והיכא רמיזא\u0004 \u0005[והיכן נרמז\u0006 הדבר\u0005]\u0006 בספר שופטים? \"ואלה הגוים אשר הניח ה'... \u0003למען דעת דרות בני ישראל ללמדם מלחמה\"\u0004 (שופטים ג, ב), \u0003ואיזו היא מלחמה שצריכה לימוד,\u0004 שאדם צריך ללמוד אותה? \u0003הוי אומר: זו\u0004 ירית \u0003קשת.\u0004","\u0003ומנלן\u0004 \u0005[מנין לנו]\u0006 ש\u0003ביהודה כתיב\u0004 \u0005[נאמר]\u0006 הדבר? \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בתחילת ספר שופטים: \u0003\"מי יעלה לנו בתחלה אל הכנעני...\u0004 \u0003להלחם בו, ויאמר ה' יהודה יעלה\"\u0004 (שופטים א, א —ב), הרי שהם היו הראשונים להילחם.","ועוד מביאים מחלוקת של אותם אמוראים בפירושו של פסוק אחר: \u0003\"וירם הטבח את השוק\u0004 \u0003והעליה וישם לפני שאול\"\u0004 (שמואל א ט, כד), \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \"השוק \u0003והעליה\"? ר' יוחנן אומר: שוק ואליה\u0004 (זנב הכבש), ולפי זה \u0003מאי\u0004 \u0005[מה]\u0006 משמעות הלשון \u0003\"והעליה\"? דמסמכא\u0004 \u0005[שסומכת]\u0006 ה\u0003שוק לאליה\u0004 שהאליה מונחת על השוק.","\u0003ור' אלעזר אומר: שוק וחזה,\u0004 ולפי זה \u0003מאי\u0004 \u0005[מה]\u0006 מובן \u0003\"והעליה\"\u0004 — \u0003דמחית לה לחזה עילויה דשוק כי בעי\u0004 \u0003אנופי, ומנפי ליה\u0004 \u0005[שמניח את החזה על גבי השוק כאשר צריכים הנפה,\u0006 \u0005ומניפים אותו\u0006 ביחד עמו\u0005].\u0006 \u0003ור' שמואל בר נחמני אמר:\u0004 \u0003שוק ושופי\u0004 (עובי בשר הירך) שמסביב, ולפי זה \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"והעליה\"?\u0004 הכוונה היא ש\u0003שופי עילויה דשוק קאי\u0004 \u0005[על גבי השוק נמצא],\u0006 ולכן הוא נקרא \"העליה\".","וחוזרים לפירוש המשנה, ששנינו: \u0003לא תתייחד אשה עמהם\u0004 עם הגוים. ושואלים: \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]?\u0006 \u0003אילימא בחד\u0004 \u0005[אם תאמר ב\u0006איש \u0005אחד],\u0006 \u0003דכוותה\u0004 \u0005[שכיוצא בה]\u0006 ל\u0003גבי\u0004 אדם מ\u0003ישראל מי שרי\u0004 \u0005[האם מותר\u0006 להתייחד\u0005]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003לא יתייחד איש אחד\u0004 אפילו \u0003עם שתי נשים!\u0004"],["\u0003אלא\u0004 נאמר שמדובר \u0003בתלתא\u0004 \u0005[בשלושה],\u0006 יש לשאול: מדוע מדובר דווקא בגוים? \u0003דכוותה\u0004 \u0005[כיוצא בה]\u0006 ל\u0003גבי ישראל\u0004 אם היו הם \u0003פרוצים מי שרי\u0004 \u0005[האם מותר\u0006 להתייחד עימם\u0005]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנויה\u0006 במשנה\u0005]\u0006 לגבי ישראל: \u0003אבל אשה אחת מתייחדת עם שני אנשים, ו\u0004על כך \u0003אמר רב יהודה אמר שמואל: לא שנו אלא ב\u0004אנשים \u0003כשרים, אבל בפרוצים אפילו עשרה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא, מעשה היה והוציאוה\u0004 אל מחוץ לעיר לאישה אחת \u0003עשרה\u0004 גברים \u0003במטה,\u0004 שהעמידו פנים כאילו הם מוליכים אותה לקבורה, ולאחר מכן כולם חטאו איתה!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו במשנה אלא כשהיתה \u0003אשתו עמו\u0004 עם הגוי, שבישראל לא נאסר הדבר. וטעם הדבר: \u0003גוי אין אשתו משמרתו\u0004 שלא יזנה עם נשים אחרות, \u0003אבל ישראל אשתו משמרתו.\u0004 שנינו במשנה שטעם האיסור לאשה להתייחד עם גוי הוא חשד לעריות.","ושואלים: \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 הלכה זו מטעם אחר, שהרי יש לחשוש \u0003משום שפיכות דמים\u0004 שמא יהרגו אותה! \u0003אמר ר' ירמיה: באשה חשובה עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003דמירתתי מינה\u0004 \u0005[שמפחדים ממנה]\u0006 ולכן לא יהרגוה, אבל איסור יחוד יש בה. \u0003רב אידי אמר: אשה כלי זיינה עליה\u0004 הנשק שלה נמצא עליה, שלאשה יש הגנה שלא יהרגוה מעצם היותה אשה, ולכן מצד אחד יש לחשוש לאונס או לפיתוי, אך מצד אחר אין דרך להרוג אותה.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 אם הטעם הוא זה או זה? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]:\u0006 כאשר היתה זו \u0003אשה\u0004 ש\u0003חשובה בין אנשים\u0004 מפני שקרובה למלכות, \u0003ושאינה חשובה בין הנשים\u0004 שאינה יפה, שאשה כזו, לדעת ר' ירמיה אין בה חשש לא משום שפיכות דמים ולא משום עריות, ולדעת רב אידי — בכל אשה יש לחשוש משום עריות.","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב אידי בר אבין: האשה אף על פי שהשלום עמה\u0004 ואין לחשוש שיהרגו אותה — \u0003לא תתייחד עמהן, מפני שחשודין על העריות.\u0004","שנינו במשנה: \u0003לא יתייחד אדם עמהן\u0004 מפני שחשודים על שפיכות דמים. באותו ענין \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ישראל שנזדמן לו גוי בדרך\u0004 והם הולכים יחד — \u0003טופלו לימינו,\u0004 ידאג שיהא הגוי מהלך לימינו, ובאופן זה יוכל הישראלי לדאוג לכך (ביד ימינו) שהגוי לא יוכל לפגוע בו. \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה אומר:\u0004 יש להבחין, אם היה הגוי מזויין \u0003בסייף\u0004 — \u0003טופלו לימינו,\u0004 שהחרב נמצאת כרגיל בשמאלו של אדם, וכך יוכל הישראלי למונעו מלשולפה. אם היה הגוי מזויין \u0003במקל\u0004 — \u0003טופלו לשמאלו\u0004 שתהא ידו סמוך ליד ימין של הגוי, שהיא מחזיקה באופן קבוע במקל.","\u0003היו עולין במעלה או יורדין בירידה, לא יהא ישראל למטה וגוי למעלה,\u0004 שלא יהא עליו בעמדת יתרון אם ירצה להתקיפו, \u0003אלא ישראל למעלה וגוי למטה. ואל ישוח\u0004 (יתכופף) הישראלי \u0003לפניו, שמא ירוץ\u0004 (ישבור) \u0003את גולגלתו.\u0004","אם \u0003שאלו\u0004 הגוי \u0003להיכן\u0004 הוא \u0003הולך\u0004 — \u0003ירחיב לו את הדרך\u0004 כלומר, יאמר לו מקום מרוחק יותר מהמקום שבאמת אליו הוא הולך, כדי שאם ירצה להרע לו יחשוב שיש בידו זמן מרובה יותר לעשות זאת. והוא \u0003כדרך שעשה יעקב אבינו לעשו הרשע, [דכתיב\u0004 \u0005[שנאמר]\u0006\u0003]\u0004 שאמר לו יעקב: \u0003\"עד אשר אבא אל אדני שעירה\"\u0004 (בראשית לג, יד),","\u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויעקב נסע סכתה\"\u0004 (בראשית לג, יז), כלומר שאמר לו שנוסע הוא לשעיר, אף שבפועל נסע רק עד סכות.","בענין זה מסופר, \u0003מעשה בתלמידי ר' עקיבא שהיו הולכים לכזיב, פגעו בהן ליסטים\u0004 (שודדים), \u0003אמרו להן\u0004 הלסטים: \u0003לאן אתם הולכים? אמרו להן\u0004 שהם הולכים \u0003לעכו,\u0004 שהיתה רחוקה יותר מייעדם האמיתי. \u0003כיון שהגיעו לכזיב פירשו\u0004 ונכנסו לעיר. \u0003אמרו להן\u0004 הליסטים: \u0003[תלמידי] מי אתם? אמרו להן: תלמידי ר' עקיבא\u0004 אנו, \u0003אמרו להן: אשרי ר' עקיבא ותלמידיו, שלא פגע בהן אדם רע מעולם,\u0004 שהבינו שמדברי רבם למדו דבר זה.","מסופר, \u0003רב מנשה הוה אזל\u0004 \u0005[היה הולך]\u0006"]]};
